/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20030307-3","meetingId":"h15-c-budget","date":"2003年3月7日","dateIso":"2003-03-07","committee":"予算特別委員会","time":"午前１０時１６分～午後５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を127件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中副委員長","kind":"質問・要望","question":"おはようあります。ご説明をします。予算特別委員会の運営につきましては、例年同様、お手元の資料のとおりですが、特にご確認をいただきたい点につきまして、ご説明いたします。審査日程につきましては、日程表のとおり、審査日数を８日間といたします。１人当たりの質問時間は、答弁時間も含めまして１０分、１５分、２０分のいずれかとし、その時間内で会派で割り振りをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"おはようあります。平成１５年の予算特別委員会の最初の質問をします。歳入の３８ページ、１款特別区税、４０ページの７款特別区財政調整交付金、５２ページの１７款諸収入、時間があったら歳出でもう１点、確認をさせていただきたいと思います。先ほど、再調整額の見合い額という説明がありましたけれども、この分の収入が固定資産税等の減免措置で９５億円減っている影響かどうか確認したいと思います。","respondent":"松崎税務課長、市岡企画財政課長","answer":"委員ご指摘のとおり、中堅ファミリー層が大幅に増えて、約2,０００名増えまして、大きく税収構造が変わり、納税義務者が増えて、今回の１５億円という補正をご審議いただくです。影響額が２３区に対して、確か約１０９億円というふうに言われています。ただ、今回は当初予算に比べると減額をしておりますが、再調整で若干プラスの再調整もありました。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"税のほうですが、査察額が相当大きかったということですか。というのは、１５億円で品川区の世帯数が増えた割合からすると、ものすごくバランスが大きいんです。１世帯当たり、そんなに突然大きくなったのかなと思ったので確認をしたんです。ですから、勤め人の方より事業者の方の転入が多かったのかなという、その辺の勘定もしているのかどうか、その辺もお願いしたい。","respondent":"松崎税務課長、市岡企画財政課長","answer":"１点目ですが、約１億7,０００万円が修正で構成された部分です。残りが中堅ファミリー層、普通徴収と特別徴収の差ということですが、特別徴収では６００名対前年で減っています。こういうことも本来の都区財政調整のあり方からすると疑問がありますので、やはり都区財政調整をもっと区の主体的な制度として改革をしていくように考えていかなければならないと考えております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"税収に関しては、ダブルカウントで入っている方が増えていることは、あまりこっちが増えていると、事業をやっている方の収入が増えてきているのかと、現実はそうではない状況において、品川区だけなぜこんなに数字が変わってくるのかなということの確認をしたかった点です。当然、担当の方が大変なことは十分承知の上ですが、その辺のご苦労と今後の回収について、もう一度お聞きしたいと思います。","respondent":"松崎税務課長、市岡企画財政課長","answer":"それによって、おそらく4,０００万円以上の対応が整理できる見通しというか、３月１０日に東京都から入ってくる予定になってありますので、滞納はさらにパーセンテージでは上げられるのではないかと、今のところ予想しています。この１４年度については、今税務課長が申し上げましたとおり、税が堅調であったために、一般財源の二つの柱である財調が落ちても、何とか計画的な事業が当初の計画どおり進められるという状況にありましたが。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１５年度、１６年度、１７年度ということで、新しく資料が出た中で、年間約１億円ちょっとの増額が区税の中に出ているのだと思うんです。財調の問題が大分絡んでくると思うので、その辺これからもご検討をよろしくお願いしたいと思います。なぜこれが減額になっていくのか、区のほうに諸収入に入っているのか、その辺の流れを教えていただきたいと思います。","respondent":"小野政策担当課長","answer":"これが順調に返済が進んでまいりまして、負債が減少してまいりましたので、過大な資本を抱えてよく必要がなくなったということで、資金的に可能な範囲で今回減資を行ったです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今までの流れの数字がわからないんですが、現在、(株)品川都市整備公社の資本金が５億1,６００万円、なぜ減資するのかという理由が、今の説明ではわかりにくかったんですが。では、なぜこの５％だけにするのか、もっと減資してもいいんじゃないかという、その辺の判断なんですが。","respondent":"小野政策担当課長","answer":"それぞれ現在資産金額では約５億円ほどの物件の価格になっておりますけれども、資金的にこれを減資をいたしますと、要するに株主に返すお金が出てまいりますので、現在の持ちの資金ということでは、１３年度末で繰り越しの利益が3,５８０万円ほどの繰越利益ということですので。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"あまりこの会社の中の決算に入っても、ちょっと違う部分かもしれないんですが、確かに3,５８６万円が当期未処分利益に出ていたので、その分かなと説明を聞いてわかったんですけれども、逆に言えば毎年当期利益が上がってきたときに、今後減資を考えていくということも出てくるのかということも絡むと思うんですが。","respondent":"小野政策担当課長","answer":"ただいまのお話のように、現在の資本金につきましては、シーガル東大井の建設事業を行うときに、２億5,０００万円ほどの増資をしておりまして、この事業が平成２０年に借入額が完済になりますので、今回の減資は第一弾、そして完済が終わって資金的に余裕が出てくれば。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何かやり方に納得いかないという部分があるんです。もう１点、会社の中の含み資産という問題は絡んでこないんですか、そのまま数字だけが動いていっていいのかなという点が納得いかないところがあるんですけれども。","respondent":"濱野助役","answer":"もともとこの会社は都市基盤を整備するために、土地・建物をストックとして持つです。そして、賃料によって回収しながら、資金的に整えていくという性質の会社でありますので、一定の期間を経過した後に、資金的な面で資本金の減少が可能になったということで実施をしたものです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"説明はわかるんですけれども、ただ会社事態の運営方法として、そういうやり方が一般的なのかという点に疑問があるんですけれども。それから、同じ数字での株式の返還なのか、含み資産を考えていないのかという点のお答えをお願いしたいんですが。","respondent":"濱野助役","answer":"含み資産については、考えていないという形の返還です。","voiceIndex":26,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今後、会社としての利益を考えたときに、やり方をもうちょっと検討していただきたいということを要望しておきます。もう１点、歳出のほうですが、産業経済費の中で中小企業センター等の運営費の追加が出ておりました。品川区勤労者体育センターの取得、５２万5,０００円、この分についてご説明をいただければと思うんですが。","respondent":"市川産業振興課長","answer":"ご案内のとおり、この事業団は政府系の特殊法人でございまして、いろんな機構改革あるいは財務整理という必要から、約３年前から事業団の持ち分を区のほうで買い取ってほしいという要請がございまして、昨年事業団が新たに機構替えがございまして。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"よく週刊誌等で話題になった部分だと思うんですが、５２万5,０００円というのは、逆に言うと高かったのではないかと、その辺が気になっていたんですが、もし短くお答えできればお願いいたします。","respondent":"市川産業振興課長","answer":"公的な機関が、一定の算出方法に従いまして提示していただいた価格です。建設時の費用、経過年数等々を勘案いたしまして、適切な価格であると考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"山路委員","kind":"質問・要望","question":"私から７０ページの橋梁費について、７２ページの公園改良整備に関連いたしまして、また７４ページの区民住宅費に関連して質問いたします。橋梁費に関連してですけれども、補正予算書を見てみますと八ツ山歩道橋整備工事費として更正減額が１億4,５００万余されておりますけれども、内容についてお知らせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"現在、工事中ですけれども、これにつきましては当初概算費用で予算をつけていただきましたけれども、精査の結果、建設費が大幅に少なく済むとことになったものです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"山路委員","kind":"質問・要望","question":"八ツ山歩道橋は、かつては北品川一丁目の都営住宅の方が専用に使っていた歩道橋ですけれども、今、説明がありましたが、品川駅の再開発に伴って、北品川一丁目の住民の方が駅のほうに行くには重要な歩道橋になっていくんじゃないかと思いますけれども、今、住民の方たちは八ツ山踏切を渡っていますが、こちらのほうはどういうふうになっていくのか、お知らせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"これができますと、北品川一丁目の方が八ツ山踏切を通らないで、トンネルを通って行き来ができる計画になっております。","voiceIndex":35,"id":"exchange-013"},{"speaker":"山路委員","kind":"質問","question":"北品川一丁目の住民の皆さんは、非常に期待をしているということであります。もう１点、品川駅西口周辺の放置自転車対策につきまして、港区側といろんなトラブルがあったです。今後、東口の地下に1,０００台の駐輪場ができるということを伺っているわけですけれども、自転車で周辺に来られた方がスカイウォークを通って東口のほうに行けるかどうか、その辺の計画についてお伺いいたします。","respondent":"岩田管理工事課長","answer":"ただ、東口全体の区画整理事業の中で、幅員が２０ｍ程度の都市計画道路網が整備されますので、この歩道上はゆったりとした歩道ができますので、そちらは安全に自転車の方は通行できることになる予定です。","voiceIndex":37,"id":"exchange-014"},{"speaker":"山路委員","kind":"質問・要望","question":"旧東海道の商店街の活性化と、多くの方が訪れる八ツ山歩道橋を使っての旧東海道への買い物とか、こういう計画についてはどういうお考えでいらっしゃるか、お聞かせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"その中の一つに、品川駅のほうにお見えになる方々が、どういうふうに北品川商店街の旧東海道のほうに呼び込むか、自分たちのこれからの努力も必要だという認識を持っておられました。","voiceIndex":39,"id":"exchange-015"},{"speaker":"山路委員","kind":"質問・要望","question":"港区側はかなりいろいろ整備をされているんです。品川区側といたしましては、唯一の品川駅からの出口だと思いますので、周辺についてはよろしくお願いしますとともに、出口から旧東海道に入っていく案内板とか標識、あるいはもう少し大きく考えたら、モニュメントまで区のほうでまちづくり整備事業として考えたらどうかと思いますけれども、その辺についてのお考えをお聞かせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"現在、八ツ山トンネルの整備工事が実施中ですので、その中で東京国道工事事務所も、旧東海道の入り口を何らかの形で表示をしたいという意向を持っておられますので、この関係につきましては、区と地元と東京国道のほうで十分検討してまいりたいと思います。","voiceIndex":41,"id":"exchange-016"},{"speaker":"山路委員","kind":"質問","question":"どうぞよろしくお願いいたします。続きまして、区民住宅に関連いたしまして、区民住宅は建設型と借上型とありますけれども、借上型に関しまして、現在何世帯ぐらいありますかお伺いいたします。","respondent":"田村住宅課長","answer":"現在、借り上げ住宅が１６団地、２９８戸あります。","voiceIndex":43,"id":"exchange-017"},{"speaker":"山路委員","kind":"質問・要望","question":"南品川四丁目に高齢者住宅パレスガルというのがありますけれども、パレスガル周辺にも区民住宅が幾つかあるんですけれども、何棟ぐらいあって何人ぐらいの方がいらっしゃるかお聞かせいただきたいと思います。","respondent":"田村住宅課長","answer":"南品川近辺ですと、南品川四丁目に中川フラッツという区民住宅が１７戸あります。同じく、借上型の区民住宅で島田ビルということで、北品川五丁目に１２戸あります。","voiceIndex":45,"id":"exchange-018"},{"speaker":"山路委員","kind":"質問・要望","question":"その横に碑文谷街道と言いまして、この委員会でも何回も議論があったんですけれども、子どもたちの通学路にも指定されておりまして、区民住宅にお住まいの子どもとか、あるいは高齢者住宅の方が出入りするときに、碑文谷街道の狭いところを車が飛ばしてくるので非常に危険を感じていらっしゃるんですけれども、その辺の声は区のほうには届いているんでしょうか、お聞かせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"横断歩道をつくってほしいとか、あるいは一番問題になっております交差点部分に信号機がつけられないかとか、そういったご要望はいただいております。これについては幅員が狭い道路で、通過交通も多い道路ですので、現在所轄の警察署と内容については調整をしています。","voiceIndex":47,"id":"exchange-019"},{"speaker":"山路委員","kind":"質問","question":"山手通りが渋滞しているときに、抜け道となっているようですけれども、高齢者住宅の前に横断歩道が難しかったら、多少でこぼこといいますか、スピードをダウンできるような方策も今後考えられるのではないかと思いますけれども、どのようにお考えでしょうか。","respondent":"岩田管理工事課長","answer":"ただ、白線を絞り込んだり、あるいは注意看板を立てたり、できる範囲内で区としては対応していきたいと考えています。合わせまして、根本的にはここが抜け道になっておりますので、抜け道にならないような抜本的な対策も現在検討しています。","voiceIndex":49,"id":"exchange-020"},{"speaker":"山路委員","kind":"質問・要望","question":"車も通さなければいけないという、両方がうまくいかなければいけないということで、抜本的な体制に取り組んでいるということで結構ですけれども、危険を感じることに関して、やはり早期に地元住民の方のご意見を聞かれて、対策を要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"},{"speaker":"上山委員","kind":"質問・要望","question":"私から補正予算の７０ページ、防水板設置工事助成の関係が１点、それから７２ページの都市開発費の関係でお尋ねいたします。最初に、防水板設置の関係でお尋ねしたいんですけれども、今回集中豪雨の対策で区がいろいろやってきたことは、私どもとしても評価をしております。今年度は最終的に補正が追加されているんですけれども、今年度はどれぐらい執行されたのかわかれば教えていただきたいと思います。","respondent":"矢部下水道河川課長、山室住宅指導担当部長","answer":"防水板の件で１点目、広報についてですけれども、現在、広報「しながわ」、ホームページ等で防水板の設置事業につきましては広報しております。続きまして、平成１４年度の設置件数ですが、１２月末で１２件の申請がございました。建築指導の窓口におきまして、当然のことながら半地下もしくは地盤より低い建物をつくる場合については、窓口で繰り返し指導しているところですが、確認申請をおろす段階におきまして、パンフレットを添えて。","voiceIndex":53,"id":"exchange-022"},{"speaker":"上山委員","kind":"質問","question":"特に、品川区全域で水が出るわけではありませんから、一定の区域に限られた部分があるかと思いますけれども、そういうところが具体的に申請が来て、半地下などをつくるとなった場合、区としてそれ以上要請みたいなことはなかなか難しいのか、その辺は法的なところを含めてどうなんでしょうか、お願いしたいんですが。","respondent":"山室住宅指導担当部長","answer":"建物につきましては、本来地盤から４５cm以上高くして建築するということが基本的な考え方です。したがって、まずそういった指導をしているわけですが、法律では必ずしも地下あるいは地下形式を禁止しているわけではございません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"上山委員","kind":"提案","question":"今後ですけれども、提案が一、二あるんです。併せて、例えば「しながわガイド」ということで、転入されて来た方に無料で渡していたこともあったと思うんです。それから、半地下になっているようなところに、先ほどいろいろ要請されているという話をしておりましたけれども、どれぐらいそういうのがあるのか、あるいは区として把握されているのでしょうか、その辺をお願いしたいんですが。","respondent":"山室住宅指導担当部長、山田広報広聴課長","answer":"壁際になりますので、カウンターに相談に来られた方については、当然その当該地域については後ろの地図で。ただいまお尋ねの「しながわガイド」ですけれども、転入者約２万人ということで、毎年増刷をしておりまして、転入時には無料で提供しております。もう１点、事例ですが、ご案内のとおり半地下を設けた場合は、排水口とか排水ポンプの設置を要請しているところですが、必ずしも業者が購入された方に。","voiceIndex":58,"id":"exchange-024"},{"speaker":"上山委員","kind":"質問・要望","question":"先ほどの地図の件ですが、カウンターに置いてあるので見られるという話がありましたけれども、何らかの形でもう少し区民の皆さんがわかるような形で工夫できれば、ぜひ検討をいただけないかというふうに、これは要望しておきます。それから、都市開発費の関係で質問いたします。","respondent":"南雲都市開発課長","answer":"その関係で、今年度につきまして当初の見積もりに比べまして４億円ほど減っているということでございまして、西大井につきましても総事業費については変更ございませんし、完成時期などについても予定どおり完成するということになっております。","voiceIndex":62,"id":"exchange-025"},{"speaker":"上山委員","kind":"質問","question":"７２ページに「大崎駅自由通路整備委託等」とありますけれども、「等」というのは何でしょうか、「等」の中身をお願いしたいんですが。","respondent":"南雲都市開発課長","answer":"「等」と言いますのは、主立ったものが自由通路ということでございまして、そのほかにこの中で行っておりますものとして、西口南地区の新しい事業を始めるときに、新規の採択を受けるとき費用対効果の調査をすることになっておりまして。","voiceIndex":64,"id":"exchange-026"},{"speaker":"上山委員","kind":"質問","question":"ここで学校の問題をあれこれするつもりはございませんけれども、こういう形で自由通路にあたるんですかね。自由通路近辺の階段を整備するとか、エレベーターをつけるとか、そういうのだったら「等」でしょうけれども、東五反田Ｃ地区のところに何で「等」になるんですか。ただ、中身そのものが違うようなことまで、ちょっと性質が違うんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"南雲都市開発課長","answer":"この項目では大崎駅周辺の開発につきまして、補助金を支出しているもの、それから委託料等ということで外部に委託をするようなものという、そういう大きな二つに分けているということで、下のほうにつきましては、一番大きな額が自由通路の整備工事委託ということで。","voiceIndex":66,"id":"exchange-027"},{"speaker":"上山委員","kind":"質問","question":"確かに、委託費と言えば委託費かもしれませんよ。でも、やはり中身が大分違うんじゃないかと言っているんですよ。どうでしょうか、企画あるいは財政の担当から見て、こういうふうなくくられ方は一般ではわかりませんよ、こういうふうにならないでしょう。だれが見てもそうは思いませんけれども、私の言っていることはおかしいでしょうか。","respondent":"市岡企画財政課長","answer":"別に隠しているわけでは何でもございません。こういう表記の仕方というのは、通常あり得ることですし、事項別の明細資料の中には明確に記述をしていますので、委員がご指摘されたのは多分それをご覧になっているからご指摘されたのだと思いますが、明確に記述をしています。","voiceIndex":68,"id":"exchange-028"},{"speaker":"上山委員","kind":"質問・要望","question":"確かに金額は６億数千万円、額から見れば少ないです。最後に一言だけお伺いいたします。事業採算の問題も含めて質問したんですけれども、第三回定例会のときは１０月中旬、その後は１１月だ、年明けだ、１月だということをいろいろ繰り返しているようですけれども、あれから既に半年経っていますけれども、決まったのかどうかだけ答弁をいただきたいと思います。","respondent":"南雲都市開発課長","answer":"現在、最終的に候補を１グループに絞り込みまして、具体的な条件の詰めを行っているという状況です。","voiceIndex":70,"id":"exchange-029"},{"speaker":"上山委員","kind":"質問","question":"もう一つ、伺います。まちづくり事業部次長が西口中地区の問題で、街づくり特別委員会で同僚委員の質問に対して、「全部住宅も」みたいな答弁をしたことがあります。自ら決めた問題をどういうふうに評価しているんでしょうか、どう変えるつもりでしょうか。","respondent":"岩野まちづくり事業部次長","answer":"都市計画業務、それから住宅等もありますが、事業計画を見直す中で事業採算等の見直しもあるですので、その場合に住宅が多くなったり、全部住宅になる可能性もゼロではないという趣旨でご答弁したものです。","voiceIndex":72,"id":"exchange-030"},{"speaker":"北野委員","kind":"質問","question":"５９ページのねたきり高齢者等福祉費更正減額について、２点お伺いいたします。自立の方々が少なかったからということですけれども、実際に自立を見込んでいたときの考え方と、今回減額という結果になってしまったというところの違いというんですか、その理由についてお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"そういった事柄に対して、区として一定の助成をしているというのがこの趣旨ですが、全体として考えていたものより少なかったための減額だというものです。","voiceIndex":76,"id":"exchange-031"},{"speaker":"北野委員","kind":"質問","question":"それは私もわかります。ですから、そこの減額になった理由を、来られなかったからということは当然なんですけれども、どのように分析されているのかということをお伺いしたんです。","respondent":"早津高齢福祉課長","answer":"それと、この事業につきましては介護保険という非常に大きな制度改革があった中で、一定の財源を確保させていただいたというような事情もございまして、サービスが低下したということではなくて、残りがあったです。","voiceIndex":78,"id":"exchange-032"},{"speaker":"北野委員","kind":"質問","question":"それと、もう１点の質問は、家族介護の交流事業として激励の集いと宿泊研修、日帰り研修ということで実施しておりますけれども、介護者の交流や日頃の疲労回復ということでは、結構人気があるようなことを私も伺っておりますけれども、介護をしていらっしゃる方はどれぐらいの方を対象としていらっしゃるのか、また参加希望者は全員利用できるのかお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"対象といたしましては、要介護度２以上の方を介護されている方に対してご案内を申し上げてご参加いただいております。その中で５年以上介護をされている方については、併せて顕彰をするというのが基本です。","voiceIndex":80,"id":"exchange-033"},{"speaker":"北野委員","kind":"質問","question":"こちらは郵送で対象者に案内するということで、参加希望があれば参加するというシステムかと思いますけれども、逆に介護をしていらっしゃる方が前向きに外に出ようという方はいらっしゃるんですけれども、介護に生き甲斐を見出してしまうということで、要介護の方が亡くなられたときには燃え尽き症候群という形で脱力感を持ってしまうということも多々伺いますけれども、参加しない方というか。","respondent":"早津高齢福祉課長","answer":"要介護者に対するケアだけではなくて、家族に課題があるかどうかということも、介護者のアセスメント表があるんですけれども、その中には記載することになっておりますので、介護者に対する適切な支援ということも。","voiceIndex":82,"id":"exchange-034"},{"speaker":"北野委員","kind":"提案","question":"やはり、介護度２以下の方でも、一人で遠出することがなかなか難しい状況を考えると、介護をされている方、要するに介護者が見守りの中から解き放されていない状況が浮き彫りになりまして、介護度が低くあっても介護者には何らかの気分転換が必要ではないかということで、身近なところでリラックスできる場所というんですか。","respondent":"早津高齢福祉課長","answer":"介護者に対するリラックス等のご提案です。先ほど区が介護者に対して実施しております代表的なものとして激励の集いと宿泊研修等をお話いたしましたが、そのほかに各在宅サービスセンターでは、それぞれの事業として介護者教室を月１回ぐらいの開催をしておりましす。","voiceIndex":84,"id":"exchange-035"},{"speaker":"北野委員","kind":"提案","question":"３０分でもいいから、いつでもそういうようなものを受けられてリフレッシュしてくるというような、常時開設している場所が身近にあったほうがいいのではということで、これは提案します。やはりリフレッシュを図るため、交流を図るためにも身近なところに、常時交流できるような場所の設置をしていただきたいと思いますけれども、それについてのお考えをお伺いします。","respondent":"早津高齢福祉課長","answer":"このような機会が一層拡充できるかどうかにつきましては、運営法人等とも協議しながら検討してまいりたいと考えています。","voiceIndex":86,"id":"exchange-036"},{"speaker":"石田委員","kind":"質問","question":"先ほど品川都市整備公社の出資金のこともあったんですが、今回東京熱供給株式会社に出資金が出ているんですが、今この時期に、なぜ補正でこのような形で出資金が出てきているのかお聞きしたい。先ほどの説明でも地域環境に寄与することというようなお話もありましたが、この時期にどういう形のお考えを持って出資金を出したというところをお聞きしたいと思います。","respondent":"市川産業振興課長、市岡企画財政課長、黒田生活福祉課長","answer":"そこで、平成１４年度予算におきまして、品川区で予算づけをいたしまして、東京都に補助申請をしたわけですが。東京熱供給株式会社に対する出資といいますか、株式の購入の時期ですが。その施設に関しましては、２３区が５ブロックの中でブロック内で一番路上生活者が多いところが自立支援センターの建設。","voiceIndex":90,"id":"exchange-037"},{"speaker":"石田委員","kind":"質問","question":"東京熱供給株式会社の件につきましては、今後の展開ということがありましたが、もちろん出資金をすることによって、経営的な感覚の中で出資をしたと信じておりますが、今、この時期に出資をしたほうがいいとお思いになって出資をしたと思いますが、発言力をプラスするのが一つの資産という見方をするのか、例えばこれからプラントの更新だ、公共性はどうやって担保するのか。","respondent":"市川産業振興課長、市岡企画財政課長、黒田生活福祉課長","answer":"今後につきましては、補助事業の申請を受ける際に、今まで以上に密度の濃い事前相談を含めた対応が必要であるというふうに考えてあります。その上でですが、財産の取得については自治法上も長の権限ですので、責任を持って取得をさせていただき、この予算でご提案申し上げておりますが。所長会におきましても、経費につきまして提案があったときに、それについては納得できないということとか。","voiceIndex":94,"id":"exchange-038"},{"speaker":"石田委員","kind":"質問・要望","question":"５億円の話の中から切っていくということであると、今後ずっと減らしていくという理解をしていくのか、それからもう１回何か事業をやるときには、そういう形で資本金を投入し、金額が多ければ、また５億円を超えて、６億円、７億円という形で臨むのか、基本的な考え方だけを教えていただきたいと思います。","respondent":"濱野助役","answer":"今後の事業展開というのはまだいろいろな面がありますので、それは事業展開に合わせて今後のことは検討していくことになろうと思います。","voiceIndex":98,"id":"exchange-039"},{"speaker":"石田委員","kind":"質問","question":"今後、例えば利益が出たとしても、お金を入れる。では、資本金でまた入れるんですか。それは監査法人ではないようにしておくという話なんだけれども、それをそこでどういうふうにしていくかという今後のプランぐらいは考えていっていただかないとと思います。","respondent":"濱野助役","answer":"いわゆる当期繰越利益を資本に回すという考えはございません。","voiceIndex":100,"id":"exchange-040"},{"speaker":"藤田委員","kind":"質問","question":"私から３点お聞きいたします。第１点は、６９ページの東急目黒線連続立体交差事業の中で、西小山駅周辺についてお伺いをいたします。第２点目が、７３ページのしながわ中央公園整備についてお伺いしたい。それと併せて、先ほど言いました勤労者体育センターを取得したということで、どこから取得したのか疑問だったものですから、お伺いするんですけれども、以上３点まずお伺いいたします。","respondent":"中島街路事業担当課長、岩田管理工事課長、市川産業振興課長","answer":"そうしますと、平成１８年度完成ということになりますので、その１年前の平成１７年の秋に地下化という予定になっておりますので。ナイターにつきましても夜９時までということで、何時から点灯するかは、その時期によって暗くなるときに点灯する予定にしております。これは当時の助成制度みたいなものでございまして、雇用促進事業団の持ち分については無償で区が使用できるということで現在に至ってありますが。","voiceIndex":103,"id":"exchange-041"},{"speaker":"藤田委員","kind":"質問","question":"よくわかりました。それから、しながわ中央公園の利用形態はわかりました。これは東京都の道路というふうに伺っているんですけれども、この整備はどこが行われたのでしょうか。ですから、しながわ中央公園はスポーツの公園にしようという発想がありますので、例えば雨天のときにこの体育館が使用できるように改善する必要性があるんじゃないかと思うんですけれども、お考えをお伺いしたいと思います。","respondent":"奈良交通安全担当課長、岩田管理工事課長、市川産業振興課長","answer":"１点目の放置自転車の関係ですけれども、西小山駅が完成した暁には、東急のほうできちっと整備する予定ですけれども、現在確かに委員ご指摘のように。暫定工事といいますのは、ご案内のとおり補助２６号線が全線開通した暁には、この道路が区道に移管になる予定になっております。ただ、一部ヘルストレーニング室と申しまして、健康づくりのための施設も入ってありますので、その辺の利用についてのＰＲということは。","voiceIndex":107,"id":"exchange-042"},{"speaker":"藤田委員","kind":"質問","question":"３年猶予があるわけですから、例えばここを一時的に駐輪場を二段にすれば、倍の自転車が収容できるんじゃないかと思っているんですが、そのお考えをお伺いしたいということ。もう一つは、中小企業センターにレストラン蔵というのがありますが、いつも８時半になると閉まってしまうんです。ナイターは９時までやっているわけですから、この辺はやっぱり考えたほうがいいんじゃないかと思うんです。","respondent":"岩田管理工事課長、市川産業振興課長、奈良交通安全担当課長","answer":"ご指摘の件は、早急に検討してまいります。レストランの件については、ご要望に沿った形で今後検討してまいりたいと思います。駐輪場の二層式の関係ですけれども、西小山駐輪場は以前より大分広げてありますので、あくまでも暫定運用ですので。","voiceIndex":111,"id":"exchange-043"},{"speaker":"藤田委員","kind":"質問・要望","question":"目黒区寄りの線路際ののり面のところが非常に危険なんですよ、おわかりだと思いますけれども。もう風の強いときは、自転車が倒れますと車いすも通れないぐらいの自転車が駐輪されているということで、ぜひ二層式を仮にでも設置したほうがいいなと思います。これは要望にとどめておきますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-044"},{"speaker":"金高委員","kind":"質問","question":"私は歳入につきまして、７ページに出ております一覧表の国庫支出金、都支出金並びに特別区債の件につきましてお伺いします。これらのことにつきましてお尋ねしたいんですが、総体的にそれぞれの金額がなっているわけでありますけれども、詳しく見ると４４ページが国庫補助金、４６ページは都補助金になっております。","respondent":"市岡企画財政課長","answer":"再開発の関係で一番大きいのは、先ほど担当課長がご答弁申し上げましたが、西大井については国のほうが前倒しで補助金をおろしましたので、それが１３年度の最終補正から１４年度にいく繰越明許費と１４年度当初とが、いわば二重に手厚く計上していたので。","voiceIndex":117,"id":"exchange-045"},{"speaker":"金高委員","kind":"質問","question":"その次に、特別区債につきまして質問します。補正前につきまして、予算計上で３１億1,１００万円の予定でありました。そうしますと、当初より１８億8,１７０万円で済んだということでありますが、要するに借入金が少なくなるということは大いに結構なことでありますけれども、どうしてこのような大きな数字が総額として減額したのか、その辺をお聞きしたいと思います。","respondent":"市岡企画財政課長","answer":"つまり、当初考えていたよりも税収が増えましたので、国よる制度減税の幅も増えたので、この制度減税の減った分を埋めるための起債が住民税減税補てん債というものですけれども、これもそれに対応して増えたという、少し二重の絡みを持った補正内容になってあります。","voiceIndex":119,"id":"exchange-046"},{"speaker":"金高委員","kind":"意見","question":"いずれにしましても、この中で減税ということで、１２ページの特別区債の補正について、一つ目には道路橋梁整備、それから公園施設整備がありますけれども、確かに住民税の減税補てんということでプラスになっているということであります。この減税でありますけれども、確かに国の制度としての分野で減税になっている、それを債券で穴埋めするというわけであります。","respondent":"市岡企画財政課長","answer":"国の制度減税の補てんとしての住民税減税補てん債というのは、ちょっと複雑な仕組みを持っておりまして、地方税法の改正、つまり法律の改正で国の責任で減税をするんですが、しかし実際に税金が減るのは各地方公共団体なわけですから。","voiceIndex":121,"id":"exchange-047"},{"speaker":"金高委員","kind":"意見","question":"そうしますと、その差というのが当然出てくるわけでありますし、区債のほうにとっては当然利子がかかってくるということがあります。それの時間の差があるわけでありますけれども、そういう形になりますと当然何らかの方法で、来るまで待っているではなくて、多少何らかのストックをしなければいけないというところがあると思うんですが、その辺の処置というのはどういうふうになっているかお聞かせください。","respondent":"市岡企画財政課長","answer":"そこが非常に重要なところだと考えておりまして、先ほど申し上げたとおり国の制度減税なのに、財調で返すお金を埋めるということは、いわばもともと区のお金で減税の穴を埋めるということに他ならないので、ここが大変問題であるというふうに認識しております。","voiceIndex":123,"id":"exchange-048"},{"speaker":"金高委員","kind":"意見","question":"そうしますと、品川区は別としまして、他区は持っている基金を一時的にも流用といいますか、予算的な形で取り崩してとなってきますと、ほかの自治体ということであれば、当然財政基盤を脅かすような感じがあるんですけれども、ほかの自治体がそういうものを使ってしまった場合には、品川区と比較してどういう差が出てくるか、その辺をお聞かせ願いたいと思います。","respondent":"市岡企画財政課長","answer":"減債基金が一番いい例ですが、これは絶対に返さなければいけないお金で、これを免れる方法は基本的にはありませんが、ただ一つ、返すべきお金を使い込んでしまった場合は、そっくり借り替えをして、ローンで言うと先延ばしをするという方法しかないだろうと思います。","voiceIndex":125,"id":"exchange-049"},{"speaker":"金高委員","kind":"意見","question":"品川区は俗に言われる健全財政ということでありますので、今の答弁どおりしっかりと守っていただければと思います。もう一つですが、例年補正の中で用地特別会計が入っていたわけですけれども、今回は補正の中にも用地特別会計が入っていないということで、その理由をお聞かせ願いたいと思うんです。","respondent":"市岡企画財政課長","answer":"そういう意味では、少し先をにらんで、こういう形の会計の置き方も一つの考え方としてあるのではないかということで存置をいたしました。","voiceIndex":127,"id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"私から６９ページの都市計画道路拡幅事業更正減額について、質問をいたします。簡単で結構ですから、都市計画道路に対して、今どういう体制でどういう整備をしているかということを端的にまずお答えください。","respondent":"中島街路事業担当課長","answer":"現在、私ども５路線やっていますけれども、そういった中では用地買収していく際には、権利者の生活再建と営業の継続という基本的な２本の柱をもとにいたしまして、そういったことをどう担保していけるのかということを地権者と十分協議しながら進めているところです。","voiceIndex":130,"id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"これは毎年いろんな委員から質問されましたし、重ねはしませんけれども、２８億円の当初予算に対して１３億円の更正減額ということですから、数字をとらえれば大きいんですけれども、その中身はいろいろある。私どもこれをいろいろ調査していきますと、いわゆる権利者の方々はそこに何百年先祖代々住んでおられる方もいらっしゃるし、いろんな思いを持ってその土地に住んでいる。","respondent":"中島街路事業担当課長","answer":"実際に交渉を進めていく中では、権利者に事業の必要性をご理解いただくというところから始まりまして、さらにそれが進んでいきますと、実際の生活再建あるいは営業の継続がどのようにして可能になるかということをやってあります。","voiceIndex":132,"id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"まさに公的な目的のためにこういう皆さん方は大変な決断をされるわけですから、私たちがいろいろ勉強していく中では、権利者の方々はそれこそ一生を左右するような大事業です。区の担当者は人事でかわる。それから、特別昇給という話を聞きました。ですから、区側の内部の体制のこと、それから頑張った職員の処遇について、もう一つ踏み込んだ対応をお願いしたいと思うんですが、いかがでしょうか。","respondent":"中島街路事業担当課長、桑村人事課長","answer":"行き違いとか齟齬のないようにということもありますし、区の場合は人事異動が一定の期間でやられますので、そういったときにも継続的に組織的な責任を持って対応できるようにということで。その意味では、毎年やっている人事考課と、年ごとの成果に該当いたします特別昇給を組み合わせて進めてまいりたいと思います。","voiceIndex":134,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それを公共の目的のために移転するわけですから、本当に大きな決定をされる。だから、同じように品川区の職員の体制としても、今言ったプラスアルファの部分で、頑張ったら頑張った分だけ、ましてこの事業というのは非常に数字に出やすいわけですから、やっぱりそれに対しては十分な対処をしていくべきだと思いますが、その辺に対しての突っ込んだ答弁をいただければありがたいんですが、お願いできますか。","respondent":"桑村人事課長","answer":"少し繰り返しの答弁になりますけれども、先ほど言いましたとおり、こういった仕事に非常に苦労されている仲間について、きちっと把握をして、それを処遇にあらわしていきたいと考えています。","voiceIndex":137,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"支援費制度の準備事業について、お聞きしたいと思います。それと「支援費制度になります」というお知らせですけれども、どういう人にどれぐらいされたか教えていただきたいと思います。もう一つ、ケアマネージャーが担当する形に介護保険はなっていますけれども、支援費制度の場合は担当ケースワーカーという体制になるのかどうか、このことについて教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"さらに加えて、これも先日の本会議でご答弁申し上げましたけれども、品川区の場合はいち早く個別訪問、つまり一般的に制度の周知をしてもなかなかわかりにくい面がありますので、ケースワーカーが１軒１軒訪問しまして、個別に説明をしていると。","voiceIndex":141,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補正予算の４４ページ、民生費補助金の支援費制度施行準備事業費のところで質問をしています。もう一つ、障害者の方々から、区のケースワーカーが勤務異動でかわってほしくないという要望を聞いているんですけれども、障害者の実態や仕組みや制度について、よくわかっている人に相談に乗ってもらって対応してもらいたいという希望が出ているんですけれども、そのことについてもお答えいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"相談の仕組みということですけれども、今申し上げましたように、例えば知的障害者についてはダブルキャストで体制を組んでおりますし、できるだけ今回の支援費制度の移行についてもそうですが、障害者についてはすべてにわたって定期的な訪問というのは。","voiceIndex":143,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"通所する施設が決まった後でも、１回入ったけれども合わないというときに、ほかのところに変わりたいという希望が出せて、そしてお互いに交換し合うということも含めて、調整できるような柔軟な対応をしてほしいという希望が父母の方から出されているんですけれども、その辺の考え方について教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"そういった意味では、今までの施設でいいのかどうかということについても、かなりきめ細かく情報交換をしておりますので、また現実にそういった結果を踏まえて、施設間の移動についても区のほうで調整をして進めているという状況でありますし、支援費制度に移行してからも。","voiceIndex":145,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は、サービスを選べることになるわけですから、品川区にどんな施設があるか、またサービスがどういうふうになっているか、サービスの事業者はどうなっているのか、その辺のところがわからなければサービスを選べることにならないわけですので、品川区として充実させるためにこういうふうに努力しているとか、そういうことも含めて、ぜひわかりやすいものをつくっていただけたらと思います。","respondent":"日下部障害者福祉課長","answer":"自己負担の関係ですけれども、これにつきましては先月２１日に国のほうが基準を示しました。東京都はおそらく今日議決されれば、そこで決定ということになると思いますが、特にホームヘルプについて現行水準ということで、負担の緩和措置をやります。","voiceIndex":147,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私がお聞きしたところでは、全身性障害者介護人は今までは本人の所得ということで考えられていましたので、今までは無料というところが、今度は上限１万４００円まで有料になるということで心配だという相談を受けているんですが、この点についてはどうでしょう。","respondent":"日下部障害者福祉課長","answer":"実は、全身性のケースは全体で２０ケースほどありますが、現行でも負担はゼロです。確認をいたしましたが、支援費制度移行後も負担が発生する方は一切いらっしゃいません。その辺は、ご安心をいただきたいと思います。","voiceIndex":149,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"支援費制度に変わることによって、今まで受けているサービスの自己負担が増える方は一切いないということで確認させていただいていいでしょうか。","respondent":"日下部障害者福祉課長","answer":"これはどういうことかと言いますと、負担についての基準も変わります。それから、対象範囲も若干変わりますが、例えば今の全身性の問題について言えば、本人の負担が扶養義務者外ということで決まってまいります。","voiceIndex":151,"id":"exchange-060"},{"speaker":"船波委員","kind":"質問","question":"私は７３ページの仮称旧正田邸記念公園用地買収費について、お伺いしたいと思います。この額が３億８００万円となっていますが、額の根拠をお伺いします。","respondent":"市岡企画財政課長","answer":"購入の理由は、国が年度内に建物除却後の土地を一般競争入札により処分するのが原則で、だれも公共団体が手を挙げなければ、これは区民の方が一番心配されている事態になるだろうということで、報道等もありましたし、ご説明も本会議等で行いましたが。","voiceIndex":154,"id":"exchange-061"},{"speaker":"船波委員","kind":"質問","question":"補正予算で土地を購入するというだけではなくて、やはり公園用として買うからには、今後も公園として整備していくわけで、２００３年度予算にも公園を整備するための予算が計上されています。土地だけを買って公園にするという望まれていない形をしていくのに、品川区の公的なお金を使ってやるということを正当化する品川区の考え方はどういったものなんでしょうか。","respondent":"市岡企画財政課長","answer":"もちろん、いろいろな意見があることは私ども承知ですが、現実に建物については、国有財産の管理権限を持っている国が正式に取り壊しを決定しているわけですから、それについて区が建物の購入予算を計上するという無責任なことはできないわけです。それが１点です。","voiceIndex":156,"id":"exchange-062"},{"speaker":"船波委員","kind":"質問・要望","question":"やることが望ましいから、区が提供するものやサービスや施設もあるわけですけれども、区が提供するものであっても、利益を享受する人のためなので、受益者負担を求めるという考え方もあります。ほかの事柄では受益者負担を求めているという考え方もあるのに、これはひとえに公的なお金でやっていくというところに整合性がないように感じられるんですが、そういうことに関しては、どうお考えなんでしょうか。","respondent":"中尾根企画部長","answer":"しかしながら、区民の声が何が正しいのかというのは、少なくとも議会制民主主義を取っている以上は、品川区の議会の中で住民の代表である皆さんが決定することに従うというのが最も民主的ですので、区はこの議会で否定されれば、もちろん買うということについては取り下げますが。","voiceIndex":158,"id":"exchange-063"},{"speaker":"船波委員","kind":"質問・要望","question":"先ほど私が申し上げた受益者負担の考え方については、どうなんでしょうか。とりあえず区が整備するにしても、ナショナルトラストのようなやり方とか、望む人たちが実現したいとなれば、もちろん負担もしなければならないという考え方はどうなんでしょうか。","respondent":"中尾根企画部長","answer":"ただし、テニスみたいな特別なことをしたいというニーズにこたえるためには、やる方に対して有料という制度でお貸ししましょうという使い分けをしているものです。今回の旧正田邸につきまして、公園にする場合に、有料の公園にするという考え方は現在持ってございません。","voiceIndex":160,"id":"exchange-064"},{"speaker":"中島委員","kind":"質問","question":"私は６０ページの社会福祉施設費、６２ページの児童福祉施設費に関連して２点質問したいと思います。社会福祉施設費ですが、この中に高齢者等住宅運営費更正減額として７７７万9,０００円あるわけですが、これはどういったものなのかお知らせください。","respondent":"蓼沼高齢事業課長","answer":"ただいまの住宅使用料の減額の件ですけれども、当初の説明でもございましたように、借上住宅の計画が予定されていた施主の方の辞退がありますので、それに伴っての減額です。","voiceIndex":163,"id":"exchange-065"},{"speaker":"中島委員","kind":"質問","question":"これは１年に１回募集する高齢者住宅の借りる方が借りなかったということですか、建物ができなかったということですか。高齢者住宅を提供してくださる方が辞退をされたということでしょうか。","respondent":"蓼沼高齢事業課長","answer":"借り上げ住宅という高齢者住宅の一つの形で、建設を予定していた計画が、本来建てて使うべき予定のものが、その計画がなくなったです。","voiceIndex":165,"id":"exchange-066"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、高齢者住宅というのは、これからもそういう方がいらっしゃればさらに建てるという計画はあるんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"今現在、借上型、建設型を含めて２２０戸のストックがございまして、現時点ではこのストックの有効活用をしていくということで予定をしておりまして、今のところ新しい住宅の建設、借り上げ等については予定してございません。","voiceIndex":167,"id":"exchange-067"},{"speaker":"中島委員","kind":"質問・要望","question":"私もどういう内容のものかわからなかったので、これに関連して質問しようと思ったんです。そうした方に対して、資格がないととらえていいのでしょうか。もし、そうであるとするならば、こういう方たちには最後の発表があるまでずっと黙っているというのは酷ではないかと思うんですが、その辺のところをお知らせいただきたい。","respondent":"蓼沼高齢事業課長","answer":"今回につきましては、２月末に住宅審査会が開かれまして、その結果を整理して近々に結果を申し込まれた皆さんにお知らせをする予定です。","voiceIndex":169,"id":"exchange-068"},{"speaker":"中島委員","kind":"質問","question":"この枠というものをもう少し緩和をしなければいけないんじゃないかと。確かに、立ち退きや劣悪だけで見ていくんじゃなくて、高齢者の方は家賃が高い中でも目減りしていく中で、人に迷惑をかけないように一生懸命生きようとして努力して、何度も申し込みをしていらっしゃる方もいるわけですから、そういったところも配慮していただけないかと思うんですが、この辺のところはいかがでしょうか。","respondent":"蓼沼高齢事業課長","answer":"要件といたしましては、空き家の登録待ちのものとほぼ同様ですけれども、それ以外の方につきましても柔軟に宅建協会の支部と連携いたしまして、制度とは別に情報提供などもしまして、実際に住宅が見つかっているような方も中にはありますので、そういった形で対応しています。","voiceIndex":171,"id":"exchange-069"},{"speaker":"中島委員","kind":"質問","question":"これだけで最優先すべきなのかどうか、もう一つ検討しなければいけないんじゃないかと。これから先立ち退いて、それなりの今後の補償があるのかどうか、それから取り壊し、立ち退きではないけれどもせっぱ詰まっている方もいるわけですから、一概に表面的なものだけで判断をしないで、もう少しいろんな面から判断できるような基準をつくっていただけたらと思うんですが、いかがでしょうか。","respondent":"蓼沼高齢事業課長","answer":"そのほか、高齢者に関する住宅で軽費老人ホームですとか、もう少し所得のある方は中堅向けの住宅ですとか、総合的に高齢者に関する住宅の取り組みの中で、できるだけ対応できる部分は対応していきたいと考えています。","voiceIndex":173,"id":"exchange-070"},{"speaker":"中島委員","kind":"質問・要望","question":"児童福祉施設費に関連しまして、家庭あんしんセンターの運営費に対する問題があるわけですけれども、家庭あんしんセンターには母子寮とか子育て支援センター、ファミリーサポートセンターがありますけれども、ここに出ている運営費は全体の運営費でしょうか。","respondent":"辻田児童課長","answer":"この運営費につきましては、家庭あんしんセンター全体に対する運営費です。","voiceIndex":175,"id":"exchange-071"},{"speaker":"中島委員","kind":"質問","question":"済みません。質問の仕方が悪かったんですが……。そこで、ファミリーサポートセンターとか、トワイライトステイとかいろいろできておりますが、これに関連して受け付けですが、ウイークデーしか受け付けていないんでしょうか。","respondent":"辻田児童課長","answer":"受け付けですけれども、同施設につきましては２４時間体制の対応になっております。ですから、相談でありますとか、緊急時の対応につきましては、土曜・日曜に限らず受け付けているという状況です。","voiceIndex":177,"id":"exchange-072"},{"speaker":"中島委員","kind":"質問","question":"それはインターネットによる２４時間受け付けじゃないかと思うんですが、そうではなくてファミリーサポートセンターを利用したい方たちが、申し込みをする場合、ウイークデーしか受け付けてくれないという声があるんです。ところが、ウイークデーしか受け付けてくれないと、利用したくてもできないという声をいただいているんですが、この辺のところはどうでしょうか。","respondent":"辻田児童課長","answer":"ファミリーサポートセンターの通常の受け付けにつきましては、センターに職員がおりますので、実質的な対応については可能だと考えております。土曜日、日曜日につきましても、受け付けられる体制は取れるです。","voiceIndex":179,"id":"exchange-073"},{"speaker":"中島委員","kind":"質問・要望","question":"それは実際にやっているんでしょうか、利用しようと思った方からの要望なんですが。","respondent":"辻田児童課長","answer":"大変、失礼しました。月曜日から土曜日まで、９時から午後５時までということで受け付けております。日曜日は受け付けていないです。","voiceIndex":181,"id":"exchange-074"},{"speaker":"中島委員","kind":"質問・要望","question":"日曜日は受け付けていないということで、日曜日しか休みを取れない母子家庭のお母さんからの要望だったんです。特に、母子家庭でお父さんがいないわけですから、子どもをちょっと預けてほかの仕事をしたいというときに、利用できないのでは何もならないということなんですが、この辺のところは改善できないのでしょうか。","respondent":"辻田児童課長","answer":"通常は事前にいろいろな形で利用したい方につきましては、コーディネートをする部分があります。ですから、日曜日に突然かけてきまして、すぐ預かっていただきたいということは無理かなと考えております。","voiceIndex":183,"id":"exchange-075"},{"speaker":"築舘委員","kind":"質問・要望","question":"私は７８ページの職員費のところで、質問をします。一つには、民生職員費とか衛生職員費、土木職員費、学校職員費のところで減額になっておりますけれども、減額の内容を教えていただきたいこと。８０ページの７目教育職員費、９目学校職員費と二つに分かれておりますけれども、一つにしてもいいんじゃないかと思っているんですか、そのことに関してお願いします。","respondent":"桑村人事課長","answer":"職員費の算定のつくり方ですけれども、１４年度の当初予算をつくりましたときに、１３年１０月１日の職員数をもとにつくってあります。その意味で、１４年の定数算定が終わりまして、４月１日の職員数に増減が出てまいります。","voiceIndex":187,"id":"exchange-076"},{"speaker":"築舘委員","kind":"質問・要望","question":"教育職員費と学校職員費のことに関しては、私もあまりこだわりはしませんけれども、やっぱり生涯学習部がなくなりまして一本化したということもありますし、保育園は保育園で独立しているわけでもないわけですからそこに入っているわけです。そういう意味では、一緒にしてやってもいいかなということを要望しておきます。管理職手当も重要なところだと思います。","respondent":"桑村人事課長","answer":"これにつきましては、先ほどもちょっとお答え申し上げましたが、前年の人事考課に基づきまして上下５％に２.５という形で分かれてきますけれども、ものの差をつけているような制度が始まったところです。","voiceIndex":189,"id":"exchange-077"},{"speaker":"築舘委員","kind":"質問","question":"答弁にしても、一生懸命答弁しているんだけれども、長い答弁というのはどうしてもあれなので、やっぱり内容を的確につかまえた答弁というと、なかなかすばらしいということにもなるし、質問者もそうだと思って自戒をしておりますが……。私は素人ですから、それはわかりませんけれども、そういうふうに思っている区民の方もいらっしゃるかもしれませんので、ここでお聞きしたいと思います。","respondent":"桑村人事課長","answer":"例えば、大きな開発等がどうしても何月までに上げるということになれば、それはそれなりの時間外の対応が必要になってくる場合もあります。それは、ある程度折り込んで仕事をしていただくということだろうと思います。","voiceIndex":191,"id":"exchange-078"},{"speaker":"築舘委員","kind":"質問・要望","question":"休日に出て来られる職員もいらっしゃると思うんです。私もたまに出たりするときもあるんですが、そのときにも一生懸命やっていらっしゃるんだなと思います。区役所に強盗が入られるという場合もありますので、やはりそういうことを考えて、休日の管理もしっかりしていただきたいと思いますが、その点についてお願いします。","respondent":"桑村人事課長","answer":"休日等につきましては、前日に例えば土日の何時頃出るという申し出は基本的にあります。基本は振り替えということを原則としていますので、振り替えの勤務をしていただく、あるいは振り替えの中で、どうしてもできない場合には超過勤務という形にしています。","voiceIndex":193,"id":"exchange-079"},{"speaker":"築舘委員","kind":"質問・要望","question":"休日の管理というのは、しっかりとしていただきたいと思います。そのためにも、今年とか去年は２９人とか２３人採用ということでありますので、そのくらいの人数を採っていかないと、行く行く管理職になりたいから頑張ろうということで一生懸命努力をして、品川区を背負っていこうという方を若いときから育てていくということが大切だと思うんですが、その点に関して質問したいと思います。","respondent":"桑村人事課長","answer":"その意味での一定の議論の中で、どのぐらいの新規採用が必要かという判断をしています。その意味で、ここ２年は２０名前後の職員数ですけれども、とはいっても退職に比べれば、かなりの数の減ということになろうかと思います。","voiceIndex":195,"id":"exchange-080"},{"speaker":"築舘委員","kind":"意見","question":"民間からの経験者採用ということも、これからどんどん出てくると思いますけれども、ソニーのようにほとんど途中から入ってくる人が管理職になっているというのも、民間ならいいかもしれませんが、やはり区役所という公の立場の場所というのは、全体に民間が全部入ってしまうというのでは困るわけで、ある一定の民間人が入るのは、当然活性化のため、競争のため。","respondent":"濱野助役","answer":"そういう意味では、それに上手に対応しつつ、幹部を養成していくということがこれからの課題だというふうに思っておりますので、その辺は抜かりなくやってまいりたいと考えています。","voiceIndex":197,"id":"exchange-081"},{"speaker":"沢田委員","kind":"質問","question":"国民健康保険と老人保健医療に絡んで、大きく２点まず質問したいと思います。昨年の１０月に医療の見直し、負担の見直しが行われまして、所得により定額から１割から２割の負担になりましたけれども、これが国保の窓口ではどんな状況になっているのか、あるいは診療報酬の請求にどのような変化が出ているのか説明願いたいと思います。","respondent":"太田保険年金課長","answer":"国民健康保険で医療制度改革をどういうふうにとらえているかというご質問だろうと思いますけれども、私は医療制度を安定して、今後も保険証があればどこの病院へ行っても、いつでも診療が受けられるという体制を、安定的に維持をしていくという改革だというふうに認識しています。","voiceIndex":201,"id":"exchange-082"},{"speaker":"沢田委員","kind":"質問","question":"その方の話ではないんですけれども、高齢者の２人暮らしの方で、１０月の制度改革前は、月２回８５０円ですから、1,７００円の負担が１万4,２４０円、８.４倍に上がったと。これだけ不景気で大変になっているときに、医療費の負担、介護保険の負担など含めて、これは改革と言えるのでしょうか、その辺の判断をもう一度お願いしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"高齢者の医療費の関係の部分ですけれども、今般の医療制度改革につきましては、先ほど保険年金課長がお答えしましたとおり、今後とも皆保険制度を安定的に維持していくという考え方に立ちまして、見直しを行ったものです。","voiceIndex":203,"id":"exchange-083"},{"speaker":"沢田委員","kind":"質問・要望","question":"それなら窓口に行けない、医療機関にかかれないというのが相当広がっているんです。そういう点では、保険なのになぜ償還払いにするんだという問題があると思いますけれども、これは国の段階の問題ですので、これは医療の改革ではなくて改悪だと。国保の問題に移りたいと思うんですが、国民健康保険料の滞納の状況は、どんな状況になっているんでしょうか、その推移を含めて教えていただきたいと思います。","respondent":"太田保険年金課長","answer":"私どもいつも申し上げてありますが、ひと月でも滞納がある場合を含めてカウントしていますので、平成１２年度が１万4,３６６世帯、１３年度が１万5,３１９世帯、１４年度が１万6,５９９世帯ということで、いずれも６月１日現在の数字です。","voiceIndex":205,"id":"exchange-084"},{"speaker":"沢田委員","kind":"質問・要望","question":"推移をということを言ったので、あまり長いと書き取れませんので、３年ぐらい滞納の世帯の状況と滞納額を教えていただきたいと思います。それから、実際の滞納の理由ですね、どんなことが原因となって滞納になったか、調査している結果があると思いますけれども、説明願います。","respondent":"太田保険年金課長","answer":"平成１１年度から申し上げます。平成１１年度が滞納繰越分ということで１４億7,０００万余です。平成１２年度が１７億4,０００万余、１３年度が１８億9,０００万余というのが滞納繰越分の調定額です。","voiceIndex":207,"id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"前に区からいただいた資料ですと失業がトップで１６.５％、営業不振が１１.３％、生活困窮が１１.２２％という、どれを見ても、不況の中でどうにもならなくなって払えなくなったということを示していると思うんです。私、聞きたいんですけれども、こういう状況のときに、例えば保険料の減免や一部負担の減免に対して実態はどうだったのか、ちょっと教えていただきたいんですが。","respondent":"太田保険年金課長","answer":"保険料の減免ですけれども、平成１１年度が６０件、１２年度が５８件、１３年度が５５件という数字です。それから、一部負担金の減免ですが、同じように平成１１年度１０件、１２年度が１６件、１３年度が４件です。","voiceIndex":209,"id":"exchange-086"},{"speaker":"沢田委員","kind":"質問","question":"ところが、今説明がありましたけれども、保険料の減免で五、六十件、この推移というのは平成４年ぐらいからずっと似たりよったりで全然機能していない。弱い者が大変なときに、布団をはぐように取り立てるというのはいかがなものかと思いますけれども、この間の差し押さえの件数はどんな状況となっているでしょうか。","respondent":"太田保険年金課長","answer":"区の場合は、なおかつそれぞれの１割上乗せをしていますので、実際には７割減額、５割減額ということで、低所得者の方へ一応の配慮をしているです。それから、減免と減額については、やはり一定の基準がありますので、その基準に基づいて実施をしている。","voiceIndex":211,"id":"exchange-087"},{"speaker":"沢田委員","kind":"意見","question":"総件数でいうと、２５７件で杉並区を追い抜いてトップと、かなり激しい差し押さえが見られるんですけれども、この辺に対しては先ほど言いましたように失業、病気、けが、営業不振、生活困窮ということがナンバー４で、国保料滞納した問題が並んでいるわけですけれども、ここに及んでいないのかどうなのか、その辺の考え方についてお答え願いたいと思います。","respondent":"太田保険年金課長","answer":"それと、その時期に合わせて、休日窓口の開設を実施していますので、滞納されている方にそういう通知も差し上げるということで、少なくとも３回から４回の通知を差し上げた上で、何のご連絡もない方々に対して、交渉の機会を設けるという趣旨から。","voiceIndex":213,"id":"exchange-088"},{"speaker":"沢田委員","kind":"意見","question":"先ほど一番最初に述べた医療改悪に対して改革だと。国庫負担が、この間に５７.５から３６.３に国保財政が削られているという、こうした問題を見据えて、制度の改善のために品川区が言うべき点は国にも言うし、みずからも暮らしと医療を守るために努力をするということを発言しまして終りたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":215,"id":"exchange-089"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは３点にわたってお伺いをしたいと思います。これに関連をしてお伺いをします。方針があって予算化されるということは、その意味では理解をしておりますから、公園等を新設改良を進めていくときには、さまざまな形で財源があちこちから出てくるものもあると思うんですけれども、ここでは３億８００万円を予算化されておりますが、これの中身の財源的なものはどうなんでしょうかということです。","respondent":"市川産業振興課長、市岡企画財政課長","answer":"１点目のご質問ですが、現在の中小企業センターの経緯を説明します。先ほど、勤労者体育センターが昭和５４年６月に先行してオープンしています。しながわ未来債」が非常に好評のうち完売をしたわけですが、これの公債諸費は政府債を別にすると、おそらく銀行縁故債と比較するのが一番よろしいかと思うんですが、今回の実績では。","voiceIndex":217,"id":"exchange-090"},{"speaker":"土井委員","kind":"質問・要望","question":"そうすると、この事業はどこに入るのかなと思ったものですから、ちょっとお伺いしただけで、特段、それ以上の他意はありません。本当にないんですね、その種のものは。当時、いろんな特殊法人だとか、いろんな形のものをやっていたような気がするものですから、目ざとい品川区ですからきっとやっているんじゃないかと思ったもので伺ってみました。その辺で、先ほどのところをお聞かせください。","respondent":"市岡企画財政課長","answer":"ミニ公募債で１点、追加のご説明をすると、今回宣伝ではないんですが、品川区が先人を切ったために、担当者は金融機関等の折衝に大変膨大な時間と知恵を振り絞りましたので、コストと言えば、これがコストかなというふうに考えております。","voiceIndex":220,"id":"exchange-091"},{"speaker":"土井委員","kind":"質問","question":"大きく言えば学校用地等々の問題があったり、場合によっては道路の端っこのほううに何かあってみたりいろんなものがあって、現実は区が使っているというのがどうも譲ってくれそうにないと、買ってくれと言うときはみんなにわいわい騒ぐんですけれども、そういう問題があって、これの解消というのか、そんな方向も目指したいなというようなニュアンスの話を聞いたような気がするものですから。","respondent":"市岡企画財政課長","answer":"あんまり隠し玉のような話はないんですが、例えば都市計画公園、義務教育施設用地については、起債が非常に有利な形で認められまして、特に義務教育施設用地については、委員ご案内の充当率というものが９０％認められて。","voiceIndex":222,"id":"exchange-092"},{"speaker":"土井委員","kind":"質問・要望","question":"要望で終わります。目ざといというふうにも言われている品川区でありますから、そんなのは見逃すはずはないと思いますけれども、やはりいろいろと調査研究をしていただいて、区民にとって有利な形で物事が進むように、ご努力方をお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-093"},{"speaker":"三上委員","kind":"質問・要望","question":"４８ページの不動産売払収入についてお伺いいたします。今、都市計画公園とか義務教育施設は全額ということのお話を伺ったところなんですけれども、これに関連するような話で、逆の考え方です。それからもう一つは、旧荏原第一出張所跡地の売払代金、今日用意したテーマはこの問題だったんですけれども、このことについてもう少し具体的にご説明いただきたいと思います。","respondent":"伊佐都市計画課長、西島経理課長","answer":"補助４６号線都市計画道路の整備は、東京都建設局が行ってございまして、こちらも道路の拡幅によって、将来的には買収という形で区のほうに用地買収の交渉が入ってまいりますが、現時点でほかの地権者と難航している点がございまして。今般、武蔵小山の中で売買に応じる方がいらっしゃいまして、その方の代替地として１４５m2のうちの９９m2をその代替地として売却したものです。","voiceIndex":226,"id":"exchange-094"},{"speaker":"三上委員","kind":"質問","question":"その用地交渉については、まだしていないというけれども、それ以前の先ほど企画財政課長が話をされた部分で、品川区がどうなんだということなんです。逆に、品川区から東京都が買収するという話になっている話でしょう、そこのところはどうなのと。だから、３分の１が無償で貸与とかという適用されるという話をしているから、逆の立場になったら、これはどうなっているんですかと。","respondent":"伊佐都市計画課長","answer":"東京都の道路事業として、時価で東京都が区から買収するという形になるものです。","voiceIndex":229,"id":"exchange-095"},{"speaker":"三上委員","kind":"質問","question":"旧荏原第一出張所跡地について、１４５m2、正確にいうと１４５.２３m2と言うのでしょうか、昭和６３年第二回定例会で、１５年前ですけれども、この用地についてどうするのかという質問をして以来、何回か取り上げてきた問題であるので、今回有効活用という形で使われるようになったので、時間はこれぐらいかかるのかなということでいるんですけれども、ただ９９m2ということになると。","respondent":"西島経理課長","answer":"この辺につきましては、街路事業担当と十分打ち合わせをいたしまして、現在、まだ確定ではございませんけれども、次の交渉の残地として使いたいという見込みがありますので、できるだけ実現に向けて街路事業担当と調整しながら、有効に活用してまいりたいと考えています。","voiceIndex":231,"id":"exchange-096"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、今現在残地のところに町会関係の倉庫みたいな感じで使っている部分もありますけれども、将来的にはここの４６m2については、あくまでも売り払うという目的で考えているということでよろしいんですか。","respondent":"西島経理課長","answer":"今、ご質問にございましたあそこは防災ポンプの倉庫があります。ここにつきましては、地域の町会長にもご承諾をいただいてありますし、売れる間、ここを使っていただいて結構です。売った場合は、別途協議ということでお話を進めているところです。","voiceIndex":233,"id":"exchange-097"},{"speaker":"三上委員","kind":"質問・要望","question":"ぜひ土地の有効活用という面では、一生懸命取り組んでいっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-098"},{"speaker":"松澤委員","kind":"質問","question":"それと、今、残念ながらタッチの差で財産収入の質問をやられてしまいましたけれども、１点、残地の件ですけれども、やっぱり地域の方が使われているということで、１４坪残っている。それと、７１ページ、土木費の河川費ですけれども、西品川公園雨水調整池整備工事2,５７５万7,０００円、これについてお聞きしたいと思います。","respondent":"金子保育課長、西島経理課長、日下部障害者福祉課長、矢部下水道河川課長","answer":"私のほうから、４４ページの児童福祉施設整備費3,６００万円の減額に関連して、ご説明申し上げたいと思います。旧荏原第一出張所跡地の残地の問題ですけれども、過去に売れるまでの間。福祉施策包括補助金ですけれども、これにつきましては東京都が平成１２年度に創設しました補助制度でございまして。この形ですと、降雨と降雨の間隔が狭かったり、あるいは日曜・祭日等で下水道局の職員がいなかった場合。","voiceIndex":237,"id":"exchange-099"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと、雨水調整池、ありがとうございました。何とか今年度にやっていただきたいという要望が叶えられて、大変近隣の方は喜ぶと思うんです。前回、私も「あれは人災じゃないか」と言ったんですけれども、それがカバーできたというだけの話で、前にも何回も話をしているんですけれども、１時間に１０分間降るだけで溢れてしまうわけですから、それに対する対策というのものを練っていかなくてはいけない。","respondent":"金子保育課長、西島経理課長、矢部下水道河川課長","answer":"そういう意味では、補助事業はたくさんあるわけですけれども、こういった事態を受けまして、私どもとしては今後的確に補助事業に関しての情報を収集して。旧荏原第一出張所跡地の問題ですけれども、一時は子ども図書館として使ったこともありますけれども。先ほど、委員から平塚一丁目付近の工事の話がございましたけれども、平塚一丁目というより、もう少し上流側の平塚二丁目の雨水対策の管を。","voiceIndex":242,"id":"exchange-100"},{"speaker":"松澤委員","kind":"質問・要望","question":"財産収入の件はわかりました。実は、これは２月の広報ですか、「区有地を売却します」ということで、一碧荘あるいは東大井三丁目、マンション雅叙苑４号館。それと、民生費のほうはわかりました。品川区は補助金を取るのが上手だというお話を伺っていたけれども、これも一つのうまくいかなかった例ということで、今後ともさらに努力をしていただきたいと思います。","respondent":"西島経理課長、本間総務部長、矢部下水道河川課長","answer":"マンションということと、使用目的が制限されるということで、住宅以外なかなか使い勝手が難しいということ。区有財産売却の基本的な考え方ですけれども、個々には経理課長が申し述べたとおりですが、実際に庁内で公有財産の活用検討委員会を開きまして。もう１点、三ツ木公園の雨水調整池の可能性ですけれども、今、下水道局のほうで上流側を検討している中で。","voiceIndex":246,"id":"exchange-101"},{"speaker":"藤原委員","kind":"質問","question":"しながわ未来債」について、お伺いします。この２点については、私の前の質問で金高委員と土井委員の質疑を伺っておりまして、よくわかりましたが、ちょっと違う観点でお伺いしたいと思います。東急目黒線に関してですけれども、起債を取りやめた理由はよくわかりましたが、起債をしなくてもなぜ困らないのか、改めてお伺いいたします。","respondent":"市岡企画財政課長","answer":"したがって、４年ちゃんと頑張れるだけの財政力があれば、起債をしなくても償還金がきちんと財調で入ってくる見込みが立っておりますので、品川区の財政力からすると、この規模の起債を補正で取りやめても大丈夫だという判断をしたものです。","voiceIndex":251,"id":"exchange-102"},{"speaker":"藤原委員","kind":"質問","question":"この補正予算と１５年度の当初予算を編成するにあたって、手順はどのような形になっているんでしょうか。","respondent":"市岡企画財政課長","answer":"この背景としては、先般実施計画の財政計画もご配付をしたところですが、少なくとも３カ年については通算して中期財政計画というものをつくっておりますので、この中で補正予算と当初予算を連続して考えていくという検討をしています。","voiceIndex":253,"id":"exchange-103"},{"speaker":"藤原委員","kind":"意見","question":"今、企画財政課長のご答弁で連続ということが出てきたんですけれども、まさに補正予算も新年度の当初予算も深く関連していることがよくわかりました。それで、予算は単年度主義だと思うんですけれども、予算編成はどのぐらいの先まで考えているのか、お答えください。","respondent":"市岡企画財政課長","answer":"よく我々が財政のフレームという言い方をしますけれども、この補正予算にしても当初予算にしても、水の上に出ている部分は単年度なわけですが、水の底にあるのは少なくとも３カ年、それからこういう経済情勢の中でなかなか長期を見通すことは難しいんですが。","voiceIndex":255,"id":"exchange-104"},{"speaker":"藤原委員","kind":"質問","question":"「第１回はばたけ！しながわ未来債」について、お伺いします。新聞報道等で、すぐに完売したという報道を見ました。未来債の売れ行き、そして１人当たりの購入額、区民の皆さんの反応などについてお伺いします。","respondent":"市岡企画財政課長","answer":"１人当たりですけれども、これも１人当たり購入額を幾らにするかというのも、公募債を発行するときの一つの決める必要があることですが、３００万円と設定しましたが、１人平均で２１７万円ということですので、おそらく３００万円限度額目いっぱい購入された方がかなりいらして。","voiceIndex":257,"id":"exchange-105"},{"speaker":"藤原委員","kind":"質問","question":"問い合わせの中で、金利とかの問い合わせよりも、未来債がどのように活用されていくのかという問い合わせがあったというのは、目的がすばらしいことだと思います。募集のパンフレットを見ますと、ここが売りなのかなと一つ思ったのは、「品川区が発行する債券なので安心です」という文章が出ていますが、これはどういう意味なんでしょうか。","respondent":"市岡企画財政課長","answer":"もちろん、品川区は健全財政ですので、ご安心してご購入くださいということもありますが、やはりお住まいになっている品川区を愛着を持っていただいて、いつまでも住み続けていただく、そういう品川区が発行するので。","voiceIndex":259,"id":"exchange-106"},{"speaker":"宮崎委員","kind":"質問","question":"２９ページの介護保険基金積立金を中心に伺いたいと思います。それと、この基金が１号被保険者１人当たりにすると幾らになるのかということと、２３区の比較でどういうところにあるのかということで、まず区のほうの認識を聞かせていただければと思います。","respondent":"早津高齢福祉課長","answer":"今回、補正で計上させていただきました２億8,９００万円余ですが、これは１３年度の決算をいたしまして、その決算で出たものを今回予算化をして、これによりまして基金に実際に積み立てるということになります。","voiceIndex":262,"id":"exchange-107"},{"speaker":"宮崎委員","kind":"質問","question":"今年度末でどのぐらいになるのか、わかったら教えてほしいと言ったんですけれども、お願いしたいと思います。この時点では、２３区で最低だったかと思います。ほかのところを比べみると、これだけ低いところはないと思いますので、出ている部分だけで言いますと、最低というふうに思うんですけれども、なぜこんなに２３区最低レベルの利用率なのか、区の見解をお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"と申しますのは、昨年実施いたしましたサービス評価におきましても、ケアマネージャーに対するサービス評価は、９割を超える方が「満足」ないし「大変満足をしている」という評価を得てありますので、単純に率だけの問題ではないと考えているところです。","voiceIndex":264,"id":"exchange-108"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど、私はサービス利用率が低いことが、会計上どういう影響をしているのかということを聞いたんですけれども、全く答えがありませんので、改めて聞きたいと思います。特に、１割の負担が高いということで、みすみすあきらめているケースがあるので、このところに認識を聞いているんです。いい悪いは置いておいて、実態がどうなっているのか説明をお願いしたいと思います。","respondent":"早津高齢福祉課長","answer":"年度末での残ということでありますが、９０％強ぐらいの執行率ということになりますと、保険料としては１億二、三千万円ぐらいの残が生じるのではないかということが想定されるものです。","voiceIndex":266,"id":"exchange-109"},{"speaker":"宮崎委員","kind":"意見","question":"私は所得の低い方はなかなか利用できない実態があるんだという紹介をしましたけれども、介護保険料の第１段階から第５段階まで収入で分けておりますが、第１段階から第５段階のサービス利用の率があったらお聞かせいただければと思います。第１段階が在宅介護サービス利用率が何パーセント、第２段階は何パーセント、それから５段階までお聞かせいただければと思います。","respondent":"早津高齢福祉課長","answer":"１０月の給付の数値で申し上げますと、第１段階の方は生活保護の方が主になりますので、むしろ第２段階の方が利用率として何位ぐらいあるかということで見てみますと、例えば要支援のところですと、第１段階の方が一番利用率が高く、第２段階の方が３位。","voiceIndex":268,"id":"exchange-110"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、これは要介護、要支援、全部含めての数字だと思うんですけれども、総体的に言えば、第５段階と比べて収入の少ないところは低くなっているというのが、この数字ではっきり出ていると思います。このところはわかりました。さっきも聞いたんですが、見込みが幾つで、実際にどうだったのか、利用率の差についてどうでしょうか。","respondent":"新美保健高齢事業部長","answer":"一定の効率的な事業運営をすることも、また介護保険においては求められているところが現段階ではないかと考えております。","voiceIndex":272,"id":"exchange-111"},{"speaker":"宮崎委員","kind":"質問","question":"だから、その差が基金の中に入ってくるということになるわけですから、そこのところはちゃんと「そうだ」と答えていただければと思います。４月から年金が下がるわけです。状況が変わっていないとおっしゃっているんですけれども、こういう状況が変わっているんですけれども、ここのところは全然見ないのかということをお伺いしたい。","respondent":"早津高齢福祉課長、太田保険年金課長","answer":"まだ、この制度が１年半という実績ですので、また介護保険料その他基準所得金額等につきましても、品川区としては第１期と同様の措置ということもありますので。普通徴収の徴収率ですけれども、１３年度におきましては８９.９％です。１４年度は現在進行形ですが、ほぼ１３年度と同様の普通徴収率ということで推移しています。","voiceIndex":274,"id":"exchange-112"},{"speaker":"鶴委員","kind":"質問","question":"１４４ページの介護給付費準備基金積立金に、多くの時間を割いてお伺いしたいと思います。宮崎委員がお話されましたが、私は視点を変えて幾つかご質問したいと思います。先ほどの１４年度末で１５億7,４００万円という基金ですね。全体的に５７０億円ぐらいの各種の積立金があるんですが、その積立金の性格ですが、ご説明いただけませんか。","respondent":"早津高齢福祉課長","answer":"介護給付費準備基金積立金と申しますのは、介護保険法の中に制度的に位置づけられているものでございまして、積立基金は、そういった結果的に重要なものを次の保険料に相当するものとして充当するものですので、私どもは貴重な財源だというふうに考えてあります。","voiceIndex":279,"id":"exchange-113"},{"speaker":"鶴委員","kind":"質問","question":"ため込むというのは、この前の一般質問でもありましたが、福祉を切り捨ててため込んだ５７０億円をこっちに回せだとか、ため込むということは使わないという意味ですよ。しながわ未来債」につきましても、なぜいち早く完売できたか。血の出るような思いを５８年からやってきたのではありませんか。共産党は反対でした。ため込むというのは使わない、この語感はよくないですね、どう思いますか。","respondent":"早津高齢福祉課長","answer":"今回の基金につきましては、第２期で使う予定です。これは言うまでもなく、3,３００円に据え置いたのは、予想は3,４００円余ですので、この間差の保険料充当に使うものが１点。","voiceIndex":281,"id":"exchange-114"},{"speaker":"鶴委員","kind":"意見","question":"第２期の保険料ですが、昨年１０月２９日の厚生委員会で、第２期介護保険事業計画の骨子案について、介護保険担当課長が説明しました。そして第２期の保険については、3,３００円に据え置く方針を明らかにされました。骨子に基づいての施策の展開というのは、今も変わりませんか。","respondent":"早津高齢福祉課長","answer":"中間骨子に基づいた考え方に変わりはございません。","voiceIndex":283,"id":"exchange-115"},{"speaker":"鶴委員","kind":"質問・要望","question":"共産党の宮崎議員は、平成１４年第四回定例会で「２３区でも値上げの動きが多い中で、品川区は介護保険料を値上げしない努力をしたことは評価したいと思います。しかし、まだ不十分だとして介護保険料は値下げ可能だ」と、そして思い切った値下げを求められました。そして、そのときにも保健高齢事業部長は明確な答弁をされておりますが、その答弁は不変ですね。","respondent":"早津高齢福祉課長","answer":"「値下げは考えてございません」とするのが端的なものですが、「据え置きによって生ずる不足面の充当とリハビリサービスに充当するもので、引き下げは考えていない」と、このように申し上げました。","voiceIndex":285,"id":"exchange-116"},{"speaker":"鶴委員","kind":"提案","question":"時間があれば、後で説明していただきたいんですけれども。「保険料引き下げや低所得者の負担軽減を主張してきました」と、「低所得者の減額制度は共産党が条例提案や懇談会を開催、区民の署名運動が広がり、当初反対していた自民、公明など与党が態度を変え、一昨年１０月に実施」、これは事実ですか。共産党の音頭があったから、昨年１０月の低所得者の減額制度というのはスタートしたのですか。","respondent":"早津高齢福祉課長","answer":"低所得者に対する減額制度につきましては、区議会４会派からの申し入れを受けて、区として判断をし条例提案をしたものというふうに考えております。","voiceIndex":287,"id":"exchange-117"},{"speaker":"鶴委員","kind":"質問","question":"ご丁寧にも「区は今年４月から保険料の値上げをやめました。品川区についで、２３区で値上げストップの動きが広がっています」と、こうあります。第４回定例会では、「多くの区が値上げの動きがある」と言いながら、今度は「ストップの動きが広がっています」と言いますが、では、２３区の状況をちょっと教えてくれませんか。ぞくぞくと値上げじゃありませんか。","respondent":"早津高齢福祉課長","answer":"２３区の次期保険料の予定ですが、１９区が値上げの予定であり、据え置きは３区、１区は検討中というところがありますが、この区も値上げはされるというふうに見通されております。","voiceIndex":289,"id":"exchange-118"},{"speaker":"鶴委員","kind":"質問","question":"ということは、今１９区が値上げを予定していて、３区が据え置きだと。3,３００円、品川区、練馬区、江東区が据え置く。品川区よりも高いところがあるじゃないですか、共産党が今まで言ってきたような「２３区で一番高い」ということは、これから言えなくなっちゃうんです。今度は何位ぐらいになりますか、１０位ぐらいじゃないですか。","respondent":"早津高齢福祉課長","answer":"現段階では１０位ぐらい、3,３００円と発表されている区が品川区含めて４区あります。","voiceIndex":291,"id":"exchange-119"},{"speaker":"鶴委員","kind":"質問","question":"それで、一般質問でも言及いたしましたが、特別給付事業に全国で初めて、身近でリハビリということは画期的なことですよ。それと同時に、私はリハビリのことも研究するということを申し上げましたが、今後はどういう介護サービスの充実に努めていきたいと、細かな施策も含めて紹介していただけませんか。","respondent":"早津高齢福祉課長","answer":"そのほか、施設系であれば、西五反田に現在建設中のケアホームならびに安心の住まいが平成１６年４月にオープンするという、こういうものが代表的なところかと思います。","voiceIndex":293,"id":"exchange-120"},{"speaker":"鶴委員","kind":"質問・要望","question":"今後も努力していただきたいと思いますが、今回3,３００円に保険料を据え置いたのも、１０月２９日の厚生委員会で説明があったように、なぜそういうことができたかというと、基金があったからでしょう。ここにもちゃんと説明してありますが、「第２期の保険料と現行保険料との差額に充当する」。そういう基金がなければ、こういうこともできないわけでしょう、値上げせざるを得なかったですよ。","respondent":"早津高齢福祉課長","answer":"ご指摘のとおり、基金があるからこそ、3,３００円に据え置くことができ、リハビリサービスの創設もできるです。","voiceIndex":295,"id":"exchange-121"},{"speaker":"塚本委員","kind":"質問","question":"行政需要が５年、１０年単位で変わってくるわけですから、その役割が終わったときにその土地をどうするか、建物もどうするかということが一番問題なんだろうと思います。そのことについてお伺いします。品川区の中で一番の大地主は、間違いなく品川区でございまして、この地主は税金を払わないという地主ですけれども、これも一つ考えておかなければいけない。その辺から伺っていきたいと思います。","respondent":"西島経理課長","answer":"ただ、その行政需要というのは、委員ご指摘のとおり変化してまいります。変化したときを機敏にとらえまして、新たな行政需要に対応する。新たな行政需要がない場合は、土地の動向にもよりますけれども、時期を見て適宜処分をするということも考えなければいけないと考えています。","voiceIndex":298,"id":"exchange-122"},{"speaker":"塚本委員","kind":"質問","question":"ですから、一つの施設をただ持っている。ということは、全体的に自分の持っている財産を、どう行政需要をにらみながら活用していくかというのは、今までのスタイル、余ったものを処分しますかどうかというようなことで、さっき総務部長のところで答えたけれども、そのレベルでは間に合わなくなっている都市構造になっているんだということのご認識を聞きたいと思います。","respondent":"中尾根企画部長","answer":"先ほどから議論があるように、基金というようなお金を持つのだったら経費はかからないわけですから、自由なときに自由に使えると、こういうものの考え方も当然強めていかなければいけない。このような考え方に立って、今後運営していきたいと思ってあります。","voiceIndex":300,"id":"exchange-123"},{"speaker":"塚本委員","kind":"質問","question":"財政が豊かで、細かなこれは整理して、ストックにしておいたほうがいいな、使い勝手がいいようにしておいたほうがいいということができる時期はいいですけれども、悪くなったら自分の財産を食い始めてしまうということもあるわけですから、そういうことに関しては何かこの袋は別途会計ですよというような考えを持っておかないと、土地を売ってしまって、すぐ数百億円のお金が出るから。","respondent":"市岡企画財政課長","answer":"そのときに、やはり基本的な区民生活を支えるような財政基盤になるものと、そうではなくて将来付加価値を高めて活用すべきストック、こういうものをしっかり分けて資産運用をしていくという視点が大事かと考えています。","voiceIndex":302,"id":"exchange-124"},{"speaker":"塚本委員","kind":"質問","question":"そのことに対する考え方を持っていなければいけないんじゃないか。おそらく、品川区ができてから年々土地が増え続けているんだろうと思います。そのことは抑えてありますか。そのことについて、鈴木真澄委員の質問の延長線に当然起きてくるわけですので、そのことをまずどうとらえているか、今税金を納め始めた住民像をどのようにとらえているかということをお尋ねしたいと思います。","respondent":"小野政策担当課長、中尾根企画部長、市岡企画財政課長","answer":"もう既に、いろいろなところで出ておりますように、品川区の人口は平成１０年からずっと増え続けております。世帯も増え続けております。したがいまして、現時点での人口のような復活ということになれば、その活用を再び有効にすればいいという意味では、もう昔より資産が相当ありますので。平成１３年度末で2,０２６億余ということで抑えておりますが、問題は売ることのできない道路等の資産は評価していない。","voiceIndex":304,"id":"exchange-125"},{"speaker":"塚本委員","kind":"質問・要望","question":"改めて、指摘しておきます。それから近年都市化が進んで都心３区では、高齢者の高額所得者が高額マンションを取得し始め、そういう人たちの行政需要は違う。今、最近のマンションというのは大変大規模ですから、５００戸とか、そういうものができてしまって、クラスが一挙に増えたとか、空き教室があるはずだったのに、すまいるスクールができなくなったとか、そういうことが当然起きてくると思うんです。","respondent":"中尾根企画部長","answer":"最大のねらいは、活力を求めることと同時に人の住めるまちということですので、それぞれの開発についての内容を分析、どういうふうに民間の方も品川区にそういうことをやるのかというような青写真、そういったものを十分公開しておりますので、私どもは少なくとも中期的な５年。","voiceIndex":308,"id":"exchange-126"},{"speaker":"宮崎委員","kind":"質問・要望","question":"我が党の意見表明をさせていただきたいと思います。昨年、１０月に高齢者医療が改悪され、国保条例の一部改正もされました。しかも、差し押さえは２５７件と、２３区トップです。負担軽減策を、改めて求めるものであります。第２期の保険料を据え置いたことは評価しますけれども、改めて保険料の引き下げ、低所得者の保険料、利用料の負担軽減、在宅サービスの拡大を求めて、態度表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-127"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":104539,"voices":315}},{"id":"h15-20030310-3","meetingId":"h15-c-budget","date":"2003年3月10日","dateIso":"2003-03-10","committee":"予算特別委員会","time":"午前１０時０５分～午後５時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"日に開催いたしました理事会において、平成１４年度事務事業評価報告書の追加資料について協議を行い、本日、皆様のお手元にお配りをさせていただきました。 それでは","agenda":"日に開催いたしました理事会において、平成１４年度事務事業評価報告書の追加資料について協議を行い、本日、皆様のお手元にお配りをさせていただきました。 それでは","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"３３０ページの職員費につきましてご質問します。そういった方々に対しましても、本当の一つの気持ちが区民サービスをするんだという意識、そして、やはり官と民との差があるんだというようなことを承知していただいて、お仕事をしていただくということが必要だと思うんですけれども、その辺の徹底というのはどういうふうになされるのかお聞かせ願いたいと思います。","respondent":"桑村人事課長","answer":"これにつきましては、正直言いまして、これから取りかかるところです。今まで持っていたデータと各所管課でお持ちいただいたデータを突き合わせていく。その中で継続的な意味での指導をしていくということになろうかと思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"一生懸命いいことをやっても、一つの不祥事があるとそれが打ち消されて、打ち消されるどころじゃなくて、マイナスになってしまう。ですから、民間はそういうことがある。そうすると、やはり上司である、それから友人であるという方々がそういったことを見ながら、お互いに気をつけて、今お話ししましたように、一つのマイナスがあってもならないと思いますけれども、その辺のところまではいかがでしょうか。","respondent":"高橋区長","answer":"今回の不祥事は品川区始まって以来と言っていいほどのハレンチ的な行為です。これを肝に銘じまして、こういうことを２度と起こさないような努力をしてまいりますので、ご理解のほどお願いを申し上げます。","voiceIndex":6,"id":"exchange-002"},{"speaker":"嶋委員","kind":"提案","question":"私からは３点質問します。初めに、３３０ページの職員費、通勤定期代についてお伺いいたします。二つ目には、８１ページのしながわ区民公園屋外プールについて、関連して質問します。初めに、去る２月２４日、都議会予算特別委員会で、公明党の小磯議員が提案をいたしましたが、都の職員、約１３万5,０００人の通勤定期代が１カ月定期相当額の支給をされている。","respondent":"桑村人事課長","answer":"それに合わせて都のほうも一定の見解を持ってこれから直していくというようなことだろうと思います。私どもは１カ月の定期代でやっているわけですけれども、現状で見ますと通勤手当を支給しているのが2,４１１人というような現状です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"嶋委員","kind":"質問","question":"今１カ月ですが、やはりおおよその単純計算で、これを１カ月を６カ月にいたしますとどのくらいの削減がされるかお聞きしたいと思います。","respondent":"桑村人事課長","answer":"それを単純に掛け合わせたものですけれども、大体2,１００万円ぐらいの削減効果が出るだろうと思ってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"嶋委員","kind":"質問・要望","question":"2,１００万円の削減効果が出るということなので、ぜひ品川区においても東京都と同じように、６カ月の定期代の見直しを早急にしていただきたいと思いますので、よろしくお願いいたします。","respondent":"桑村人事課長","answer":"この通勤手当の月額の決め方というのは、人事委員会が決めている形になってございまして、これは私どもの区だけでは決められない部分もありますけれども、各区にいろいろ働きかけて、まさにこれからの流れはこういった形になかろうかと思いますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"嶋委員","kind":"提案","question":"私は平成１１年第４回定例本会議の一般質問で細かくいろいろな要望を提案させていただきました。それから４年がたつということになりますが、この中で区民プールなんですが、今４月くらいから９月くらいまでオープンをして、特に私もプールのことについて大分質問させていただいたと思いますが、その中でプールの利用料の昨年と一昨年、もしできましたら２年間の数を教えていただきたいと思います。","respondent":"上川内生涯学習課長","answer":"区民公園のプールの使用料ですが、平成１３年度は一般開放で２９３万8,０００円、団体、ロッカー使用料を入れて３０７万円余りです。１４年度につきましては、一般が３８９万2,１００円、トータルで、団体、ロッカー等で３９３万円余りです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"嶋委員","kind":"質問・要望","question":"あわせて利用人数を教えていただきたいと思います。","respondent":"上川内生涯学習課長","answer":"人数につきましては、１３年度が１万1,４５３人、これは一般開放の分です。平成１４年度は１万4,５２１人です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"嶋委員","kind":"提案","question":"私のほうにお手紙をいただいたのでちょっとそれをご紹介しながら質問させていただきたいと思います。この方の希望は、朝昼晩と３回に分けておりますので、このうちの１回の１時間でも２時間でもいいから、高齢者や障害者のためのプールのコーナーをぜひつくっていただきたいという要望があるんですが、プールに関しては障害者とか高齢者に対してのどのように配慮されているのかお聞きしたいと思います。","respondent":"上川内生涯学習課長","answer":"今、障害者とか高齢者とか、ハンデを持った方への配慮ですが、あそこは屋外プールでございまして、今現在はそのようなことをしておりませんが、今後、委託をしておりますので、その事業者のほうと検討しながら、よりよい使いやすい方向に検討していきたいと思います。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"コインシャワーの、平成１１年にもお願いをいたしましたが、これはクラブハウスの温水シャワーだと思いますが、そのときにも、ぜひお金を使ってもいいから区民プールにも温水シャワーを出していただきたい。クラブハウスだけではなくて、区民プールのほうにも引いてもらいたいということをお願いしておりますが、その後の経過を教えていただきたいと思います。","respondent":"松代道路公園課長","answer":"私どもは昨年、プールの前の舗装等も実は少し改修をしまして、新しくしました。今後もそういった形で施設等も順次、計画的に補修等をしてまいります。そういった中で、大規模な改修の際、そういった温水シャワー等のことも検討してまいりたいと、このように考えているところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。たしか平成１２年のときも、大規模なときに、そのときも同じ答弁でございました。それがいつなのか、もし計画があるならば、そのときにも近い時期という答弁しかありませんでしたので、ぜひまたもう一度、近い将来ということではなくて、もし年月日がわかるようでしたら、教えていただきたいと思います。","respondent":"松代道路公園課長","answer":"いま少し、クラブハウス、またプール等は補修等を加えながらご利用いただけると考えていますので、まずは補修をしながら利用いただいて、抜本的に改修をしなければいけない時期が当然来るだろうと思いますので。","voiceIndex":23,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。１３１ページの歩きたばこ防止過料に関連してお伺いいたします。いよいよ品川区も歩きたばこ防止ということで、大変うれしく思っております。私は青物横丁のことでお聞きをしたいと思いますが、シーサイド駅ができまして、企業が入りまして、朝のサラリーマンの方が大変青物横丁を乗降されます。それに対してちょっとご説明をいただきたいと思います。","respondent":"長田地域活動課長","answer":"通学時間帯ですけれども、これは今後、どういうような形で監視をしていくかという部分を決めていかなきゃいけないわけですけれども、条例ができたからといって、四六時中監視はできませんので、特に朝夕の人通りの激しい帯ですとか通学時間。","voiceIndex":25,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"区長は先日の本会議の質問で、塚本議員の質問に対しまして、「区政の主人公は区民であり、行政は区民の信託を受け運営されるものです。」私は、本当にこれは正論、正しい答弁だと思いますけれども、区長が今後、区政運営に当たりまして、こうした立場をあらゆる分野に貫いていくのかどうなのか、あるいは建前、相対的、精神的なものを言ったものであるのか。","respondent":"高橋区長","answer":"そのようにやってきたつもりですし、これからもやっていきたいと考えています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問・要望","question":"私はそういう点でもう一方、この問題でそういう方針を貫くということですので、お尋ねしたいんですが、政策決定、意思決定をする前の段階にも住民の意見を聞くのか、意思決定をした後に住民によく説明し意見を聞いて進めるのか、どちらなんでしょうか。私は政策の意思決定前に十分住民の声を聞くことが大事だし、そのことを全国が求めていると思いますけれども、区長の見解を再度お尋ねしたいと思います。","respondent":"高橋区長","answer":"そうしませんと、私は区政が停滞するだけだと考えています。そういう意味で、常時区民に対しまして耳を傾け政策決定をしているつもりです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"これまでこうした問題を質問しますと、いや、議会は住民から選ばれたんだから、住民意思の代表機関だ。だから議会の意見を聞くことが住民参加なんだと区長はたびたび答弁されましたけれども、今の答弁では、区民の声に常時耳を傾け、政策決定から政策の遂行までやるんだと言ったんですが、そうとらえてよろしいでしょうか。","respondent":"高橋区長","answer":"管理職の試験に議会と住民集会との関係についての問題が出たこともございました。私はやはり議会を補完するものが住民集会だと考えています。したがいまして、住民集会を開かなければ政策の決定ができない、こういうことは、私はないと考えています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"具体的な問題で、今政治課題といいますか、大きな争点になっている小中一貫校の問題について聞きたいと思います。昨年、文教委員会で、私はなぜここで質問するかといいますと、先日、小中一貫校の建設でなく、３０人学級をという趣旨の請願が出た審議の際に、この問題を私が聞きましたら、請願の審議に反するから予算特別委員会等でやってほしいというので、あえてこちらで聞かせてもらいます。","respondent":"鷹倉庶務課長","answer":"私ども小中一貫校を進める際に、地元にいろいろ説明会に行かしていただきました。今回、日野中学校の学区域の中で、ぜひ自分たちの子どもも行けるような学級数にしてほしいという具体的な要望がございました。","voiceIndex":34,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"今の答弁は正確でしょうか。住民への説明は、その新聞報道があって以降だったのではないでしょうか。改めて聞きたいと思いますけれども、政策決定前に住民の意見、教職員の意見、文教委員会の意見は聞いたんでしょうか、どうなんでしょうか。","respondent":"指田教育次長","answer":"これは整理しますと、今回の小中一貫校の問題というのは、すなわち教育改革全体のプラン２１を進める中の一環の一つですということはおわかりで、お話をしているとおりであります。先般の本会議につきましても、そのことを答弁したわけです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"先日の文教委員会の審査の中で、教育次長はこう言っています。「区長の発言は相対的、精神的なものとして言った」と。「すべて区民の声を聞くという考え方を持てば、行政は停滞するだけ」と述べた。私はここで区長に聞きたいんですが、区長の、区民が区政の主人公だという発言は、改めて相対的、精神的なもので、聞いていれば行政は停滞をするというのは区長の考えなんでしょうか。","respondent":"指田教育次長","answer":"そのときの大事なことをお忘れになってお話をしてございませんか。私は、ケース・バイ・ケースで、いろいろなことが出てまいりますということを言ったつもりです。そのことを飛ばしておいて、なぜそういうことを言うんですか。","voiceIndex":38,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問・要望","question":"「行政の停滞をもたらす。区長の発言は相対的、精神的なものだ」、私はこのことが、区政の基本姿勢であれば、こういう発言は出ないし、先ほど区長の区民の意見は常時耳を傾けて事に当たるという、これと教育委員会のこの姿勢は全く逆なんじゃないかと今の答弁は思わざるを得ませんけれども、改めて区長の見解を求めたいと思います。","respondent":"高橋区長","answer":"部分的な問題は往々にしてそれだけをとらえますと否定になる場合もあります。全部読みますと肯定していますけれども、その部分だけとりますと否定する場合もあります。そういう意味で、これからの発表は部分じゃなくて、すべての問題を発表していただきたいと、そう思っています。","voiceIndex":40,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"その発言は全体を近く議事録ができますので、ごらんをいただきたいと思います。次の問題なんですけれども、これまで保育園の保母の会だとか、学童保育クラブ連絡協議会だとか、あるいは介護保険の事業者の説明会だとか、区側にいろいろと会見を求めたことに対して、担当課長は、なぜここまで入ってくるんだ。こう書いてあります。こういう側面があると思いますけれども、この点についてはいかがでしょうか。","respondent":"小沼福祉事業部長","answer":"私どもは、区民は区民のご意見として承っております。父母連の問題がどうのこうのということは別の問題です。そういうことで、必要とあれば私どもは十分な対応をさせていただいてあります。","voiceIndex":42,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"もう一つだけ、今の問題は、私は取り消すべきだと思います。それから、これも２年前に取り上げた問題ですけれども、学童保育クラブ連絡協議会が、これは区長の裁断で改善されたということを述べておきますけれども、６回にわたる面談申し入れをして、１回は文書までやって、最後に私が質問して、区長が会えるようにしたというんですけれども、そのときの担当課長の発言なんですけれども、こう述べております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"沢田委員","kind":"意見","question":"改めて、こういう学童保育クラブだとか、保育園だとか、保育問題協議会だとか、こうした団体も含めて、住民と会うことが公務そのものなんだ、意見を聞くことは公務の中心課題なんだという姿勢を持つべきだと思いますけれども、区長の見解をお尋ねしたいと思います。","respondent":"高橋区長","answer":"それは沢田委員のほうからしますと当然のことだと言うかもしれません。だけど、保育園の運営の中に、大きな支障を残したことも事実です。そういうことを思っていただいて、この問題については、沢田委員もよくお考えになっていただきたいと思います。","voiceIndex":46,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"私は区政の主人公は区民でありというような今度の区長選の最大の争点だし、区民の最大の関心事だと思います。特に私は政策を決定する前の段階でどれだけ住民の声を聞くのか、決まってからその決定を徹底をするというのは住民参加ではない。常時傾けると言いながら、小中一貫校の問題でまともに意見も聞かなかったということを文教委員会で謝罪しているじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"建設的な議論をしていきたいと考えています。５８ページです。特別区財政調整交付金に関連して、それから一部事務組合に関連して、質問をします。それから、２３区それぞれの情勢が本来違うわけですから、各区の測定単位における微調整といいましょうか、その積み上げ、それから下げることもあるでしょうけれども、そういうような仕組みはどのようになっているんでしょうか。簡単に教えてください。","respondent":"市岡企画財政課長","answer":"ちょっとひっくり返した言い方ですけれども、こういうところに昼間人口を反映すると、品川区もだんだん財政状況がよくなって、都心区的な要素になりますので、そういう行政需要をルールの中に反映させることができる。こういう傾向になろうかと思います。","voiceIndex":50,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"きのうもいろんな議論がありましたけれども、例えば新しい区民のニーズの要望をどうとらえていくかということをきのう、我が党の幹事長が質問しました。だから、こういうところから実際は財調の問題があると思うんですが、このことについての議論をもう少し、今具体的に各区でこの測定単位そのものについての議論はどのようにされているかということをお聞かせください。","respondent":"市岡企画財政課長","answer":"それが先ほど申し上げたとおり、昼間人口をどう取り入れるかとか、あるいは例えば国保の問題なんかでも、収入の基準をとらえるときに、例えば生活保護世帯の世帯数の織り込み方、そのウエートをどうするかとか、いろいろいわば都心区的な区と、それから財調でいえば。","voiceIndex":52,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問","question":"要は、まず測定単位そのものの問題。それから、東京都がなぜ４８％にしたのか、その内容をいまだに２３区側に説明していないというふうな答弁があったんですが、そのことは本当でしょうかというのが一つと、それから、当然我々としては知りたいわけです。その４８％について説明はどういうふうにされるべきかということは非常に関心がありますので、わかっているところで結構ですから、ご答弁をお願いします。","respondent":"市岡企画財政課長","answer":"しかし、それでは、新しい都区制度の基本にかかわる問題は一向に解決しないので、本会議のときにもいろいろご指摘いただきましたが、ようやく１８年度に向けて都区間でこの問題を年々の都区財調協議の中とは別に検討会を設けて議論をするということになりまして。","voiceIndex":54,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、その積み上げをしていって、結果としてこの５２％の中から、そうじゃないと、こちら側だという議論をしていったほうが私は理論的かなと思うんですが、要するに東京都の仕事の範囲と品川区なら品川区の仕事の範囲、事務の範囲、これは非常にはっきりと明確にしていく必要があると思っているんですが、そのことの今考え方と、それから議論。","respondent":"市岡企画財政課長","answer":"これは賛同する他の２２区を募らなければいけない話ですけれども、こういう根本的な議論を１回やってみる必要があるのではないかと、検討会ではこういう主張をしてみたいと考えているところです。","voiceIndex":56,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"ところが、２３区の場合にはどうですか。非常に大きな自治体です。ところが、人事面も、定期代までも一緒の話ですから、どう考えてもおかしいんです。それをどうしてもやっていかなければならないということでずっと指摘をさせていただいているところでありますから、事務の範囲、特に東京都と２３区の、特に品川区の間だけでもとりあえずは結構ですから、品川区はここまで責任を持ってやります。","respondent":"市岡企画財政課長","answer":"これを実務の世界に落としてくると、いろいろな法律が絡んでいたり、それからこれまでの経緯が絡んでいたりして、例えば都市交通なんかについても、我々からすれば逆にこういう都市交通こそ東京都がやる仕事だと思いますけれども。","voiceIndex":58,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"なぜ時間稼ぎをするのか。そういう危機感があるがゆえに、あえて質問していますので、なぜ東京都が時間稼ぎをしているのかという客観的な感想と、それからもっと根本的な部分で、すぐにはできないと思いますが、自治権確立運動のようなイメージで財源移譲とか権限移譲、東京都と２３区の仕事の役割分担というものを広範囲に広げていくべきと思いますが、いかがでしょうか。","respondent":"中尾根企画部長","answer":"それから東京都と２３区側の問題もそこのところに最大の今、改革するメリットがある、こう私どもは考えておりまして、これは今後とも区長も何回も言っておりますけれども、品川区としてはそのことについて全力を尽くしていきたい、こういうことです。","voiceIndex":60,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"繰り返しますが、時間稼ぎの答弁があった感想をお聞かせいただきたいのと、それからあとは、非常に長い時間がかかることは覚悟しておりますけれども、指摘しておきたいのは、こういう制度というのは非常におくれていますね。社会の変動がものすごく進んでいる。インターネットだ、いろいろな仕組みも進んでいる。時間稼ぎの部分の感想をお願いいたします。","respondent":"市岡企画財政課長","answer":"私は全くそうではなくて、都は広域自治体に徹し、基礎的自治体である特別区が区民のすべての生活の課題についてこたえるべきだと考えているところです。","voiceIndex":62,"id":"exchange-029"},{"speaker":"川西委員","kind":"質問","question":"使用料の６４ページと６８ページです。一つは、区民集会所使用料について、今年度、地域センターとして新しくリニューアルの計画がありますけれども、使用料は前年どおり組んでいられるかどうか伺います。それから、同じく使用料で、６８ページの衛生費の検便関係の衛生試験所のことです。とりあえずこの二つを伺います。","respondent":"長田地域活動課長、田中健康課長","answer":"質問の第１点目、区民集会所の使用料ですけれども、区民集会所の使用料につきましては、例年の実績等々を参考にいたしまして、若干ずつ組み直しています。そういう意味では、衛生試験所の法的な根拠といいますのは食品衛生法上等にありますけれども、その機能の中心に、本来私どもがきちんと持っているべきであろうものを残すという意味合いの中で、他のものについては。","voiceIndex":65,"id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"あるいは今、一部ボランティアの人たちが打ち合わせをする場所等も研究していらっしゃるけれども、あるいは部分によって、場所によって設置していらっしゃるけれども、ああいうのをもう少し拡充して、地域センターとして利用できるためには、今年度は本当は使用料を減らして、例えば過去には必要であった和室みたいなものはシルバーセンターで十分活用もできるので、そういうところをロビー。","respondent":"田中健康課長、長田地域活動課長","answer":"衛生試験所の老朽化というお話が出ましたが、確かにあそこは３階、４階部分、試験所の部分については工事等を必要な部分だけ調整してきたこともあります。その集会室をつぶしてロビーという部分につきましては、いろいろな設備的な条件等もありますので、今すぐは難しいかと思いますけれども、昔、管理人がいたときの若干のスペースを今、倉庫にしたりしていますけれども。","voiceIndex":68,"id":"exchange-031"},{"speaker":"川西委員","kind":"質問・要望","question":"過去において、品川荘とか、箱根荘とかへ行きますと、葉書にいろいろ書いてありまして、ご要望があったらマル・バツを書いてくださいなんていうことがありました。あれはとても役に立っております。１園じゃなくてもいいですけれども、１５年度、調理委託を実施したことによって、費用対効果のこともありますけれども、どれだけ人件費が浮くのか、費用が浮くのかということがわかったら教えていただきたい。","respondent":"田中健康課長、金子保育課長","answer":"これの積算につきましては、人件費といいますか、小児の医師が１名、それから看護師が１名、事務が１名ということがほとんどのところでございまして、あとは多少の光熱水費等々を見て予算として基準額が組まれております。これも概してで恐縮ですけれども、大体今までの人件費から見ますと２分の１弱の費用になっているです。","voiceIndex":71,"id":"exchange-032"},{"speaker":"川西委員","kind":"質問・要望","question":"要望です。その子どもの体質がどういう経緯で１歳になったのか、２歳になったのか、５歳になったのかによって治療の方法も異なると考えます。例えば青山病院、昭和大学病院に救急車で行かせたほうがよいのかどうかという判断もその辺でつくのかなとふだんから思っておりますので、この辺について、小児の健康手帳のようなものを将来もこれを機会に考えていただけたらと、これで要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-033"},{"speaker":"山路委員","kind":"質問・要望","question":"電柱というのは、直接、品川区の事業じゃないと思うんですが、この電柱に関しまして、歳入のところに、あらゆるところにいろいろ、私も土木関係のところだけかなと思いましたら、一つは６９ページの民生使用料とか、６７ページの総務使用料とか、８１ページの教育使用料のところに電柱ということが書いてあるんですが、どういう意味か、どういう関係にあるのか、ご説明をしていただきたいと思います。","respondent":"岩田管理工事課長、早津高齢福祉課長、鷹倉庶務課長","answer":"土木関係のところに書いてあります主に道路占用の部分での電柱につきましては、これは道路法に基づく占用許可手続を行いまして。民生費で電柱が出てまいりますのは、土地建物使用料というような形で民生関係の施設の敷地内に電柱があるものが何点かございまして。同じく教育委員会の使用につきましても、学校内に電柱がある、こういう関係です。","voiceIndex":76,"id":"exchange-034"},{"speaker":"山路委員","kind":"質問・要望","question":"占用使用料ということで考えてよろしいかと思うんですけれども、この電柱にかかわるいろいろな問題が地域ではございまして、平成１５年度の予算書の中では、電線の地中化を計画されて、これから進めていかれると思うんですけれども、そのとき、トランスとか、いろいろ地中に埋められるのか、または地上に出されるのか、この辺について、ちょっと聞かせていただきたいと思います。","respondent":"岩田管理工事課長","answer":"しかし、ここ１～２年の技術革新の中で、新たな電線類の地中化方針というのが今、国で検討されております。","voiceIndex":80,"id":"exchange-035"},{"speaker":"山路委員","kind":"質問","question":"ここで、電柱とか地中化、今後のことに関しまして、健康被害についてちょっとお伺いしたいんですが、電柱の場合は全部じゃないと思うんですけれども、特に高圧線の場合は、電磁波が非常に強くて、通学の子どもたちにということで一部新聞報道に出ておりましたが、その因果関係については掌握されているかどうか、あるいはトランスの設置によりまして、全く電磁波の影響はないのかどうか、その辺について。","respondent":"金井環境課長","answer":"新聞紙上ですとか、国等でも一定の研究、検討はしているように聞いておりますけれども、特にここのところ、はっきりとした、そういったような健康被害というものはまだ明らかになっていないという状況だです。","voiceIndex":82,"id":"exchange-036"},{"speaker":"山路委員","kind":"質問・要望","question":"一方、地上波というのがまた、これは健康によいと言われているんですけれども、地上波というのは区民生活におきまして、どういうところから発しているか、その中身がわかったら教えていただきたいと思います。","respondent":"金井環境課長","answer":"大変申しわけありません。私もまだ地上波の関係については情報を得ておりません。","voiceIndex":84,"id":"exchange-037"},{"speaker":"山路委員","kind":"質問・要望","question":"区民の健康を守るということで、これからどんどん時代とともに電線の地中化とか計画されているわけですけれども、電磁波とか、あるいは地上波とか、いろいろ区民の健康にいいことはどんどん推進して、また悪いことは測定を最低、記録するとかして啓発するとか、そういう対策、対応を今後とっていただきますように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"継続して補助金は実施されていくのか、この点が１点。１月の都議会の中で、その質問が出たので当然だなと思っていたんですが、それに対して区のほうは、先ほど人事委員会規則で決まっているということで、区の中で検討して、既に今までも当然人事委員会に申し出をしていたのか、今後の対応は当然として、今までの状況はどうなっていたのか、その点をちょっとお答えをお願いしたいと思います。","respondent":"宍戸ＩＳＯ担当課長、桑村人事課長","answer":"照明設備の改修工事につきましては、率としては２分の１を見込んです。それから省エネ対策結果報告書、これは１０分の１０の補助金を見込んです。東京都も検討しているということもありまして、私どもとしても６カ月定期にするように検討すべきだというようなお話は人事委員会のほうに文書等で出しています。","voiceIndex":88,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ＮＥＤＯのほうですけれども、今、名前を聞いて思い出したんですけれども、学校のＩＳＯか何かで、学校に対して実施してくれる財団ですか。それから、人事委員会のほうに書類を送ったというのはわかるんですけれども、今までの段階において、区の中でどういう検討をしていたか、そっちのほうをもう１点、お願いしたいと思います。","respondent":"宍戸ＩＳＯ担当課長、桑村人事課長","answer":"今回、報告書をつくる予定になってありますけれども、この報告書の中で、そういったほかの皆様方に使えるような、区内事業者の方々に使えるような補助金も紹介しながら、区でやった実績について。正直言いまして、事務的に考えれば４月、１０月というような形にある程度決めて６カ月分まとめて払うというやり方のほうが仕事的には楽なわけですけれども、どういったやり方が事務的にやれるのか、また、今後。","voiceIndex":91,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"省エネのほうは各企業、成果を生かしていただいてＰＲ、区内事業者の方も使いやすいような形をお願いしたいと思います。それと職員費の定期代のほうですけれども、今の検討状況ではなくて、それまで区の中で６カ月定期を買わず、１カ月だったということ自体を検討なさっていたのかなという、そっちの意味なんです。その点をお答えいただきたい。","respondent":"桑村人事課長","answer":"この間、６カ月定期の問題は何回か質問も受けて、その意味で検討したところですし、ただ正直言いまして、人事委員会規則ということもあって、その後、実現につながっていないわけですけれども、今回、この２～３年、各都道府県が一斉にそういうことを何県か入り出した。","voiceIndex":94,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"人事委員会に対しては、継続して、本当にこの点、むだな経費というと失礼な言い方かもしれないですけれども、職員の方の作業は出ると思います。例えば民間の方でやっぱりいました。６カ月定期を買っています。１カ月掛ける６でもらうのと、６カ月で買うと先ほどＪＲで２割減るということがありましたけれども、その辺のチェックはどこかの部署でなさっていらっしゃるんでしょうか。","respondent":"桑村人事課長","answer":"実際上どういうふうな形の定期を買っているかというのは、正直言って調査をしているものではございません。その本人のどの程度の経費をある程度見込めるかということがあろうかと思います。その意味では、そういう意味でのチェックは正直言ってやったことはございません。","voiceIndex":96,"id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それともう１点、逆に定期の経路です。例えば新しくりんかい線ができたから、この路線を使っていいかどうかというのは、企業によっては、例えば１５分の通勤時間が短縮できたら新しい経路で回ってもいいというようなケースがありますけれども、当然、品川区として、経路は時間的なものでやっているのか、金額的なものでやっているのか、その辺はどちらでしょうか。","respondent":"桑村人事課長","answer":"今回、りんかい線につきましても、その意味では違う路線をまたＪＲに乗り継ぐような方が増えてまいりますので、その意味では経済的にはちょっと難しいというのが今の判断です。ただ、その分を負担して乗ってくるという職員もおります。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それを経路として認定していただく。前にちょっとお聞きした中で、例えばお子さんを保育園に預けていくので、そっちへ行ってから来るので、その経路を認めているというお話を聞いたことがあります。品川へ行って大井町へ来る。定期を本当に買っているのという疑問も感じるところもちょっとあるんですが、そういう面でのチェックをなさっているのかなという確認なんですが。","respondent":"桑村人事課長","answer":"それは先ほど言いましたとおり、経路の認定とすれば、品川を回ってＪＲで大井町に来ていただく。ただ、実際上の通勤手当の額は横浜で乗りかえてＪＲで来てもらうというような形で使い分けているところがあります。","voiceIndex":100,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、逆にそっちのほうはもっときちんとしたフォローをしてもらいたいなと。この件について、総務委員会でも、今までも再三ご答弁もいただいておりますし、法務省からも、東京法務局民事行政部長からの統合についての依頼文も出ておりますが、この進展状況と区民サービスという面でどういうふうに考えられるか、もう１回、お願いいたします。","respondent":"桑村人事課長、西島経理課長","answer":"ただ、この辺のところは、正直言いまして、例えば年次休暇をとればどうだったのかとか、個々の職員をとらえれば相当大きな差が出てまいりますので、一定の平均で算定するのはやむを得ないものじゃないかと思っておるところです。この中では、当初１５年２月を目途として統合を進めてまいりましたが、地元住民の皆様に対するご説明の期間等を考慮して、統合実施期間を１年ほど延ばしてというふうに明確にうたってあります。","voiceIndex":102,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区民サービスという意味で、大田に移されるのでなく、ぜひ大田から品川へ持ってくるように、区としてさらに強調していただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-046"},{"speaker":"高星委員","kind":"質問・要望","question":"１５分しかありませんので、私は簡単に３点ほど質問しますので、簡単に、明快にお答えいただきたいなというふうに思います。最初に、一つは、財政当局にお聞かせいただきたいんですけれども、せんだって本委員会の中で補正予算が審議されて、それぞれ賛成、反対の意思を表したところでありますけれども、どうなんでしょうか。補正予算というものが、例えば本予算があって、補正予算があるわけです。","respondent":"市岡企画財政課長、田村住宅課長、西島経理課長","answer":"ご提案申し上げている私どもとすれば、当初予算も含めて、補正予算も含めてご賛成いただきたいわけですが。ただし、購入経費だとか、区が持ち出しで出している部分がありますので、あるいは国の補助、都の補助を受けていますが。これは5,０００万円以上の工事ですけれども、この掛け金収納書を契約係に提出することということで普及を図っているところです。","voiceIndex":108,"id":"exchange-047"},{"speaker":"高星委員","kind":"質問・要望","question":"この中で、こういう私どもの建設現場では、この工事の元請事業主は建設業退職金共済制度にきちんと加入していますということで、そういう張り紙をして、品川区の場合は5,０００万円以上のものについてはその報告も求めているということであるようでありますけれども、現実的な話を聞きますと、共済のほうからシールを買ってきて、そのシールは実はなかなか現場の方々には届いていない。","respondent":"田村住宅課長、西島経理課長","answer":"委員ご指摘のように、確かに団地ごとに使用料の明細を明らかにしてというようなご指摘ですが、やはり当初は使用料収入、当然、建設型ですと土地代、建設代、設計費代、あるいは建築工事代ということで。国がつくった制度ですので、自治体としてどこまでというところはありますけれども、これがうまく普及するように、工事の現場あるいは契約の現場でそれについては検討してまいりたいと考えています。","voiceIndex":112,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３３０ページの職員費についてお伺いをします。保健所と保育園のところを伺います。保健所ですけれども、まず、保健師の配置をされている場所と配置の数と主な仕事の内容を教えていただきたいと思います。保健師の１人当たりの受け持ち人数、２３区の平均と比較をして適正なのかどうか、その辺も含めてお願いいたします。","respondent":"桑村人事課長、田中健康課長","answer":"一つは、健康課の本課におります。それから、高齢福祉課、各保健所、保健センターのサービス課、あと大井保健相談所です。受け持ちの仕事の内容等はちょっとまた別の者がお答え申し上げたいと思います。現在では精神のほうのいろいろなご相談にも乗っている。これが大きな分野です。","voiceIndex":116,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"済みません。配置の数をお伺いしたので、減員になって何人なのか、それぞれのところで。","respondent":"田中健康課長","answer":"現員計は３６名です。それから、住民１人当たりの職員数ですが、こちらは今、詳しい数字を持っておりませんが、たしか１万人をちょっと切る状況に私どもの数字ではなってあります。","voiceIndex":119,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"意見","question":"２３区との比較で、適正かどうか、その辺の数の評価の仕方を。","respondent":"田中健康課長","answer":"私どもは２３区のデータですとかを見ている限りは、私どもの現在の保健師の職員数について、少ないということは少なくともないだろうと考えています。","voiceIndex":121,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２３区の平均の受け持ち数を、ちょっと古い数字なんですが、7,４００人ぐらいなので、品川区はそれよりもかなり多いかなという評価を私はしています。今、仕事の内容の主なところをお伺いして、かなり多岐にわたってお仕事をされていると思うんですけれども、その中で、特に精神保健のところが今すごく求められているのではないかと思っています。","respondent":"小林品川区保健所保健サービス課長","answer":"ただし、品川区におきましては、保健師以外に心理職を保健所、保健センターに３名配置しておりまして、他区との比較は一概に保健師の数だけでは論じられないのではないかと考えておりますので、保健師の現在の業務の中で仕事の見直しを進めていく中でそれぞれの役割。","voiceIndex":123,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面でのコーディネーターとしての保健師の役割はすごく重要だと思うので、今回の削減は、その辺の相談業務に支障が出るのではないかとすごく懸念をしているんですけれども、いかがでしょうか。","respondent":"小林品川区保健所保健サービス課長","answer":"電話相談の中身ですけれども、軽微なものから重いもの、さまざまでございまして、ご指摘のように、いろいろな精神保健にかかわるご相談、それから初めは母子の相談であっても、それが精神保健にかかわるといったような思いがけない展開になってくることも実際ありますので。","voiceIndex":125,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"現場はかなり仕事をこなしきれなくて、大変な状況であるなと思うのは、ちょっと保健所の関係の組合の役員の方からご意見をいただいたんですが、紹介します。かなり相談が多い中で減らされることに対して、現場からは不安の声が出ています。私は本当に今、こうやっていろいろな相談が増えている中だからこそ増やしてほしい、減らすなんてとんでもないと思うんですが、その点について一言。","respondent":"田中健康課長","answer":"保健師の業務というのは、先ほど人事課長からもありましたとおり、高齢福祉課、健康課にもいろいろ職員はありますし、それから、今回、健康づくりプラン２１という、今名称を変えようと言っていますが、そういうことも始めております。","voiceIndex":127,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保健所というのは、本当に区民の健康を守る最前線というか、区民に本当に近いところにいるので、私はぜひ充実をさせていただきたいなと思います。給食の調理代行のことですけれども、３１名の減ということで、さらにまた委託が拡大をするということでは、問題点が出てきているのではないかと思うので、その問題点をお伺いしたいのと、委託の新年度２８園、何社がかかわっていくのか、その辺を教えてください。","respondent":"金子保育課長","answer":"この間、何度か、この委員会等でもご説明申し上げましたとおり、非常にいい効果が上がってきているということがあります。","voiceIndex":129,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"よい効果が出ているということなんですけれども、もちろんよい面も出ていると思うんですけれども、１社で大体３から４園受け持っているところで、私は人手の確保に困難なところというか、むらが出ているのではないかというので、一つ、例をお示ししたいんですが、１４年度委託が始まったところで、パートの定着ができなくて、おいしい給食がつくれていないという例があるので。","respondent":"金子保育課長","answer":"その結果、委員もご存じかもしれませんけれども、現在の段階では、子どもが大変おいしいカレーだということをおじいちゃん、おばあちゃんに伝えているという話を聞いているところです。","voiceIndex":133,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"意見","question":"ようやくとおいしくなったということなんですが、４月から１２月まで味覚を育てなくちゃいけない子ども、離乳食の大事な時期に、おいしくない、大好きなカレーがまずい。この事実は認めますね、課長。この事実があったことをきちんと認めるかどうか。そして、この問題点をどう今とらえているのか。何が問題だったんだととらえているのか。そこをお聞かせください。","respondent":"金子保育課長","answer":"あるいは保育課にきちんと連絡を上げれば私のほうでも対応しますので、その辺の情報の整理といいますか、迅速かつ的確に情報を伝えるということを園長に徹底しておりますので、今後はそのようなことはないと考えております。","voiceIndex":135,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"事実があったことは認められたということと、あと、対策をとった。私は安い賃金でかなり厳しい仕事をしているという面では、私は定着しない、定着しないがために中身が改善、せっかく今よくなったけれども、また今、働いている方がかわってしまったら、またもとに戻る。やっぱり専門性がないとだめだというこの点をまず課長が認めるかどうか、お伺いしたいと思います。","respondent":"金子保育課長","answer":"私どもはこの調理代行業務を各業者にお願いするに当たって、このような献立の給食をこのような時間に、このぐらいの数を出してくれと、こういうふうな指示を出しておりますので、それが的確にされている限りについては、私どもとしてはそれ以上の指示はするつもりはございません。","voiceIndex":137,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"今回、認められた、本当に子どもたちにおいしい給食が、当たり前のところが出せなかったということに対して認めて、やっぱり改善策というんですか。きちんととらないと本当に繰り返すと思うんです。だから、やっぱりこの間で何を教訓として今後に生かしていくのか、再度お尋ねします。","respondent":"金子保育課長","answer":"そこで問題が解決しない場合には、必ず私のほうに上げる。そういったことを徹底することによって、この調理代行の業務というものが味も含めて、すべて効果の点で問題がなく執行できると考えております。","voiceIndex":139,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"意見","question":"私は子どもたちにおいしくて、安全な給食をつくっていくためには、本当に専門性が大事と思っています。そういった面では、今、方向として全面的委託だと本当に水準が下がっていくと思います。ぜひ直営の保育園給食を本当に残していってほしいなと強く望みます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-060"},{"speaker":"本多委員","kind":"質問・要望","question":"先日の議場で、我が党の伊藤議員より一般質問で、りんかい線の開通後、臨海高速鉄道の債務返済するに当たりましての利用者の現況ですとか、今後の取り組みということでは、２７年目からは黒字転換にしていくという状況をお聞かせいただきましたが、まず品川区について、平成７年度から８年間で３６億円の貸付金ということで、７年間の据え置きの２０年間で均等償還ということで。","respondent":"伊佐都市計画課長","answer":"この前提としては、利用客数が予想どおり確保されることが前提となります。現時点で、先ほどご質問がありましたとおり、想定している１日当たり９万7,０００人という乗客数はほぼ確保されている状況でございまして、今後ともこの利用者増しに努めていくと聞いてあります。","voiceIndex":143,"id":"exchange-061"},{"speaker":"本多委員","kind":"質問・要望","question":"その後、やはりこれは臨海高速鉄道の事業ではあるが、品川区としてもまちづくりとして品川は品川の魅力を出して、品川区としても乗客を伸ばすというようなことを言われておりますが、それと償還とのかかわりについて、品川のまちづくりとしてその辺の今後のあり方についてお伺いしていきたいと思います。先に品川のまちづくりとしての乗客を伸ばす点と償還のかかわりについてお伺いしたいと思います。","respondent":"伊佐都市計画課長","answer":"りんかい線の経営に当たって、将来の利用増を見込むときに、例えば臨海副都心の今後の開発等も織り込んですし、品川区内では、例えば大井町、大崎、それから品川シーサイドといった開発の数字も織り込んです。","voiceIndex":145,"id":"exchange-062"},{"speaker":"本多委員","kind":"質問・要望","question":"これからもいろいろなイベントがあると思うんですが、例えば今まで山手線を使った福祉の「夢さん橋」ですとか、そういった面も、いろいろと品川区としてイベントの面でバックアップをされていると思うんですが、今後の乗客を増やしていくという見方から、ハード面だけでなくソフト面でのバックアップ体制というんでしょうか。","respondent":"伊佐都市計画課長","answer":"こういったことで、今後とも、区といたしましてはハード、ソフト連携したまちづくりの支援を協力してやっていきたい、コーディネーターとしての役割を果たしていきたいと考えています。","voiceIndex":147,"id":"exchange-063"},{"speaker":"本多委員","kind":"質問・要望","question":"それと２点目に移らせていただきますが、１３８ページの同じく諸収入の５目雑入、すまいるスクールの参加費９４６万8,０００円なんですが、これまで１４年度までの４校での児童の登録数は７割から８割の登録というデータが出ておりますが、１５年度は１５校の新設で１９校になるということなんですが、この参加費の９４６万8,０００円に対するカウントについてお聞かせいただきたいと思います。","respondent":"富田教育改革担当課長","answer":"勉強会につきましては、各学校とも約８０人程度の勉強会参加を見込んでおりまして、既存の４校につきましては、４校分、通年ということで、およそ３１３万円、そしてまた新規１５校につきましては、半年分ということで６３３万円を計上しているものです。","voiceIndex":149,"id":"exchange-064"},{"speaker":"本多委員","kind":"質問・要望","question":"その方は、じゃあ、学童に入れるしかないのかなというので、いや、今年できますからということで、ちょっと周知が足りなかったのかなと思いまして、我々もしっかりと、例えば１５年度から１５校増えるんだといったような話は、そういったことを聞けばお答えはしていくつもりなんですが、そういった意味での周知の徹底というんでしょうか。","respondent":"富田教育改革担当課長","answer":"ご指摘の１５校の学校についての周知が足りないのではないかというご指摘でございましたけれども、私どもは学校長の意向等を含めてこの１５校を決めたわけですが、学校選択の時期、あるいは年内ぐらいにも。","voiceIndex":151,"id":"exchange-065"},{"speaker":"本多委員","kind":"意見","question":"当然手続というものがあるわけですけれども、できる限りのご努力をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-066"},{"speaker":"中島委員","kind":"質問","question":"私は使用料および手数料の中の使用料、３目衛生使用料の中の健康センター使用料、これは７０ページです。それから１３４ページ、諸収入の受託事業収入の中にあります３目土木費受託収入の街路樹整備費収入、ここについてお伺いをいたします。初めに、健康センターの使用料に関連してなんですが、昨年の決算特別委員会のときにホールの空調の件で私は利用者の方の声をお伝えいたしました。","respondent":"田中健康課長","answer":"実はいろいろ抜本的な問題等ございましたけれども、とりあえずできる方法の中でという選択肢を今回選ばせていただいてやらせていただくつもりです。","voiceIndex":155,"id":"exchange-067"},{"speaker":"中島委員","kind":"質問・要望","question":"そうしますと、温度の調整というのはかなり改善されるのでしょうか。できる範囲の中でというのはいろいろありますので、その辺のところを具体的にお答えいただきたいんですが。","respondent":"片田施設担当課長","answer":"今のご質問ですけれども、一応いろいろな調整ができるような形で、早い時期に検討してまいりたいと思っていますので、よろしくお願いしたいと思います。","voiceIndex":157,"id":"exchange-068"},{"speaker":"中島委員","kind":"質問","question":"いろいろとれるご答弁だと思うんです。早い時期といっても、夏に間に合うのかどうか、その辺のところまで具体的にお願いします。","respondent":"片田施設担当課長","answer":"夏に間に合うような方向で一応検討してまいりますので、よろしくお願いしたいと思います。","voiceIndex":159,"id":"exchange-069"},{"speaker":"中島委員","kind":"質問","question":"期待をしていきたいと思います。やはり多くの方が利用されておりますので、最大の努力をお願いしたいと思います。次に、土木費受託収入の街路樹整備費とありますが、大井町駅西口駅前広場と、こういうふうになっているんですが、どこの整備なのか、新しく木が植えられるのか、現存の木なのか、その辺のところを教えてください。","respondent":"岩田管理工事課長","answer":"この街路樹整備につきましては、りんかい線の大井町西口の駅前広場と斜面の道路部分に工事が始まる前にケヤキ並木がございましたけれども、このケヤキ並木を復旧する工事でございまして、現在、工事をやっております鉄道建設公団のほうから区が受託しまして。","voiceIndex":161,"id":"exchange-070"},{"speaker":"中島委員","kind":"質問","question":"それと新しい植えられる木もあるんですが、マクドナルドの前にも木が１本ありました。それから、三井地所との間にも木が１本植えられて、両方とも周りにベンチが腰かけられるように、木陰に座れるようになっているんですが、実はあそこのところの整備というのは何か考えておられないでしょうか。夏場は木陰でとても休むためにはいいんですけれども、人間より先にハトのほうがあそこを占領してしまいます。","respondent":"松代道路公園課長","answer":"例えば街灯とか、そういったほかのものについては、ハトがとまれないような工夫をして比較的被害を少なくしておりますけれども、樹木に関してはいかんせんとまれないようにはなかなかできませんで、その辺が非常に頭の痛いところです。","voiceIndex":163,"id":"exchange-071"},{"speaker":"中島委員","kind":"質問","question":"せっかくの緑ですから、このよさも生かしたいんですが、やはり夏は木陰が必要である。せっかくのベンチがまた生きるような方向で、ぜひ私はお願いしたいと思います。それから、高木を植える場合も、いろいろな鳥の習性とか、さまざまな角度から考えて植樹をしていくということもこの都心の中では必要ではないかなと考えておりますが、その点ではいかがでしょうか。","respondent":"岩田管理工事課長","answer":"高木の復旧工事につきましては、これは前々からありました大木のケヤキを１３本復旧する予定です。それから、ハトの対策につきましては、西口については、私どもが把握しているだけでお２人の方が毎日えさをまきにいらっしゃいます。","voiceIndex":165,"id":"exchange-072"},{"speaker":"中島委員","kind":"質問・要望","question":"公園を利用されている若いお母さんたちからも、テーブルがちょうど木の下にあるけれども、動かせるようにしてほしいなどという声もあります。せっかくの座れる場所に危なくて座っていられないということもありますので、これから、課題は難しい課題だと思いますが、その辺のところもせっかくの自然が少ない都心での大事な緑ですので、みんなが共有できるようにご検討いただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-073"},{"speaker":"北野委員","kind":"質問","question":"私は４項目でお伺いしたいと思います。８３ページの総務手数料の中の住民票写しと住民基本台帳カード交付、それと３００ページの職員費、３３６ページの予備費についてお伺いします。職員費についてですけれども、こちらのほうには、職員の不祥事という問題がありましたけれども、住民の方からどういうようなご意見が寄せられているんでしょうか。その点についてお伺いしたいと思います。","respondent":"山田広報広聴課長","answer":"大変厳しいお声としましては、「区は強盗を養っているのか、税金を払わないぞ」というようなご指摘であるとか、「管理監督としての責任をどういうふうに考えているのか」、さまざまな側面からのご意見が寄せられています。","voiceIndex":169,"id":"exchange-074"},{"speaker":"北野委員","kind":"質問","question":"電話で６件、Ｅメールで６件ということでも、結構、住民の方からはいろいろなご意見が出されていますけれども、やはり信頼関係というのを復活していかなくてはいけない。本当にこの不祥事によって、イメージアップ運動を進めている品川区にとってはすごくイメージダウンがあるかと思いますけれども、今後、イメージアップに向けてどういうことを進めていかれるのかお伺いします。","respondent":"山田広報広聴課長","answer":"イメージアップからいたしますと、本来あるべき姿ではないわけですので、粛々と朝のあいさつ運動から始まって、それぞれの一人ひとりに訴えかけていくという形で運動としては進めさせていただきたいというふうに考えております。","voiceIndex":171,"id":"exchange-075"},{"speaker":"北野委員","kind":"質問","question":"ぜひ１日も早い住民との信頼関係の回復をお願いしたいと思います。次に、予備費についてお伺いしますけれども、予備費が３億円計上されておりますけれども、本来の予備費の目的というのをお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"なぜ必ず設けるかと申しますと、予備費は通常言われるとおり、予算に定めのない事項、あるいは予算超過の支出に対して対応することで、あらかじめ予算の形で議会にお諮りし、一つの科目として執行機関に執行を委任していただくことによって、軽微なもの、あるいは緊急なもの。","voiceIndex":173,"id":"exchange-076"},{"speaker":"北野委員","kind":"質問","question":"本来はやはり予測できないもの、災害とか不測の事態に伴う対策に充てるというもので計上されるべきものですけれども、決算書の説明などを見るといろいろな項目から予備費が上がっているわけです。本来予算できちんと上がっていればいいものであるし、また、補正予算で整理されるべきものだと考えますけれども、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"それ以外は、補正予算との関係で申しますと、本来から言えば、何か事態が起きたときに補正予算で議会にその都度お諮りするというのがある意味では原則だと思いますが、それでは、例えば水害なんかの場合には緊急に対応することができませんので。","voiceIndex":175,"id":"exchange-077"},{"speaker":"北野委員","kind":"質問","question":"通常の経過の中では、この予備費については補正でもわかりませんし、先決処分のときには、それがイコール予備費から充てられるというのがわかりました。これはやはり不測の場合、災害の場合は確かにそういうこともあり得ますけれども、実際はきちんと予算の中で明記していくことが必要なんじゃないかなと思いますので、その点について、もう一度お考えをお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"性質上、あらかじめこれまで実績として上がっているようなものについては、執行そのものは長の権限としてお任せいただいているものと思いますが、例えば委員ご指摘のような事故の報告、これは地方自治法に基づいて先決処分の報告を各常任委員会で行うわけですが。","voiceIndex":177,"id":"exchange-078"},{"speaker":"北野委員","kind":"質問・要望","question":"カード１枚1,０００円ということの単純計算をすると4,２７０枚ということで、８月以降の発行ですけれども、このぐらいしか見込みがないということなんでしょうか。お伺いしたいと思います。","respondent":"冨田戸籍住民課長","answer":"ただ、初年度ということですので、若干プラスアルファしています。ただ、これは８月２５日実施ということですので、約半年分ということです。通年という感じですと、その倍近くに行くのではないかと見ております。","voiceIndex":179,"id":"exchange-079"},{"speaker":"北野委員","kind":"質問・要望","question":"この住民票の写しというのは、年々というか、減ってきているという経過なんですけれども、住民基本台帳のネットワークが開通された場合は、品川区外からも結局要望は増えてくるわけですね。そうしたときの発行の数というのは、見込みですけれども、この中にカウントされていないんでしょうか。それはまだ予測がつかないということなんでしょうか。お伺いします。","respondent":"冨田戸籍住民課長","answer":"ただ、トータルとしては、従前とられている住民票の写しを超えることはないと一応は想定できますので、今回、特別に予算計上しておりませんけれども、この住民票の写しの中に含めた形ではおります。","voiceIndex":181,"id":"exchange-080"},{"speaker":"北野委員","kind":"質問","question":"また、国は当初予定よりも、当初は７３自治事務でしたけれども、現在は自治事務が２６４自治の事務に使われていくということで、前の決算特別委員会のときにお伺いしたときには、この国の使われたものが１通１０円で東京都に手数料が入るということでありましたけれども、そうしたときに、国がどのくらい使ったかということが区にはきちんと情報として入ってくるものなのでしょうか。","respondent":"冨田戸籍住民課長","answer":"都道府県の段階に対しての開示請求に応ずるような形で、ある程度の情報の開示がなされるものと考えています。細かい点はまだ詳細の通知が来ておりませんので不明です。","voiceIndex":183,"id":"exchange-081"},{"speaker":"北野委員","kind":"質問","question":"やはりこれは都道府県のところへと言いますけれども、区民に対して情報開示のところでどのような使われ方がされているかということを情報公開の部分で請求できるというような形になっていたと思うんですけれども、それについては、都道府県レベルということは、国の部分は個人情報としては公開がとれないんでしょうか。","respondent":"冨田戸籍住民課長","answer":"今、申し上げたのは……。","voiceIndex":185,"id":"exchange-082"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうから使用料の考え方について、ちょっとお伺いさせていただきたいんですが、その前に、７３ページ産業振興施設使用料ということで、西大井のベンチャー創業支援施設の今回、歳入という形で1,５３０万円予定をされているわけです。","respondent":"市川産業振興課長","answer":"ベンチャー創業支援施設の使用料の決定というか、今の段階で、まだ予定ということで説明をします。今回、平米単価3,３００円というものを算出基礎としています。","voiceIndex":188,"id":"exchange-083"},{"speaker":"原委員","kind":"質問・要望","question":"その支援サービスは本当のサービスとして支援をしていくのか、あるいはそこのところに何かの代価を求めるのかどうかということが一つ。それからもう一つは、新しくベンチャー支援という形で、施策としては８月にスタートするわけですね。企業導入に当たっては、果たしてそれが適当かどうかということについては、もう少し精査する必要があるのではないかと思うんですが、その辺のお考えはどうでしょうか。","respondent":"市川産業振興課長","answer":"ただし、このサービスは、利用者にとっては無料になる、いわゆる基礎的なサービスと、それから、一定程度高度な内容を求める場合には有料のサービスという振り分けを予定しています。","voiceIndex":190,"id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"安ければたくさん企業が入るものでもないかもしれないし、その事業によってもいろいろ考えが出てくると思うので、その辺のところの設定はもう少しいろいろな形を考慮して進めていっていただきたいと思うんです。それは要望です。そこの中には、今お話があったような減価償却という形の考え方がどのくらい反映されているのでございましょう。","respondent":"市岡企画財政課長","answer":"後者の行政財産使用料につきましては、いわば財産価格、建物の償却費用、こういった市場性を十分勘案して使用料を決定しています。公の施設についてはまたちょっと違う考え方をとってあります。","voiceIndex":192,"id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"そうすると、その中の話として、使用料を決めたときに、どういうような形をそこで妥当な使用料として認めるかということについては、委員会の中で話し合われてはいるんでしょうけれども、行政の中では、それは考え方としてどういうふうに持っていかなくちゃならないのかお伺いしたい。","respondent":"市岡企画財政課長","answer":"しかし、そういう単純な原則ではなかなか割り切れない社会情勢もありますので、例えば平成８年度に大きな使用料の改正をしましたが、このときには、例えば区民の方と区外の利用者でははっきり受益者負担の考え方を分けまして、区外の方には割り増しをお支払いいただくとか。","voiceIndex":194,"id":"exchange-086"},{"speaker":"原委員","kind":"質問・要望","question":"その割り増しの話もそうなんですが、では、区民が利用する場合と区外の方々が利用する場合の格差はどこで求めたらいいかという話になると思うんです。条例を見たって、そういうことについては書いていない。金額が設定されているだけの話ですから。区民サービスの限界と使用料の接点、そこのところをどう求めるのが一番妥当なのかというところが今後の中ではまた問題になってくると思うんです。","respondent":"市岡企画財政課長","answer":"これは実は使用料の改定をしようとしまいと、毎年、予算の時期には私どもはいろいろ検討しています。","voiceIndex":196,"id":"exchange-087"},{"speaker":"本間委員","kind":"提案","question":"持ち時間の中で数点にわたって質問します。それから、臨海部の広域斎場建設、１０７ページ、時間があれば１１４ページの緊急地域雇用特別交付金についてをお尋ねしたいと思います。その中で、平成１５年２月を目途としたものから、１５年度の早い時期に改めて提案するというような中身を知りました。この延期になった、先送りになったという経緯と理由について教えていただきたいと思います。","respondent":"西島経理課長","answer":"それ以後、司法書士会、宅建協会、土地家屋調査士会、東京商工会議所と、それぞれ法務局側が折衝というか、説明をしたわけですけれども、その中でも強い反対があったということで、当初、１５年２月に想定していたものが、どうもこれはそう簡単には行かないということの中で。","voiceIndex":199,"id":"exchange-088"},{"speaker":"本間委員","kind":"質問・要望","question":"このお話の意見書の中にもありましたように、地域の住民の皆さんとよく話をしてと、ご理解を得るようにというような部分がありますので、これまでの経過の中でもろもろの、利用者にとって使い勝手のよかった部分がいろいろあったかと思いますが、もう一度、その辺は十分把握されて、何かの機会にまた上のほうに話をする機会があったらよろしくお願いしたいと再度。","respondent":"宮地区民課長","answer":"臨海部広域斎場につきましては、大田区の東海一丁目３番というところにあります。","voiceIndex":201,"id":"exchange-089"},{"speaker":"本間委員","kind":"質問・要望","question":"来年の１月にオープンするという話で伺っておりますけれども、現在、急ピッチで工事が進んでいるようですが、現在どの程度の進捗状況なのか教えていただきたいというのと、もう１点、駐車場についてです。公共施設を利用する場合には、車の利用を前提としていないというような話も一度伺ったことがあるんですけれども、駐車場の件についてどの程度の規模になるのか、ひとつお知らせください。","respondent":"宮地区民課長","answer":"全体の敷地の３分の２程度は駐車場ですので、かなり広いスペースを確保しているです。それから、予定といたしまして、オープンが１６年の１月ということで順調に進捗しておりますので、予定どおりできるです。","voiceIndex":203,"id":"exchange-090"},{"speaker":"本間委員","kind":"質問・要望","question":"１１４ページの緊急地域雇用特別交付金のところに行きたいと思います。したがいまして、この件について具体的な内容と、もし人数換算のようなものができるようだったら教えていただきたいんですけれども、いかがでしょうか。できますでしょうか。","respondent":"小野政策担当課長","answer":"こういうふうな条件がついておりまして、今回の１５年度の中では人数といたしましては、６事業ですけれども、６事業の中で従事する労働者の数２８４名、その中で新規の雇用者の数が２２３名という計画で事業を実施するものです。","voiceIndex":205,"id":"exchange-091"},{"speaker":"本間委員","kind":"意見","question":"大変雇用環境が厳しい中で、私たちの周りでもかなり呻吟をしている方がいらっしゃいます現実に、それで昨年、重大な受けとめ方を労働界ではいたしまして、政労使で緊急雇用対策問題が協議されたと聞いておりますが、その経過を踏まえての今回の措置なのか、あるいはさらに新しいものが出てくるのか、ご意見で結構です。","respondent":"小野政策担当課長","answer":"つい最近来た情報によりますと、新たに１５年度に追加の交付、品川区に対しては8,７００万円の追加交付の予定だということがまいっておりまして、その中で、今までの従来の形での一般事業に対する委託、3,７３０万円、それから中小企業の特別枠がございまして。","voiceIndex":207,"id":"exchange-092"},{"speaker":"本間委員","kind":"質問","question":"実はそういう新しいお話を聞きまして、うれしく思っておりますけれども、例えばシルバー人材センターで駅付近等で、駐輪場等で働いている人の話をお伺いしますと、これから先、単価が切り下げられるようなことで、雇用問題も危ないんだと。私たちもこの仲間のうちから何人かやめなきゃいけないんだという話が出ておりますけれども、その真偽のいかんはどうでしょうか。","respondent":"小野政策担当課長","answer":"この事業の基本的な雇用の期間が６カ月と定められておりますので、そういう関係で、雇用満了で変わらなきゃいけないという状況も出てくるかと考えております。","voiceIndex":209,"id":"exchange-093"},{"speaker":"本間委員","kind":"質問","question":"６カ月という部分ではなくして、今までどおり仕事をしていた方が単価が切り下げられるようなこと、もしあれでしたら結構ですが、うわさの話かもしれませんので、もしあれでしたら、正しい情報を後ほどで結構ですから教えてください。次、１１７ページと９５ページにまたがっている都市計画交付金補助１６３号線整備事業費に関してです。","respondent":"中島街路事業担当課長","answer":"その後、住民説明会等を行ってまいりまして、私どもは地元の商店街の皆さんともいろいろなお話をさせていただいて、現在、商店街の再生に向けて勉強会を立ち上げているです。","voiceIndex":211,"id":"exchange-094"},{"speaker":"本間委員","kind":"質問・要望","question":"残留する者、転出していく者、さまざまのものがありますし、住宅のみ、あるいは店舗のみ、店舗と住宅、持ち家、借家人、さまざまな要素が絡み合う一本橋商店街の部分ですが、どうかまちづくりの再生の中で商店街の再生という部分にもう少し力を入れながらアドバイスをしていただくということを要望して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-095"},{"speaker":"藤田委員","kind":"質問・要望","question":"私から３点お伺いをいたします。７４ページの自転車駐車場使用料、同じく７４ページの区営住宅の使用料、７３ページの道路占用料の中の足場仮囲い、これについてお伺いをいたします。それとあわせまして、平成１５年度、この計画があれば教えていただきたいと思います。それから、足場仮囲いですが、これはどういう積算で決めていくのか、この辺をまずお伺いしたいと思います。","respondent":"奈良交通安全担当課長、田村住宅課長、岩田管理工事課長","answer":"今年度の計画ですけれども、１５年度は京急の新馬場駅、それから東京モノレールの大井競馬場駅の２カ所です。それと世帯構成にかわっての変化ですが、当初入居してから何年かたちまして、単身世帯になった、あるいは家族数が減ったということですと。足場等の道路占用料の件ですけれども、これは建築現場でやむを得ず道路に仮囲いを突出させる場合とか。","voiceIndex":215,"id":"exchange-096"},{"speaker":"藤田委員","kind":"質問","question":"有料にした後、知りませんよではなくて、やはり周辺の人とどういう話し合いで、置かれないようにするとか、フォローアップを何かしないと住民は納得しないと、こういうふうに私は思うんですが、お考えがあればお伺いしたいと思います。それから、区営住宅ですが、５階以上でエレベーターがない住宅は何カ所あるのかお聞きしたいと思います。それと、この工事現場、足場の仮囲いについてはわかりました。","respondent":"奈良交通安全担当課長、田村住宅課長、岩田管理工事課長","answer":"特にやっているのは旗の台の駅周辺で、４０～５０台とまっている。区営住宅におけるエレベーターの設置ですが、現在、１２団地のうちで３団地、ただし、そのうちの１団地、東大井三丁目の団地につきましては。今後とも所轄の警察署とこういったものについては見つけ次第指導するように区も努力してまいりたいと思います。","voiceIndex":219,"id":"exchange-097"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは定期利用と一時利用がありますけれども、定期利用につきましてはそうした方法もぜひとれないのかなということで皆さんの要望です。お考えをお伺いしたいと思います。これは非常に深刻なんです。ですから、エレベーターをつけられるだけの予算がないのか、建築基準法で、敷地内でそれだけのエレベーターをつけるのが難しいのか、この辺の判断はどうやっているのかお伺いしたいと思います。","respondent":"奈良交通安全担当課長、田村住宅課長","answer":"今、委員のご指摘の駐輪場に屋根をつけたらどうかというお話ですけれども、委員のご趣旨に沿って、つけられるところはこれから検討してまいりたい。荏原七丁目につきましては、建築基準法５６条の２で、高さ制限で違反するのでエレベーターの設置は不可能と。その他の住宅につきましては、それぞれ建築基準法の制限等があります。","voiceIndex":223,"id":"exchange-098"},{"speaker":"桜井委員","kind":"質問・要望","question":"最初に、文化センターの関係なんですけれども、昨年もちょっと質問させていただきまして、事務事業評価を見ますと、１３年度は、文化センター運営がＣになっていまして、その点について、優先利用使用料の減免、これを見直すというコメントもあったわけですけれども、それから１４年度の事業評価を見ますと今度はＢになっていまして、それから、反映状況というのがもう一つ出されていますけれども。","respondent":"上川内生涯学習課長","answer":"１４年度、再評価をいたしまして、区民の視点に立った使いやすい施設にしていくというところで、いろいろな文化センターの備品を整えたり、それから修繕をするところは修繕をしたりというところで、１４年度は継続してやっていくというところで、東品川。","voiceIndex":230,"id":"exchange-099"},{"speaker":"桜井委員","kind":"確認","question":"それは考え方ですから、もう一回、確認をしておきたいと思いますが、拡大をしているわけですね。今まで南大井文化センターと、あと、また新たに旗の台が加わったんでしょうか。私は基本的に、先ほどから話を聞いてみますと、業務委託、全面委託ですけれども、委託の内容が今、ご答弁いただかなかったので、もう一度お聞きしたいんですが、昭和建物というのはどういう会社なんでしょうか。","respondent":"榎本行財政改革担当課長、上川内生涯学習課長","answer":"最後の反映状況につきましては、１３年度と１４年度の評価を受けて、今現在、１４年度、１５年度についてどういう状況になったかということを説明しているのでございまして、その結果、文化センター維持分については。会社の概要ですが、本社は関西にありまして、施設設備の管理とか受付業務を担当している業者です。","voiceIndex":232,"id":"exchange-100"},{"speaker":"桜井委員","kind":"意見","question":"私も今の昭和建物の定款をとってみたんですけれども、最初にビル建物等建築物ならびにその附属設備の清掃および維持管理業務がトップに出ておりまして、ずっと見ますと、労働者派遣事業、ホテルの客室整備、洗浄、フロント業務というのが入っているんです。実績までちょっとわからないんですけれども、今、課長が言われましたのは、仕様書の説明ですね。どういう業務委託をしているかという話ですね。","respondent":"上川内生涯学習課長","answer":"区分のところだけを見ますと、かなり大業な項目がありますが、具体的には主な内容のところでございまして、委員がおっしゃったようなところにつきましては、職員が対応するなり、館長が対応するなり、また利用者の声をお伺いする場としては利用者協議会等で館長等も出席しまして。","voiceIndex":235,"id":"exchange-101"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう研修なり、その中身が、この要件にはそういうことは全く入っておりませんね。８００万円ですか。私は今回、ため込み基金の問題というのは、かなり論議がありますけれども、私どもの見解ですから、別に行政に見解を求めていません。その窓口にかかわる、また区民のサービスにかかわるこういう点に来るのではないかと私は指摘しておきたいと思いますし、見解を求めます。","respondent":"市岡企画財政課長、指田教育次長、松代道路公園課長","answer":"本会議でもしっかりお答えをしてきたところですが、これは、不断の行財政改革というのは。二つのご質問にお答えするようになるかと思うんですけれども、委員もご承知のとおり、文化センターは行財政改革を昭和５７～５８年から始めましたけれども。こちらは１３年の１０月６日から釣り堀としてオープンしているものでございまして。","voiceIndex":237,"id":"exchange-102"},{"speaker":"桜井委員","kind":"意見","question":"次長の答弁は社会教育法をご存じないんじゃないかと思うんです。場の提供は第一義的です。それから、時間がないので釣り堀のところだけ一言申し上げておきますと、やはり子どもたちが楽しみ、毎月2,０００人ぐらいの利用客があると聞いていますけれども、やはりそれぞれの子どもたちが本当に楽しんでやっているならば、積極的に区としてもきちんと設備・施設の改善を図るべきであると申し上げて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":241,"id":"exchange-103"},{"speaker":"築舘委員","kind":"質問・要望","question":"一つ目は、職員住宅ということで、職員の待機寮ならびに職員住宅ということですが、平成１４年度の事務事業評価では、評価がＣということで、福利厚生施設としての役割は縮小したものの、災害時の初動体制要員の確保策を含め、職員住宅のあり方の見直しを図ると、こういうふうになっているんですけれども。","respondent":"桑村人事課長","answer":"その意味で、まだ需要が残っている寮につきましては、そのままの形のものを持っていくわけですが、果たして今の時代にこういう形で寮自体を持っていくのが必要なのか、あるいは必要があれば普通の住宅の借り上げ等で対応するのがいいのか。","voiceIndex":243,"id":"exchange-104"},{"speaker":"築舘委員","kind":"質問","question":"そういう方向性はもちろん進めていると思うんですけれども、区内に住んでいる職員の方、それから区外に住んでいる方という分け方をしますと、お聞きしましたところ、品川区在住は３８％ぐらいだとお聞きしたんです。こういうときにこそ品川区内に住んで、そして、今までは５ＬＤＫだったのが３ＬＤＫになってもいいじゃないですか。お２人で仲よく住む場合は２Ｋでもいいですね。","respondent":"桑村人事課長","answer":"今おっしゃられたように、３８％、約1,０００人ちょっとの職員が区内に住んです。その意味で、どういう形で、そういったいざというときの対応ができるか、これから検討してまいりたいと思います。","voiceIndex":245,"id":"exchange-105"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと、車で通勤をしたりする人が例えばいたとしたら、通勤手当を出すのかどうかということです。それでもプラスして、自己負担をしている方もいらっしゃるというお話でしたけれども、その点に関して、それと住居手当の件ですが、この資料を見すると、国のほうは借家の限度額は２万7,０００円、持ち家だと1,０００円ですか、ただし、新築５年だと2,５００円の補助がある。","respondent":"桑村人事課長","answer":"その意味で、そういったものを借りるということについては、一定の手当を出すという考え方です。区においては、その意味では、地方公務員ですので、ある程度のところに住居を構えられるだろうという考え方でこういう程度になったものです。","voiceIndex":247,"id":"exchange-106"},{"speaker":"築舘委員","kind":"質問・要望","question":"自転車の場合は出るというんですけれども、車の場合、これはやはり排気ガスの問題とか、そういうことで、土・日の本当にどうしても来なきゃいけないとか、そういうときは別だとは思いますが、普通のときは認めないという確認をさせていただきたいということと、それから、住居のほうですが、やはり区内に住んでいらっしゃる方はそれなりに近いですし、通勤手当がかからない分。","respondent":"桑村人事課長","answer":"これはちょっと一つの今の手当の考え方よりも、むしろ政策的な考え方なんだろうと思います。先ほど申したとおり、区内にどのぐらいお住まいになることが今後の職員のあり方にとってどうなのかというものを検討させていただいて結論を出したいと思います。","voiceIndex":249,"id":"exchange-107"},{"speaker":"藤原委員","kind":"質問","question":"保育園の保育料の推移についてお伺いさせていただこうと思うんですけれども、たしか保育料は定額ではなく、区民税に応じた額だと思うんですけれども、今この不況の中で、保育料が増加しているのは区民税の増加している理由と同じなんでしょうか。この間の補正のときに少し、中間ファミリー層が増えているということを区民税のときにご答弁されていたんですけれども、保育料の増加についてはいかがでしょうか。","respondent":"金子保育課長","answer":"平成１５年度につきましては、７億8,７７３万円余ということで、１４年度に比べて４.９％の増加を見込んでおります。","voiceIndex":252,"id":"exchange-108"},{"speaker":"藤原委員","kind":"質問","question":"保育料の徴収率についてお伺いしたいんですけれども、区民税のほうは連続で２３区で第１位とかで、大変努力されているということがわかったんですけれども、先週の金曜日にも苛斂誅求の取り立てという話がありました。ただ、それでも一方では、保育園を利用されない方から見れば、きちんと払ってもらうものは払っていただくという考えがあると思うんですけれども、いかがでしょうか。","respondent":"金子保育課長","answer":"ただ、１３年度につきましては、残念ながら２位といった状況であります。納めていない方、滞納の方への対応ですけれども、まず納期限が過ぎますと、私どもでは翌月から督促状、催告状の交付、あるいは電話による催告をしております。","voiceIndex":254,"id":"exchange-109"},{"speaker":"藤原委員","kind":"質問","question":"今、課長のご答弁で負担の公平の観点でしているということと、過酷な取り立てはないということが二つわかりました。次に、支弁費といいますか、保育の費用にかかる国、都の支出金の昨年度対比についてお伺いしますが、いかがでしょうか。","respondent":"金子保育課長","answer":"保育の実施に関する国、都の費用に関してはさまざまな種類のものがあります。基本保育に限ってみますと、平成１４年には１２億9,５２９万円、これは予算ベースですけれども、それを平成１５年には１３億2,３１１万円余ということで、２.４％の増加を見込んでおります。","voiceIndex":256,"id":"exchange-110"},{"speaker":"藤原委員","kind":"質問","question":"保育料が４.９％増加している。そして、国、都の支出金も２.４％増加しているということはわかったんですけれども、全体の保育の費用についてはどうでしょうか。ここ２～３年の傾向についてお伺いします。","respondent":"金子保育課長","answer":"全体の保育の費用というお尋ねですけれども、まず予算ベースで事業費で見ますと平成１４年度には２８億7,４８２万円余、平成１５年度は３０億9,８３１万円余ということで、２億2,４００万円、率にしまして７.８％の上昇を見込んでおります。","voiceIndex":258,"id":"exchange-111"},{"speaker":"藤原委員","kind":"質問・要望","question":"今後ともぜひ調理代行などコストの削減に努めながら、このような多様なニーズに応えるように努力していただきたいと思います。これは要望です。それともう一点、最近、保育園に入園された方から、納付書か口座振替の依頼書が送られてきたというお話を伺って、たしか夜間保育はプリペイドカード方式だったと思うんですけれども、保育料はこの方式にできないんでしょうか。","respondent":"金子保育課長","answer":"私どもは延長夜間保育をかなり広範に導入したときに、このプリペイドカード方式を実施したわけなんですけれども、そもそもこのプリペイドカード方式のメリットは、いつ何時の時点で迎えに来たか、それによって料金は幾らになるのか。","voiceIndex":260,"id":"exchange-112"},{"speaker":"藤原委員","kind":"質問・要望","question":"さまざまな観点で利用者にとって便利な方法をこれからも検討していただきたいと思います。よく聞くんですけれども、例えばきょうのお迎えは、両親のどちらかが早く仕事が終わるとした場合に、今、１世帯当たり１枚しか配布していないと思うんですけれども、これを２枚配布していただくことはできないんでしょうか。","respondent":"金子保育課長","answer":"ですので、先ほど申し上げたとおり、システム的には可能ではありますので、これについては少しお時間をいただいて検討をさせていただければと思っています。","voiceIndex":262,"id":"exchange-113"},{"speaker":"藤原委員","kind":"質問","question":"最後にもう１点お伺いしたいんですけれども、一番最初の質問で、保育料が増加しているということで伺ったんですけれども、多くではないんですけれども、地域、町に出たときに、高額所得者が保育園に入りやすいと聞いたことがあるんですけれども、それに対して明確なお答えをいただけますか。","respondent":"金子保育課長","answer":"保育園の入園の選考についてのお尋ねだと思いますけれども、私どもは保育にかける度合いの高い方というのを一番ベースの選考の基準にしておりますので、高額所得者の方が有利であると、こういうことは一切ございません。","voiceIndex":264,"id":"exchange-114"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと施設の問題、形状的な部分でちょっとお伺いしたいと思います。それから、７４ページの区民住宅の使用料についてお伺いしたいと思います。要するに施設、シルバーセンターです。狭くなってきて、上がっていく狭くなりかけたところがちょうど右側にはりがあるんでしょうか。ですから、そういったことについての、せっかく貸し出しをする施設であれば、改善方をちょっとお願いしたいと思うんです。","respondent":"蓼沼高齢事業課長、田村住宅課長","answer":"ということで、なるべくそういったところがわかりやすいようにということで、いろいろ工夫をしていますけれども、今後、さらにもう少し安全性がわかるような工夫、ＰＲ、利用者の方全般につきましても、そういったようなＰＲについて。フラット家賃と傾斜家賃の関係ですが、今、ご指摘のように、ファミーユ下神明、また、来年度実施します西五反田三丁目の区民住宅は、全体がフラット家賃ということと、住み替え可能ということです。","voiceIndex":267,"id":"exchange-115"},{"speaker":"三上委員","kind":"質問","question":"だから、こういうことが、同じ区の施設でありながら家賃の設定の仕方が極端に違ってくるといった場合の割安感という部分についても、こういった考え方が、やっぱりちょっと高いんじゃないかということでの意識がどうも払拭できないということになりかねないんじゃないかと思うんですけれども、どうなんでしょうか。","respondent":"蓼沼高齢事業課長、田村住宅課長","answer":"シルバーセンターの件ですけれども、構造上の問題、施設担当のほうとも十分相談をいたしまして、ハード面、そして、ソフト面を含めて安全性が改善できるかどうか、十分検討してまいりたいと思います。ただし、委員のご指摘のように、実際、傾斜が物価の状況を踏まえても、上がりぐあいがかなり高いんじゃないかという問題は確かにあるかなということで、やはり当初の契約は２０年間の借り上げ等の契約になっていますが。","voiceIndex":270,"id":"exchange-116"},{"speaker":"三上委員","kind":"質問","question":"ですから、これについては、国の制度そのものを変えなきゃならないということであれば、これは２３区の中でもどんどん声を上げていって、やってもらわなきゃならない部分がありますし、それと同時に、品川区としても、じゃあ、どこのところに家賃設定というのをするのかという意味である程度の見直しということもやってもいいんじゃないか、そういうふうに思うんですけれども、いかがでしょうか。","respondent":"田村住宅課長","answer":"委員のご指摘のとおり、やはり地価が横ばい、あるいは右肩下がりという状況にありますので、やはり既存の区民住宅につきましては、賃貸者契約の中にもやはり家賃の変更等の項目がありますので、オーナーと時世に合わせて協議をすることが必要ではないかと考えております。","voiceIndex":273,"id":"exchange-117"},{"speaker":"三上委員","kind":"質問・要望","question":"オーナーと話し合うことも大事ですけれども、品川区の基本的な考え方をどうするべきか。区長がどういう住宅政策をとるのか、こういうことも関係してくるわけですから、それについて、きちんとそういう部分についての対応を不公平感がないように考えていっていただきたいと思うんです。国のほうについて、制度としてもどういうふうに取り組むかちょっとお願いしたいんです。","respondent":"山室住宅指導担当部長","answer":"したがって、先ほど住宅課長が申し上げましたとおり、現在、フラット家賃で下神明は出てきておりますので、今後、この傾斜型家賃も全体的に見直しをして、フラット家賃との整合性を区としても考えていきたいと考えています。","voiceIndex":275,"id":"exchange-118"},{"speaker":"三上委員","kind":"質問・要望","question":"どちらにしても、時間をかければいいという問題でもないと思いますので、ぜひとも早急にそういった問題についての取り組みを善処していっていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":277,"id":"exchange-119"},{"speaker":"金高委員","kind":"質問","question":"私は、４９ページの特別区税ならびに５６ページ、地方消費税交付金、それから１２８ページの繰越金と、時間がとれれば１４４ページの特別区債につきまして質問をします。お聞きしたいのは、納税義務者、特別徴収の件でありますけれども、１００％ないという、ここの部分についてまずお聞きしたいと思います。","respondent":"松崎税務課長","answer":"年度内に幾ら完全に納付されるかどうか、一つのポイントとして見て、基本的には１００％に今までもなっていません。そういうような状況があるであろうという想定のもとに、９９.４６％というのを見込んでいるものです。","voiceIndex":279,"id":"exchange-120"},{"speaker":"金高委員","kind":"質問","question":"それともう一つ、従業員はお金を払った。それから、そういう場合には、それらの方々に対して、現実は払っているわけですから、その処置としては、完全に１００％払ったということでの証明といいますか、なるんでしょうか。その辺のところをちょっとお聞かせ願いたいんですが。","respondent":"松崎税務課長","answer":"２点目ですが、特別徴収義務者が各社員から住民税分を納めていただいた部分で、納期の到来していないものと到来しているもの両方に分けて考える必要があると思います。","voiceIndex":281,"id":"exchange-121"},{"speaker":"金高委員","kind":"質問","question":"その中で１点、繰越滞納の件でありますけれども、累積されてくるということでありますが、帳簿上でもって実際に累積された部分がどこかの時点でもって切っていかなきゃいけないという部分があるんですか。それは何年くらい積み立てたといいますか、経過したときに、それを欠損とするのか、その辺をちょっとお聞かせ願いたいんですが。","respondent":"松崎税務課長","answer":"例えば外国人の方で就労されて、住民税を払わないまま帰国されたような場合は取る手段がなかなかございませんので、落とすという場合もありますので、何年ということでは考えてございません。","voiceIndex":283,"id":"exchange-122"},{"speaker":"金高委員","kind":"確認","question":"ということは、確認いたしますけれども、時効はないと解釈させていただいてよろしいんでしょうか。","respondent":"松崎税務課長","answer":"一応、税の時効は５年というのがあります。ただ、時効を延ばすかどうかというのが私どもの判断です。","voiceIndex":285,"id":"exchange-123"},{"speaker":"金高委員","kind":"質問・要望","question":"次に移らします。地方消費税についてでありますけれども、地方消費税、今年度につきましては、４６億円の計上になっております。5,６００万円が減額になっているわけですけれども、5,６００万円減額になったという考え方がありましたらば、予算の組み立ての状況においてどのようにして、これが減額として出てきたか、その辺をちょっと示していただきたいと思います。","respondent":"市岡企画財政課長","answer":"これは事業所統計に基づく算定です。それから、5,６００万円減と見込んでいる根拠といいますか、考え方ですが、これは全国的に個人消費の落ち込みということが現在の不況の一番深刻な事態のあらわれであります。","voiceIndex":287,"id":"exchange-124"},{"speaker":"金高委員","kind":"質問","question":"続きまして、その次の繰入金につきましてお伺いします。１、２、３、４につきましては、それぞれ取り崩しながら、それぞれの科目、目的に沿って使われているわけでありますけれども、５目と６目、中小企業融資基金繰越金、高額医療と二つあるわけでありますけれども、このうちの中小企業融資基金の繰越金、約１３億3,８４６万5,０００円余りですか、これが実際に基金がなくなるわけであります。","respondent":"市岡企画財政課長","answer":"これは条例議案のほうでご説明があったかと思うんですが、制度融資自体はもう預託をしなくても十分行えるということで廃止をいたしました。","voiceIndex":289,"id":"exchange-125"},{"speaker":"金高委員","kind":"質問・要望","question":"ベンチャー支援については、先ほど原委員もそれぞれ質問しておりました。やはり今まで培った中小企業の融資の基金でありますので、十二分に活用していただきたいと思いますし、ベンチャー支援のほうは先ほども若干質問もありましたけれども、この中でお聞きしておきたいところが一つあります。８月にオープンとなっておりますけれども、実質的にこの予算が成立するのは今月です。","respondent":"市川産業振興課長","answer":"その工事期間を見込んだ上で、現在のところ、８月からの利用開始ということで計画を立ててあります。その間に募集、応募、入居者の決定と、こういうことをその限られた期間の中ですけれども、処理していこうということで事業計画を立ててあります。","voiceIndex":291,"id":"exchange-126"},{"speaker":"金高委員","kind":"質問・要望","question":"この毎日変動しているということでありますけれども、これは、例えばもし３００万円投資して、この債券を買って、５年間持っていればそこそこの０.３４％でもって利率がついて戻ってくるということでありますけれども、途中換金できますということですから、当然、償還期間前に換金ができるわけでありますけれども、毎日変動しているという変動の内容等について。","respondent":"市岡企画財政課長","answer":"最初のほうに書いてある起債の利息の限度との関係ですが、これは実は借り替えるときに、もう１回、許可をとり直さなくもいいように、少し高めに設定しておりますが、５年物の０.３４というのは、今の中では非常にバランスのいい金利だと思いますし。","voiceIndex":293,"id":"exchange-127"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、今、お話が出ました１４４ページ、教育債ならびに９８ページ、学校施設整備費に関連して、ちょっとお伺いしたいと思います。教育債でありますが、考え方を教えていただきたいと思います。７月から工事を開始するんだ。そこら辺の点で、もう一度、どうしてこういう工期の予定表をつくったのかというところを改めてお聞きしたいと思います。","respondent":"市岡企画財政課長、鷹倉庶務課長","answer":"なおかつ、償還経費については、建物については全額がそのときに措置されるのではなくて、言ってみれば償却の割合に応じて標準算定をされますので、こちらのほうはそこそこに活用するという程度で考えていったほうがいいのではないかと。具体的な数字でお話し申し上げますと、現在、１５年度に実施設計を済ませて、１６年度の６月に本体工事の契約をしていくと、こういうお話です。そうしますと、今、石田委員のご指摘のとおり、当該年度の子どもが新しい学校に入れない。","voiceIndex":296,"id":"exchange-128"},{"speaker":"石田委員","kind":"提案","question":"たまたまそういう制度があって、ゼロ債を組めば、この子どもたちは１カ月でも２カ月でも学校を使って、最後、卒業していけるという制度があるのであれば、私はそのためにゼロ債制度があると思いますし、時間もないので、もう１点だけ言わせていただくと、基本的に、文部科学省がそういう制度で原則論を言うのであれば。","respondent":"鷹倉庶務課長、市岡企画財政課長","answer":"したがいまして、都を通じていろいろ話をするわけですけれども、いろいろな働きかけをやっていきたいと考えています。学校の主人公はあくまでも子どもですので、子どものことを中心にお話をしていきたいと思ってあります。私どもは、その動向も必ずや充実すると考えていますので、今回、中長期をにらんだ学校改築計画を出しているというのが１点です。","voiceIndex":299,"id":"exchange-129"},{"speaker":"石田委員","kind":"質問・要望","question":"最後にもう１点だけ確認をさせていただきたいと思います。基本的に、区があって、国の補助制度が今ある。国の原則論がある。じゃあ、東京都が本当にそういうふうに言ってくれるのかどうか、そこら辺の兼ね合いをどう考えていらっしゃるのかというのがちょっと最後だけ確認をしていただいて、必ず通るような形で、今の教育債を含めて通していく方法はどこにあるのかというお考えをもう一度。","respondent":"市岡企画財政課長","answer":"都区協議とか、２３区間とか、あらゆる場で働きかけをしていく必要がある、こういうふうに考えています。","voiceIndex":302,"id":"exchange-130"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと私はまずお伺いしたいのは、今回、都の財調交付金が１０億円のマイナスということなんですけれども、これについての区の見解といいますか、これをまず聞いておきたいと思います。この原因が、なぜ東京都、県ですけれども、区としてどう見ているかということ、あと区の施策への影響がどういうふうになってくるのかというところをまず聞いておきたいと思います。","respondent":"市岡企画財政課長","answer":"基金を持ち出して恐縮ですけれども、品川区はこういうときにこそ区民の期待にこたえるために、投資的事業をやらなければいけませんから、これはやらなくてよければ、それはそれなりの対応の仕方もありますが、こういう時期だからこそ区民の期待にこたえて。","voiceIndex":305,"id":"exchange-131"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、課長からは、不景気で税収が増えない。その次に伺いたいのは、特別区民税のところなんですけれども、今回、５.３％の増ということであります。前年から比べて１.５％減っている。国民の所得が減っているというところで、私は特別区民税がどういうふうな仕組みで上がってくるのか、増えるのかというところを改めて聞きたいと思うんですけれども、そこの見解です。","respondent":"市岡企画財政課長、松崎税務課長","answer":"先ほどの財調で１点だけご説明をさせていただきたいのは、都がいろいろ福祉的な給付の見直しをしていることとこの財調は一切関係はございません。人数でいって約３人。対前年度で３人しか変化がないということは、ここがしっかりと支えているです。１０％の部分が増えている。したがいまして、品川区の税収構造は上向きと見ていいということで、１５年度見込んでいるところです。","voiceIndex":307,"id":"exchange-132"},{"speaker":"宮崎委員","kind":"意見","question":"この中堅所得層が、今、国全体ではというお話でしたけれども、他区、２３区なんかでの比較はどういうふうにされていたのか、見ているのかというのと、いわゆる中堅所得層が増えてきた、そこでの区の取り組みはどういうものがあったのか。戦略的に、あるいは戦術的にどういう取り組みがあったのかというところをどなたに聞いたらいいのかよくわかりませんけれども、そこのところはどういうものがありましたか。","respondent":"松崎税務課長、小野政策担当課長","answer":"前半の他区の状況ですが、やはり住宅施策に力を入れた区、例えば具体的な名前を挙げるのは何ですが、渋谷区等は大きく税収が延びております。城南ブロックで見ましても、城南５区ありますが、税収は比較的堅調と考えています。特に第三次長期基本計画の中では中堅ファミリー層の区内での確保ということで、住宅政策であるとか、あるいは子育てであるとか、さまざまな部分で進めていた。その成果が上がってきたものと考えております。","voiceIndex":310,"id":"exchange-133"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、例えば今、住宅政策のところでも、ここにいわゆる中堅所得層が多く入ってきたということだと思うんですけれども、一方では、例えば私もきのう、知り合いのところを訪ねたらもぬけの空だったんです。そういう中で公共料金が上がっていく。こういう中で、区も公共料金の考え方をどういうふうにしていったらいいのかと思うんですけれども、そこのところをお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"このように考えてあります。","voiceIndex":313,"id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"収入のそこそこある人はやっぱりそれなりに負担できる。先ほどどなたかの質問のところで、使用料、手数料のところだったかと思うんですけれども、市場原理を考えて料金を設定するんだというお話でしたけれども、そういう角度でいくと、収入が少なくなってきた人が負担がどんどん増えていくということになるだろうと思います。","respondent":"中尾根企画部長","answer":"このように考えてありますので、その点についてご理解のほどよろしくお願いしたいと思います。","voiceIndex":315,"id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、住宅のほうへずっと話が来ていますので、住宅のところでいけばもっと前回の都営住宅でも、わずか６戸で８５倍ぐらいの倍率でした。だから、ここのところに気持ちを配慮した中身にして、これは住宅政策だけではなくて、していただきたいということをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-136"},{"speaker":"鶴委員","kind":"質問","question":"私は７２ページの土木使用料および３３０ページの職員費に関連して数点お伺いします。道路につきまして、道路を占用する場合、あるいは使用する場合の手続というのは、どういう手だてをとるのかということです。それから、職員費に関連しまして、今、朝８時半ごろ、どういう注意を促す放送を庁内でやっているか。これにつきまして、まだ給与から天引きになっているか。数年前と比較して報告してください。","respondent":"岩田管理工事課長、山田広報広聴課長、桑村人事課長","answer":"ただ、一部限定的な解除として占用という考え方がございまして、電柱とか。朝の注意ですけれども、現在、８時半に庁内放送を使いまして、職員全員による朝のあいさつ運動、それから。数年前から比べますと、毎年大体１００件ちょっとぐらいずつ落ちておりまして、５年間で７５４件減少になっているものです。","voiceIndex":319,"id":"exchange-137"},{"speaker":"鶴委員","kind":"質問","question":"道路でどういう道路なのか聞きたいんですが、今の説明はわかりました。確かにそうでしょう。道路は、街頭で募金活動をやるときだって所管の警察に一応提示しなきゃいけません。出さなきゃいけない。街頭宣伝を車でやる場合でも警察に届け出を出さなきゃいけない。昔は、かつては碑文谷街道といったんでしょうか。目黒の碑文谷に通ずるあの道路はどういう道路ですか。それから、貯蓄金のことは後で触れます。","respondent":"岩田管理工事課長、山田広報広聴課長","answer":"品川区道です。昨年の６月から各事業部の皆さんによる朝のあいさつ運動ということで展開をさせていただいて、それぞれの事業部のＰＲを含めて朝の中に組み込んでおります。","voiceIndex":323,"id":"exchange-138"},{"speaker":"鶴委員","kind":"質問","question":"道路交通法第２条第１項第３号の４に規定する。路側帯は何のために設けられているのでしょうか。それから、第１４号議案品川区歩行禁煙および吸い殻・空き缶等の投げ捨ての防止に関する条例、この第９条にうたわれている、「何人も公共の場所において歩行中に喫煙をしないように努めなければならない」とありますね。この「何人」と「公共の場所」ということはどういうことでしょうか。","respondent":"岩田管理工事課長、長田地域活動課長","answer":"路側帯につきましては、道路交通法で定められているものでございまして、車と人を分離させる目的で設置するものでありまして、歩道のない歩車道分離されていない道路に歩行者の安全を確保するために引いている線でございまして。今回、提案させていただいている１４号議案の中の「何人も」ですけれども、この「何人も」という意味は、品川区民に限らず、品川区の地域を利用する方はすべて含みます。","voiceIndex":326,"id":"exchange-139"},{"speaker":"鶴委員","kind":"意見","question":"そうしますと、運転免許を持っている人はわかると思いますが、路側帯に車なんかを駐停車する場合、０.７５ｍ以下の路側帯の中に入って車をとめてはなりませんね。その左側にとめなければならない。この路側帯でバザーができますか。それから、このスーパーの前の自転車が例えば平塚橋交差点のところからカーブしていく、あのカーブのＳ字型のところは夕方どういう状況かわかりますか。","respondent":"岩田管理工事課長","answer":"先ほど答弁が漏れましたけれども、道路の占用と道路の使用というのはちょっと考え方が違っておりまして、占用というのは繰り返し継続してそこに物を置く場合に占用という形になりますけれども、一時的に臨時的に道路を使う場合は道路使用と申しまして、公安委員会所管ですので。","voiceIndex":329,"id":"exchange-140"},{"speaker":"鶴委員","kind":"質問・要望","question":"２００２年１１月１７日、「飯沼雅子ニュース」、「お待たせしました。お電話をいただければ伺います。」そして、１２月８日付、同じ「飯沼雅子ニュース」、「バザーの御礼。１１月１７日のバザーはおかげさまで大盛況でした。大混雑。だから、スーパーマーケットの経営者にしっかり、歩道の路側帯には自転車を置かないように協力を求めるなり、あるいは行政指導すべきだと思うんですが、いかがでしょうか。","respondent":"岩田管理工事課長","answer":"平塚橋の駐輪の問題ですけれども、この問題につきましては、私どもも前々から苦情をいただいているところでございまして、お店等につきましては、善処をしていただくように繰り返し注意を申し上げているわけですけれども、残念ながら、なかなか改善が見られないですが。","voiceIndex":331,"id":"exchange-141"},{"speaker":"鶴委員","kind":"質問","question":"それで、粘り強くあそこに、別なところに駐車場を設けるなりしないと、スーパーの前では今に事故が起こります。とてもじゃないが、はらはらどきどきです。車の列も長蛇の列ができてしまう。どう対処していくか聞いておきたいと思います。だれが整理するのでしょうか。本来は持ってきた人がきれいに並べるべきではありますけれども、この点は承知されていますね。どういうふうに指導されていますか。","respondent":"岩田管理工事課長","answer":"これは基本的には商行為を行う上において、近隣のそういった交通ももちろんですけれども、きちんとしたルールに基づいて営業されるというのが前提です。したがって、区としてはそういうお店をつくられる場合にはきちんとした駐輪場を確保して……。","voiceIndex":333,"id":"exchange-142"},{"speaker":"松澤委員","kind":"質問・要望","question":"最後ですので短く３点ばかり。１２６ページ、１点目は歳入の１３款財産収入、２項財産売払収入６３万1,０００円の内容についてお聞かせいただきたい。１回にどのくらい経費がかかっているかというのをお聞きしたいと思います。３点目は、議会費に関連して、議会控室の使用についてをお聞きしたいと思います。","respondent":"小野副収入役、福田区議会事務局長","answer":"不用品売払代金についてですけれども、これにつきましては、物品で使用に耐えなくなったもの等について、売れるものについては売却をして収益を上げているというものです。こういう立場でやり方をとっておりまして、必ずしも１回分の経費、そういうことでの算定が今のところ、まだしていない、できていない、こういう状況ですので、ご了解いただきたいと思います。","voiceIndex":336,"id":"exchange-143"},{"speaker":"松澤委員","kind":"質問","question":"予算の中に６３万1,０００円収入というふうになっているものですから、何か決まっている物品を売り払う予定があるのかなということでお聞きしたんですけれども、お願いいたします。","respondent":"小野副収入役","answer":"不用品売払代金の内容の主なものにつきましては、清掃車、小型プレス車両、それから、それに伴う古タイヤ、あと、軽自動車のナンバープレート等です。","voiceIndex":339,"id":"exchange-144"},{"speaker":"松澤委員","kind":"質問","question":"そこから各議員のところまで追跡でリンクできるということで、大変にすばらしいと思うんですけれども、２３区の中で先駆的に始めているということなんですけれども、当然、始めのほうですから、他の区から注目されたり、あるいは自負心、私たち品川区が２３区の中では一番すごいんだという思いがあると思いますけれども、一つ、トップページのアクセス数というんですか、きょう、見ましたら3,３４６件。","respondent":"小野副収入役、福田区議会事務局長","answer":"不用品とする基準ですけれども、特に基準というものが定めてあるわけではございませんけれども、まず第一義的には各課で不用になったものをまず不用品交換会ということで、できるだけ他課で使用できるように。こう言っては何ですけれども、議会というのはどこでも、そう派手な存在ではない場合が多い。そう考えますと、１日５０件の方がアクセスをしていただけるというのは大変ありがたいことだと考えています。","voiceIndex":341,"id":"exchange-145"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと、ホームページのほうはわかりました。１日の件数としてはというようなお話を伺いましたけれども、やはり私たちもいろいろ質問していく中で、ホームページを立ち上げたり、議会のホームページのアクセス数が多くなると大変にうれしく思うものですから、これのＰＲのほうもよろしくお願いしたいと思います。売り払いのほうの話を伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"先ほど副収入役がご答弁申し上げたように、この売り上げのうち主なものは品川清掃事務所の清掃車両ですが、これは６台分を入札で売却する予定のものがほとんどです。６０万円を占めるということです。","voiceIndex":344,"id":"exchange-146"},{"speaker":"松澤委員","kind":"質問・要望","question":"売払収入、私たちにとってはスクラップ・アンド・ビルドというんでしょうか。いいえ。それぞれ各会派が勉強しているんではないですか。そうしたら１１時半に消えました。これは当然、議会事務局も閉まっているものですから、その後のことはわからないでしょうけれども、風聞的に、これだけ遅くまで使っているということを事務局では理解しているんでしょうか、その辺をお聞きしたいと思います。","respondent":"福田区議会事務局長","answer":"私どもは、職員が夜分、帰宅をするということもあります。ですが、委員がおっしゃいました１１時３０分ということは、私ども事務局は滅多にございませんで、この時間まで控室が使用されているという実例を把握しておりません。","voiceIndex":346,"id":"exchange-147"},{"speaker":"松澤委員","kind":"質問・要望","question":"その時間まで、議員が帰るまでいるわけにいかないですから。庁舎管理という点からすると、これからだんだん警備が機械化されてくる状態になるとおそらく一般の職員の方でも警備の時間が切れるころには、常識的には９時でしょうか。それより過ぎるときには、ある意味何か特別な許可を求めるとか、届けを出すとかするんでしょうけれども、それが議会の控室の場合はどうなるんだろうか。","respondent":"福田区議会事務局長","answer":"したがいまして、そこに何らかの問題があるんだと、こういうことでありますれば、しかるべき議会運営委員会等を中心としたご議論が改めて必要かというふうに考えます。","voiceIndex":348,"id":"exchange-148"},{"speaker":"松澤委員","kind":"質問・要望","question":"私はやはり１１時半まで残っているのは異常ですから、そういうときには事務局のほうで、こういう話を聞いたんですけれども、どういう理由があったんでしょうかと、それぐらい聞くのは議会事務局としての一つの当然のことだと思います。終わります。","respondent":"堺委員長","answer":"以上をもちまして、本日予定の審査はすべて終了いたしました。次の会議は、あす、３月１１日、火曜日、午前１０時から開きます。本日はこれをもって閉会といたします。","voiceIndex":350,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":114991,"voices":351}},{"id":"h15-20030311-3","meetingId":"h15-c-budget","date":"2003年3月11日","dateIso":"2003-03-11","committee":"予算特別委員会","time":"午前１０時０７分～午後５時３４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を127件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"私からは、１点、１５１ページの私立幼稚園関係費に関する品川型就学前施設のプリスクール西五反田に関連して。品川区の先駆する幼保の形ということで、やり方については、ＮＰＯ法人に委託ということなんですが、まず、なぜＮＰＯ法人に委託という形をとられるのか教えていただきたいと思います。","respondent":"古川総務課長","answer":"こういう中で、新しいその施設については、優れて幼児教育に対するノウハウをお持ちの方々が設立予定されているＮＰＯに委託をと、こういう方向を出したわけです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"本多委員","kind":"意見","question":"ＮＰＯということで、どうとらえていくのか。一般論になるかもしれませんが、契約について、随意契約、入札、プロポーザルいろいろな方法があると思うんですが、契約について、ちょっとご説明をお願いしたいと思います。","respondent":"古川総務課長","answer":"平成１５年度にお願いしていますのは、あくまでも建物の建設費でございまして、実際には平成１６年６月の開設をめどにしていますので、具体的な契約等については、平成１６年度に向けての中で、その方法論を含めてということになろうかと思います。","voiceIndex":6,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"ノウハウというものが、今までの３歳児から５歳児についての就学前幼児教育のエキスパートという、非常にいい部分も出して、公私ということでやられると思うんですが、例えば、今まで３歳児から５歳児までの児童を一緒にして縦割りにした教育をしていた幼稚園もあると思うんです。その点について、ちょっと教えていただきたいと思います。","respondent":"古川総務課長","answer":"つまり、私立幼稚園、そして公立の保育園。私ども、今、さまざまな形で協議といいますか、事前の検討の場に臨んでおりますけれども、そういう視点からとらえますと、双方にとっても新しい、大きな取り組みなのかなと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"それとあわせて、例えば、そういった工夫をしていくには、ルームのあり方ですとか、ハード面の考え方、ソフト面の考え方、その辺の区の考え方と運営していく側との考えの一致というんでしょうか、その辺はどういうふうに考えているのか、教えていただきたいと思います。","respondent":"古川総務課長","answer":"それぞれＮＰＯを設立しようという私立幼稚園の園長の方々、そして私ども、区の関係者がこの部分については十分に協議を重ねていきたいと考えています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"来る側と運営を委託していく側と十分な協議をされて、うまい方向でいくことを、ほんとうにお願いしたいと思います。保育と就学前教育という部分と、今度は、子育て支援センターという部分も、また幅広く入ってくるという点ですが、その点についても、区側としての委託側に対する申し入れというんでしょうか、その辺についてはどうでしょうか、ちょっと教えていただきたいと思います。","respondent":"古川総務課長","answer":"先ほどの答弁にもかかわってまいりますけれども、ハードの部分も含めて、ソフトもそうですけれども、保育課、そして児童課、総務課、そしてＮＰＯ法人を設立をしようとしている方々で会合を持ちながら、先ほどもちょっと触れましたが、子育て支援センターの関係で申し上げますと。","voiceIndex":12,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"これからいろいろと初めての試みですので、いろいろなハードルもあるかと思いますが、区側と委託を受ける側との協議というんでしょうか、コミュニケーションをしっかりと図っていただきたいと思います。改めて、その点だけ確認をさせていただきたいと思いますので、よろしくお願いします。","respondent":"古川総務課長","answer":"そういう中でとらえますと、この間、同じ思いと申しましょうか、新しい運営というところにお互いの気持ちが一緒になっておりますので、さまざまな課題、難しい問題も多分出てこようかと思いますけれども、そういったものを一つずつクリアしていきながら、ここに掲げてあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"嶋委員","kind":"質問・要望","question":"私は、１５１ページの公共施設整備基金積立金、本来ならば教育費に入っていくかと思いますが、ここでは義務教育施設整備基金というのがあると思いますので、そのことに関連して、お話をさせていただきたいと思います。もう一つは、１７５ページの東大井区民集会所運営委託に関連してお尋ねをいたしますので、よろしくお願いいたします。","respondent":"市岡企画財政課長","answer":"いわゆる積み立てをし、取り崩す基金というのは、条例でその目的が定められておりまして、公共施設整備基金というのは、道路、あるいは一般的な箱もの、その他の公共施設、性質は似ているんですが、義務教育施設整備基金というのは。","voiceIndex":17,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"フットサルというのは５人制です。混合もできるということで、大分、地域で幅広く子どもたち、また青年たちがやっておりますが、品川区においてフットサルができる施設は、今幾つあるでしょうか、ちょっとお聞きをしたいと思います。公共施設の中で、フットサルができるようにお願いをしたいと思いますが、ちょっとお考えをお聞かせいただきたいと思います。","respondent":"指田教育次長","answer":"そういう中において、最近特にフットサルというものが非常に人気が高まっているということは、私どもも承知していますので、どの辺のところでどうやってできるか、場所的な問題も含めまして、今後、検討させていただきたいと考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"やっぱりこれは混合チームができる、年齢も関係なくできるという意味では、幅広いスポーツになっていくと思いますので、ぜひまた、今後お考えをいただきたいと思っていますので、よろしくお願いいたします。二つ目に、１７５ページの東大井区民集会所の運営費について、お伺いいたします。この内容をちょっとお聞かせいただきたいと思いますので、よろしくお願いいたします。","respondent":"長田地域活動課長","answer":"こちらの委託につきましては、住民で組織する団体ですけれども、大井第一コミュニティ運営委員会のほうに管理運営委託をしています。それの必要経費として2,０００万円ちょっとを組まさせていただいたものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"東大井集会所は１階、２階ということで、２階のほうにテレビとかビデオとかが設置をされております。ぜひ、１階にテレビデオを設置していただくか、またはスロープなどを設置をしていただきたいと考えていますが、いかがでしょうか。","respondent":"長田地域活動課長","answer":"１階の和室へ入る部分には、階段１段分ぐらいの段差があります。ですから、そういった意味で、テレビデオがキャスターの上に乗っていますけれども、確かに一体型になりますと、相当重うあります。そういったこともあろうかと思います。","voiceIndex":23,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"１階の和室は、高齢者の方たちが踊りとかで使っていますので、ここでビデオを使ってもっと幅広く、健康のために踊りもやっていただきたいと思いますので、ぜひ検討をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"二つあるんですが、最初に１５９ページの美化対策費、歩きたばこ防止キャンペーンの関係で、ちょっとお伺いしたいと思います。歩きたばこの問題では、いろいろなことがテレビやマスコミでも報道されておりまして、品川区も大分有名になっております。ちょっと質問なんですが、新年度に区が予算で予定している今度の歩きたばこ防止キャンペーン事業の概要について、少し説明をいただけませんでしょうか。","respondent":"長田地域活動課長","answer":"今回の特徴ですけれども、千代田区が先行をして、昨年１０月から実施をしておりますけれども、一定の効果があったと報道をされております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"上山委員","kind":"質問・要望","question":"区民から、今、いろいろな声が寄せられたという話もあります。私は、今度の関係で、周りのたばこを吸う人に、「どう思いますか」ということでちょっと聞いてみたんです。その中には、巡回指導という言葉も見られるんですが、それから、悪質な違反者みたいなこともあるように思うんですが、どういう場合を想定されているのか、少しご説明いただけませんでしょうか。","respondent":"長田地域活動課長","answer":"先ほど、条例の中で、特に歩きたばこも含めて、一定のエリアの中では罰則を適用していくということで説明をさせていただきました。私ども、従来から行ってきましたのは、ポイ捨ての問題というのはモラルの問題だと、基本的に思っているところです。","voiceIndex":29,"id":"exchange-013"},{"speaker":"上山委員","kind":"提案","question":"先ほどちょっと述べましたけれども、今度、条例が提案されて、委員会までやられて審議されている。もう少しよく聞いてやるというのはどうだったのかなと思うんです。今後、実施するのは１０月ということだったと思うんですけれども、もう少しよく聞いてやるみたいなことは、そこら辺の感じというか、この間の扱いといいましょうか、どんな感じだったんでしょうか。少しお願いしたいんです。","respondent":"長田地域活動課長","answer":"施策の実施につきましては、区民の声を聞いてということだと思うわけですけれども、平成９年に前のポイ捨て条例を提案をしたときから、ずっと区民の声は聞いていると、私どもは思ってあります。","voiceIndex":31,"id":"exchange-014"},{"speaker":"上山委員","kind":"質問・要望","question":"次に進ませていただきたいんですけれども、１５１ページの公共施設整備積立基金の関係と学校施設の関係もあるんですが、ちょっとお尋ねしたいんです。今度、学校改築などを、区としてもいろいろ予定されているわけですけれども、どんなふうにしてこれを取り崩す、あるいは使っていこうとしているのか、少しご説明いただければと思います。最初にそこだけちょっとお願いしたいんですが。","respondent":"市岡企画財政課長","answer":"学校施設のために、一定程度基金を取り崩すことも考えていますが、これは公共施設整備基金ではなくて、義務教育整備基金を取り崩すという予定です。","voiceIndex":33,"id":"exchange-015"},{"speaker":"上山委員","kind":"質問","question":"今回、こういう形では幾つか起債もしたりとか、用地のこととかいろいろあるかと思うんですけれども、そこら辺とのかかわりはあまりないんですか。そこら辺ちょっと説明いただければありがたいんですが。","respondent":"市岡企画財政課長","answer":"学校の、特に平成１５年度については、用地関係がほとんどだと思いますが、まず用地取得に当たっては、一番大きなものは、先だって来、用地の取得の場合の起債のお話が出ていましたけれども、充当率９割ということで、起債を中心にして。","voiceIndex":35,"id":"exchange-016"},{"speaker":"上山委員","kind":"質問","question":"もう少しお尋ねしたいんですけれども、今度、小中一貫校のかかわりで言えば、用地なども手に入れるようになるかと思うんですが、そこら辺とのかかわりで、起債、それからどのぐらい予定というんでしょうか、考えていらっしゃるのか、もしわかればご答弁いただければと思うんですが、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"起債の額は、予算書に載っているとおり、平成１５年度、ほぼ５０億円の予定です。","voiceIndex":37,"id":"exchange-017"},{"speaker":"上山委員","kind":"質問","question":"今回、用地の関係で幾つかあるんですけれども、平成１５年度はそういうことだと思うんですけれども、ここでやるのが適切かどうかわかりませんけれども、この前土地開発公社のところで説明があったときに、その中では、５０億円ぐらい、公共施設建設用地取得ということで計上されておりました。そこら辺とのかかわりは、そういうことでよろしいんでしょうか。かかわりというか考え方なんですが。","respondent":"市岡企画財政課長","answer":"ただ、何度かご説明しておりますけれども、例えば、起債の時期と相手がお売りになりたいという時期が食い違っている場合、つまり先に買わなければいけないような場合については、一定程度公社で買い支えをして、その起債の許可待ち、特財待ちを、つなぎの役割をする。","voiceIndex":39,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"今、質問がありましたが、同じく１５９ページの歩きたばこ、そして１７３ページの保育所に関連して、ちょっとお尋ねしたいと思います。そしてまた、千代田区が2,０００円だから、品川区も2,０００円と。逆なんですよね。そういった実例をやらないと上がっていかないもので、注意勧告だけだったら、私はなかなか難しいと思いますので、そこら辺のところを、先にちょっとお伺いいたします。","respondent":"長田地域活動課長、松崎税務課長","answer":"それのまとめといたしましては、製造会社のほうですがＪＴと、それから小売商協同組合、大田たばこ商業協同組合と東京中央たばこ商業協同組合という二つの組合ですけれども、こちらのほうから。条例と税収の関係ですが、先行例の千代田区を参考にさせていただきましたところ、１０月に施行して、１月現在のデータが出てあります。予算に対して８３％の達成率ということで、ほぼ平年並みに推移しているです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"わかりました。この庁舎ではやってほしくないんですけれども、ある自治体では公共施設での禁煙というのが、特に学校の施設、やっぱり吸っているけれども、教員、用務員、やはり子どもたちの生活する場では、たばこを全面的に禁止していこうというような動きもあるんですけれども、うちはどうでしょうか。","respondent":"指田教育次長","answer":"一応、今の中では、とりわけ中学校や何かになりますと、吸っている子どもも中には見受けられるときもありますので、基本的にはきちんと喫煙所みたいなところで吸うような形で、なるべく子どもたちの目の前で吸わないような形で対応していきたいとは考えております。","voiceIndex":47,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問・要望","question":"ポイ捨てに引っかけて何を言いたいかというのを、これからちょっとお願いしたいんです。「ポイ捨て等」ということで、空き缶、そしてガム等も入っているんだと思いますけれども、ちまたでは、ガムという字をはっきり入れてほしいという要望が多いんですね。時間がなくなってきましたが、保養所。一碧荘を、今回、売却に出しましたけれども、ちょっとその後の経過だけ教えていただきたい。","respondent":"長田地域活動課長、西島経理課長、宮地区民課長","answer":"条例の中には、直接「ガム」という言葉は出てきておりませんけれども、私ども、この条例をＰＲする中で。ご案内のとおり、平成１３年１２月末で打ち切りまして、１月に解体工事を行いました。２月に広報およびホームページで売り出したをしたところです。今後も、できる限り効率化を図るために、ＰＲ、それから施設の改善の自主努力等をしていっていただくよう指導をしてまいります。","voiceIndex":49,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"今の答弁ですけれども、１日も増ですよね。今、それだけ増をしたからこれでいいというものではない。４日に１回休み、１月に８日休むという、そういったね。お客さんが行かなくたってあそこは運営できるんですよ、それだけの手当てをしているんだから。やはり契約の時期がいつなんですか。やはりそういったところをしっかりとしてかかっていかなくちゃいけないと思いますので、再度、お願いします。","respondent":"宮地区民課長","answer":"契約ですが、やはり、議会の中で予算が通ってからということですので、４月からの契約ということになります。","voiceIndex":53,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、頭に入れてやっていただきたい。というのは、これはまた同じように出ているように、５月に箱根が１カ月休んで、さっき言っていましたように改装しますよね。そうすると、そちらに行かれる人が今度は品川荘と暖景苑のほうに分散して利用しようかと思うんです。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-023"},{"speaker":"高星委員","kind":"質問・要望","question":"私は、３点について質問させていただきたいと思います。これは、私も、今般の一般質問の中で質問させていただいたわけですけれども、もう一度、確認の意味も含めましてお聞きしたいと思います。それが１点です。建物が幾つもあるわけですから、この辺の自治会はどうなっているのか、どういうふうにつくられていくのか。そのことだけ、まずお聞かせいただきたいと思います。","respondent":"小野政策担当課長、阿部人権啓発課長、長田地域活動課長","answer":"そういう点で、ＮＰＯと行政の関係で言うと、行政が現在できないような部分、それを柔軟に、機動的にやってもらえるというところ、そしてなおかつ。さらにもう１点、今まで比較的手薄というと申しわけないんですけれども、かかわってこなかった外国人の部分も。自治会等のつくり方も２とおりございまして、自分たちのところだけで一つ自治会をつくって、区政協力委員会に登録をしていただくような方法と。","voiceIndex":57,"id":"exchange-024"},{"speaker":"高星委員","kind":"質問・要望","question":"こういうところの方々に話をかけたか、話を持ってこられたか、それはわかりませんけれども、こういう中でつくられていくと、ややもすると第３セクター的な、つまり、ＮＰＯというのは、本来は自主的で広域団体でなければならない、自主的な団体ということで規定されているわけですから、そこのところとの整合性をよもや間違いなくしていただきたいと思います。これは難しい課題だと思います。","respondent":"中尾根企画部長、長田地域活動課長","answer":"ただ、今回、新しく幼保一元化のためにつくりましたのは、ほんとうに新しい分野であること、そしてそのことに対しての専門的知識について、どうしても私どもは一緒にやっていきたいということからでございまして。大崎第一地域センターの今後のあり方というお話ですけれども、先ほど、ご指摘いただきましたように、３１町会という区内で一番町会数を多く持っているところです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"高星委員","kind":"質問・要望","question":"こういう意味で、あそこに品川区の立派な建物もできるわけですから、ひとつ品川区の地域センターの、あまり言うといけないですけれども、すばらしいモデルみたいな形でつくり上げていただきたい。私も地元出身の議員でありますので、これから先もじっとその辺は見据えて、ときにはまたここでお話ししますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"中島委員","kind":"質問・要望","question":"私は、日ごろ区民の方から伺っている要望を伺いたいと思います。それから１７１ページ、備蓄物資管理費に関連して、それにつけ加えまして、先ほど出ました暖景苑について、短い時間の中で４点お伺いしますので、お答えは簡単にお願いしたいと思います。できれば交番とか、表にわかるように掲示をしてほしいという声が一つあります。この点については、いかがでしょうか。","respondent":"冨田戸籍住民課長","answer":"そういうことで、委員のご指摘がありましたけれども、私どものほうも、何らかの形の看板等の設置方をしていきたいと考えています。ＪＲのほうと協議して、進めていきたいと考えています。","voiceIndex":66,"id":"exchange-027"},{"speaker":"中島委員","kind":"質問","question":"ぜひ、お願いしたいと思います。そういうことで、交番の掲示のほうもお願いしたいと思います。私も、３年前に上級救命士の資格をここで取らせていただきましたが、もう３年も経つと忘れてしまいます。こういったものが何か目で見てわかるような、そういった救命法だけでも、ときおり間隔を置いて区民チャンネルで流してはいかがでしょうかという区民の方の声がありますが、これはいかがでしょうか。","respondent":"山田広報広聴課長","answer":"ただいまの救急救命法の、いわゆる講習会の形をとった放映をというご提案かと思います。本年度、いわゆる暮らしのガイドということで何本か制作をしてまいりますので、その中で検討させていただきたいと思います。","voiceIndex":68,"id":"exchange-028"},{"speaker":"中島委員","kind":"質問","question":"備蓄物資管理費に関連してなんですが、これも区民の声なんですが、備蓄物資を購入する場所がよくわからないということです。こうした販売は区ではなさっていないのかなと思うんですが、この辺はいかがでしょうか。","respondent":"久保田防災課長","answer":"備蓄品のお尋ねですけれども、現在、区の２階の売店で販売しております。そういうＰＲも、２階の展示場、あるいは、機会を通じて広報等、あるいはそういう形で、私どもも宣伝はしているところであります。","voiceIndex":70,"id":"exchange-029"},{"speaker":"中島委員","kind":"質問・要望","question":"そういったものが販売されておりますと、区民の防災意識も高まると思います。常に私たちというのは防災意識を高めていかなければいけないという点からも、考えていただけたら、これは要望いたしておきます。それから、先ほど横山委員から暖景苑のお話がありました。それは違反は違反ですから、当然、捨てられても構わないけれども、私は、やり方に問題があると思います。よろしくお願いします。","respondent":"宮地区民課長","answer":"もう少し、お客様に丁寧によく事情をご説明し、納得いただけるようにしていくように厳しく注意いたしましたので、今後はそういうことはないと思いますが、また何かありましたら、いつでも言っていただければ、すぐに注意いたしますので、よろしくお願いいたします。","voiceIndex":72,"id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"今のイカの件は、ご本人は車で持って帰ったということで、それは違います。本人はしっかりと、今、ここにありますということで私に言っておりました。その焼いたという報告、そのことも、なぜそれを言ってきたのか、私もおかしいと思います。やはり人間性の問題だと思いますね。１億1,０００万円以上の補助金をもらっているのですから、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、１５３ページの国際友好都市交流事業と、１６１ページ、生活安全推進事業についてお伺いをいたします。それから、ボランティアと、登録をしてあるメンバーがいるはずなんですが、その辺のところの把握はどうされているのか、お伺いさせていただきたいと思います。品川区での犯罪の発生の現状と対応をお伺いをさせていただきたいと思います。","respondent":"古川総務課長、長田地域活動課長","answer":"十数年経過してきている中で、三つの都市との交流を基本にしながら、そして品川区内における地域の国際化というもう一つの柱立て、この２本を主な事業項目ということで、それぞれ実施しています。区内における犯罪の状況ですけれども、警察のほうから提供していただいた資料によりますと、平成１２年では総数で6,３７４件、平成１３年、１年間では6,３３８件ということで、若干減少しております。","voiceIndex":76,"id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"お答えください。それから、もう一つは生活安全のほうですけれども、件数が減ってきたらかそれでいいというわけではないと思うんです。例えば町会等の役割の中では、向こう三軒両隣がしっかりスクラムを組んでなければいけない場合もあるわけで、そういったところを、警察との関連の中で、情報等々の伝達等については、それぞれの中でしっかり、どういう形でやられているのかというのをお伺いします。","respondent":"古川総務課長、長田地域活動課長","answer":"一定の登録をしているボランティアの方々、そしてそれぞれの事業の必要の都度にお手伝いをしていただける範囲の方々、友好協会のほうは、そういう方々のご協力をいただきながら、品川区の国際友好親善を進めていると。いずれにいたしましても、犯罪のない地域にするということにつきましては、出かけるときにはちょっと声をかけていただくとか、個人個人のちょっとした心がけ、こういういったことで日常、生活安全に関する意識を高めていただく。","voiceIndex":79,"id":"exchange-033"},{"speaker":"原委員","kind":"質問・要望","question":"特に無償の方のお手伝いというのは多いわけですよね。有償にはそれなりの理由があって、謝礼をお支払いするのは結構だと思うし、たくさんの無償の方がボランティアでかかっていただくのも結構なんですが、そこのところで、無償の方が不満を持たないような工夫を、ちょっとしてほしい。ですので、そこのところは、もうちょっとしっかりとした、不満にならない区別というようなものを工夫していただきたい。","respondent":"古川総務課長、長田地域活動課長","answer":"そういう中で、一定の報いる方法等についても検討させていただきたいと考えています。そうした意味におきましては、一般質問の中でもございましたけれども、交番の問題ですとか、地域における犯罪といったものも、この協議会の中で提示をさせていただきまして、解決に向けた話し合いを進めていきたいと。","voiceIndex":82,"id":"exchange-034"},{"speaker":"原委員","kind":"質問・要望","question":"今のような形でお進めいただければと思います。ただ一つだけ、情報を伝えるという部分においては、警察なり、行政なりの情報を、今、こういうことになって、皆さん注意してくださいという正確な情報をしっかりとお伝えいただければということ、そこだけ要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"私は、１５１ページの私立幼稚園関係費についてと、１６７ページの行政評価システム経費について、お伺いします。初めに、プリスクール西五反田についてお伺いしますが、もう何人かの委員からお話が出ましたので、簡単に質問します。今までの幼保一元化と、ＮＰＯという以外には、どこが違うのか、質問します。","respondent":"古川総務課長","answer":"大変難しいご質問なんですが、今までの幼保一元化とどのように違うかという視点でとらえますと、幼保一元化というのは、とりもなおさず二元的な管理体制、国の文部科学省、あるいは厚生労働省をそれぞれ縦系列にとった幼児教育機関である幼稚園と、福祉施設である保育園と。","voiceIndex":87,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"今、少子化ということで、私立幼稚園の経営自体が厳しくなっていると伺いますが、私立幼稚園の振興策としては、どのような意味を持っているんでしょうか。","respondent":"古川総務課長","answer":"それは、一定の努力をなさっている結果だろうと考えていますし、私ども、さまざまなご要望を受けとめながら、補助もその一つですが、私立幼稚園の振興策を、この間、さまざまな形で取り組んできた成果だろうと思っています。","voiceIndex":89,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"今、保育課長は金子課長ですが、たしか私がまだ議員になってなかったときに、古川総務課長も保育課長をなされた時代があったとお伺いしています。そのときに、保育行政のすばらしい改革をなさったと伺っているんですが、保育課長のときにしたことと、総務課長になられたということで、やっぱりそういう流れでこういう施策というのは出てくるんでしょうか。","respondent":"古川総務課長","answer":"そういう意味合いにおきましては、品川区の中で、さまざまな形で、就学前施設に対し期待をしていきたいと考えております。","voiceIndex":91,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、行政評価システム経費について、お伺いします。先ほど、企画財政課長のご説明の中で、外部委員会ができたというお話が出ましたが、この構成メンバーと、外部の方はどんなメンバーが入っているのか、女性はどのぐらい入っていらっしゃるのか、教えてください。","respondent":"榎本行財政改革担当課長","answer":"公募区民につきましては、応募は１５名ございまして、そのうち４人ということで、地域、年代、過去のいろいろな活動ですとか、参加意欲等で、４名を選ばせていただいたところです。この中で女性のメンバーが３名入っております。学識経験者１名、公募区民２名ということです。","voiceIndex":93,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"最後に、私たちは選挙で選ばれた住民の代表の議員ですけれども、それ以外に公募を入れたということは、外部の一般の方からもご意見を伺いたいという、これは区長の思いなんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"公募区民を入れていくというのは、ここのところ、新しくつくった附属機関、審議会等では、内容等もありますけれども、大体公募区民を入れていくという方向になっております。もちろん、区民参加ということで、こういう形での手法をとっているところです。","voiceIndex":97,"id":"exchange-040"},{"speaker":"桜井委員","kind":"質問・要望","question":"もう一つは、総合区民会館のかかわっている都市整備公社も含めて、この間、情報公開の問題で第３セクター、文化振興事業団をはじめとして、国際友好協会、スポーツ協会、一定程度の要綱も定め公開となってきたわけですけれども、株式会社品川都市整備公社についての公開はどういうふうに考えているのか、お尋ねいたします。","respondent":"上山区民生活事業部副参事","answer":"主に清掃、警備等の委託、そして管理組合負担金等につきましては、管理者である品川都市整備公社のほうに委託をしているものです。管理運営委託につきましては、公の施設の管理運営ということで、財団法人品川文化振興事業団のほうに委託をしております。","voiceIndex":101,"id":"exchange-041"},{"speaker":"桜井委員","kind":"質問","question":"区長、わかりますでしょうか、ちょっと遠いんですけれども、一番右側に総合区民会館がありまして、今、私が質問申し上げました管理委託は文化振興事業団、それから、品川都市整備公社に管理委託。これが非常にわかりにくいことなんです。ですから、総合区民会館からは、いろいろな線を通って株式会社に行って、またほかに再委託をしている。どうして、こういうふうなわかりにくい委託をしているんでしょうか。","respondent":"小野政策担当課長","answer":"ここの中で、当然、商業施設、区民施設ということでそれぞれいろいろ違った施設が入っておるわけですけれども、それぞれで清掃等をやりますと、一体の施設ということで、実際の仕事、あるいは管理上の問題が難しいということで、一たん。","voiceIndex":106,"id":"exchange-042"},{"speaker":"桜井委員","kind":"質問","question":"２０年近くになるんでしょうか、ずっとＣＳＣサービスに委託をしているわけですよね。実際のこの3,１００万円というのは、原資として当然区民の税金からいくわけですから、総合区民会館という公の施設を管理しながら、そこで品川都市整備公社がもうけるというシステムが、区民から見れば非常にやっぱりわかりにくい。その民間会社からの出資は、総額幾らになっているでしょうか、改めてお知らせください。","respondent":"小野政策担当課長","answer":"そういう意味では、なかなか行政として十分、迅速に対応しきれない部分がありますので、第３セクターの中でこれをやることによって、より迅速に、あるいは効率的に管理ができるということで、品川都市整備公社に管理を委託しているです。","voiceIndex":108,"id":"exchange-043"},{"speaker":"桜井委員","kind":"質問","question":"実際の事業計画を見てみますと、かなり品川都市整備公社が事業をやっていらっしゃる。果たして、こういう株式会社は一体、区との関係でどういうふうに位置づけているのかと、私は常々疑問に思っているところなんです。こうした株式会社品川都市整備公社の会長として、どういうふうにこれからこれを運営されていこうと思っているのか。それから、それとの関係で、品川区の運営についてお聞きしたいと思います。","respondent":"濱野助役","answer":"その後、地方自治法が改正されまして、施行令が改正されて、いわゆる株式会社でも、たしか３分の２だったか、区が一定程度出資をしている会社であれば、公の施設の管理ができると位置づけられました。","voiceIndex":110,"id":"exchange-044"},{"speaker":"桜井委員","kind":"質問・要望","question":"私は、区長が会長としてどういうふうに考えているかということを、ぜひ教えていただきたいと思っています。もともと株式会社というのは、言うまでもなく、利益を追求していく。これだけの株式会社をやっていくというならば、少なくともどういう仕事をされていて、どういう考えのもとに会社を経営していくのかという会長としてのコメントも、ぜひ必要だと思いますけれども、いかがでしょうか。","respondent":"高橋区長、濱野助役","answer":"私、会長ですけれども、平重役でございまして、代表権は社長が持っておりますので、社長から発言いたします。そういう時代の中で、この会社を区として活用していくというのは、当然の方向だと考えておりまして、この辺は見解の相違かと思います。","voiceIndex":112,"id":"exchange-045"},{"speaker":"桜井委員","kind":"質問","question":"見解の相違という言葉はやめたほうがいいと思いますけれども。ですから私は、区民の区営住宅の、さまざまないろいろ大変困難を抱えているところの滞納使用料収納業務、ここまで株式会社に委託をしていく、区営住宅の区民の生活の大切な管理を委託していく、私はいかがなものかという考え方を持っています。情報公開の問題でお答えをいただいてないんですけれども、改めてお願いします。","respondent":"濱野助役","answer":"先ほど、広報広聴課長からご答弁申し上げましたように、第４８回の取締役会で、情報公開についても対応していくと決めてありますので、何か情報公開をやっていないかのようなあれですけれども、やっておりますので、ご理解いただきたいと思います。","voiceIndex":115,"id":"exchange-046"},{"speaker":"桜井委員","kind":"質問・要望","question":"情報公開については、失礼いたしました。そうしますと、株式会社として、定款というのか、何か取り決めとした文章になっているんでしょうか。そこだけちょっと確認して、改めて教えていただきたいと思います。","respondent":"濱野助役","answer":"定款にはございませんけれども、事務方の取り決めのようなものにあります。","voiceIndex":117,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、１５５ページ、総務管理費の健康診断事業、それから代替職員雇用経費、あと、１６５ページ、広報費、それからインターネット等経費、１６７ページ、企画調整費の中からちょっと質問させていただきたいと思います。この辺が大幅に減員になっている理由として、当然、行政改革の一環だと思うんですが、この辺、どうとらえていいのかということを、まず１点、お聞きしたいと思います。","respondent":"桑村人事課長、小野政策担当課長","answer":"１点目の代替職員の経費が落ちた理由なんですけれども、私どもで持っております代替職員経費は、いわゆる欠員ですとか、病欠ですとか、育児休業ですとか、正規の職員が一定の期間いない場合に、私どもの職員課の経費で。これは端的にこういう理由でということはございませんけれども、事業部支援プロジェクトということで、平成１５年度につきましては、各事業部で施策を展開していくのに必要な行政事業を把握をするということで、基礎的な調査を、今回。","voiceIndex":120,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"代替職員のほうなんですが、非常に減っているということでいいことだと思うんですけれども、そのことによって事業の進展に支障は出ていないのかという点を、もう１点、教えていただきたいと思います。それから、事業部支援プロジェクトですが、昨年とは内容的には大分変わったととらえていいんですか。その辺だけ、もう１回、お願いいたします。","respondent":"小野政策担当課長、桑村人事課長","answer":"昨年の場合は、初めての事業部支援プロジェクトという形で予算化をいたしまして、事業部制２年目ということで、そういう意味では、新たに各事業部の中で。そういう意味では、決して私どもが何か拒否しているとかいうことではございません。一定の話し合いの中でやっているものですから、事業に支障は出ていないと考えています。","voiceIndex":123,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今のお答えですが、確かにこれからも少ない人数の中で一生懸命頑張っていただきたいと思いますので、よろしくお願いいたします。この点については、また改めて質問する機会を持ちたいと思っています。これは、職員の人数が減ったという感じから出ているのか、内容的なものが変わったのか、その点を先にお答えをお願いします。","respondent":"桑村人事課長","answer":"これは一つは予算の組み方で、職員が減ったということもありますし、決算の不用額が少し出ていたものです。その意味で、内容は同じものですけれども、少し予算上の工夫をしたというものです。","voiceIndex":126,"id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問","question":"健康診断をほんとうにやったか、やったから大丈夫とは言えないですけれども、こういうものをきちんとやっておいていただいて、皆さんいろいろなストレスもたまってくると思いますし、内容を下げないでほしいという意味での質問をさせていただきました。それから、この部分を教育委員会のほうとしては、どう考えているのかというのがちょっと疑問で、質問の内容です。","respondent":"山田広報広聴課長、青木指導課長","answer":"今までのように、私どもがペーパーでやっていた世論調査というのは大人の方を対象にしていたわけですけれども、今後、このやり方をとれば、年齢別に切りながら。先日の本会議でも、川西議員のご質問にお答えしておりますが、区政や区の仕事を学ぶということは重要なことだと考えております。","voiceIndex":128,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"内容的にはわかりました。学校の中で、これから検討というお話だったんですけれども、ここまで出ている中で、教育委員会と広報の間で、その辺のすり合わせはしていらっしゃるのかなというのを、今、非常に感じました。それからもう一つ、当然、小学校なり中学校のインターネットをパソコンで開いた段階で、区のホームページは当然開けるということでよろしいんですね。","respondent":"山田広報広聴課長","answer":"今回の世論調査の設計に当たっては、多面的には検討しております。","voiceIndex":131,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問","question":"せっかく学校の中で使える、そしてインターネットの授業をやっていますよね。使いこなせていない方の研修というのは、どうなっているのかなと。庁内というか、ある人の話だと、やはり使い勝手の悪い方、ちょっと高齢の方ですと、使いきれていないというお話も伺っています。その辺をどういうふうにお考えになっているのか、お答えをお願いします。","respondent":"田中情報システム課長","answer":"ただ、非常に年齢の高い方で、なかなかなじみにくいという方がおられますので、その点については、今後とも丁寧に、職場の皆さんの助け合いの中で習熟できるように、各職場で情報化推進委員という体制も取っておりますので。","voiceIndex":133,"id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺のあまり使えない方を忘れていかないように、アンケートの対象として外さないように心がけていただきたい。それからもう１点最後に、皆さんもそうですけれども、パソコンをいじっていると、どうしても画面に向っちゃっているんですよね。その辺、相反する部分なんで、答えようがないのかなと思うんですけれども、その辺について、ちょっと考えていただければと思うんですが、どうでしょうか。","respondent":"本間総務部長","answer":"今、ご指摘もございましたとおり、パソコンも、仕事を効率よく進めるための道具です。そういう意味では、それを使いながらフェース・ツー・フェースで、区民の方へのサービスも忘れずに、これから取り組んでまいりますので、よろしくお願いいたします。","voiceIndex":135,"id":"exchange-054"},{"speaker":"藤田委員","kind":"質問・要望","question":"私から、１５７ページの庁舎管理、１６８ページの防災対策、この二つにつきまして、お聞きしたいと思います。庁舎管理のほうですが、私は３点ほど、一つ一つ質問をしたいと思います。そのために、あそこは非常に危険です。道幅がぐっと広がりますから、お考えを伺いたいたい。７番目が二葉四丁目。これは東京都の調査ですけれども、これについて何か感想がありましたら、お聞かせいただきたい。","respondent":"西島経理課長、久保田防災課長","answer":"あそを、木を取り払いまして空き地にしたほうが有効であるというご意見をいただきましたので、検討させていただきたいと思います。東京都が今回、実施しました地域危険度調査の感想です。今回、都が行っている調査は５回目になりまして、これの目的というのは地震に強い防災まちづくりの指標とするです。","voiceIndex":138,"id":"exchange-055"},{"speaker":"藤田委員","kind":"提案","question":"かなり人通りが多いですから、やるんであれば、新年度予算で早急に。私は、五、六年ほど前に、りんかい線の工事をする前に提案したことがあります。その出たところなんですよ。そのときに、ちょっとして足が引っかかってしまうということで、ぜひ、改善方を要望したいと思います。火が移らないように高木を植えるとか、いろいろな形で対策を考えていく必要があると、私は思いますが、いかがでしょうか。","respondent":"西島経理課長、浜脇住環境整備課長、久保田防災課長","answer":"大きな構造を変えるというのは、なかなか難しいとは思いますが、ミラーをつけるなり、あるいは何か改善策ができないか。一方では、道路も若干狭いところが多いようですから、道路につきましても、拡幅を目指して、今、手を打って検討しています。この地区についての消火器の重点配置については、これまでも街頭用消火器の設置をやっておりましたけれども。","voiceIndex":141,"id":"exchange-056"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひ、よろしくお願いをしたいと思うんです。危険度調査は、発表以来、やはりまちでは話題になっています。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-057"},{"speaker":"土井委員","kind":"質問・要望","question":"私は、３点になるんでしょうか、１５１ページにあります基幹事務管理システム関係、それから、１７９ページの住民基本台帳ネットワーク関係、同じく住民基本台帳の関係では、監査委員費のほうにも出ておりますので、この辺と、さらにもう一つは、先ほどのたばこの関係のところで一つお伺いしたいのと、１８１ページの品川区民カード交付事務、これについてお伺いをしたいと思います。","respondent":"田中情報システム課長、冨田戸籍住民課長、南監査委員事務局長、市岡企画財政課長","answer":"基幹事務管理システムの財源ですが、一般財源です。特定財源等は入っておりません。あるいは、今後のことになりますけれども、公的個人認証の制度化がもし実施された場合には。内容はまだ、細かく仕様等を詰めてございませんが、主として、入退室管理ですとかいろいろな規定ありますが。人口、世帯数に応じて少し算定を修正するような形で加算分がある、いずれにしても一般財源であることは間違いございません。","voiceIndex":147,"id":"exchange-058"},{"speaker":"土井委員","kind":"確認","question":"そうすると、その通信回線の維持管理も全部我々のほうで持っていると、こういう形なんだということで確認をしてよろしいですね。そして、それは、その点から言っても、これは維持も含めてもっともっと国が金を出すべきしろものだと思うんで、そこら辺をもう一度確認をして、場合によっては国に要求をしていくべき内容ではないかと、このように思いますので、お伺いをしておきたいと思います。","respondent":"冨田戸籍住民課長","answer":"それからあと、国が出すべきであるという財源の部分ですけれども、住基カードのほうが、今年度施行の予定ですけれども、その経費については、今のところ、不交付団体ということで、全部特別区の負担になっております。","voiceIndex":152,"id":"exchange-059"},{"speaker":"土井委員","kind":"質問・要望","question":"病院とか、いろいろなところに行っても、身分確認を求められるときに、それは品川区が出すんですから、区内の皆さんだったら、「そのカードでもわかるよ」とおっしゃるかもしれないけれども、よそへ行ったら、「全然そんなのは知らないよ」と言われると困るわけなので、その辺との関係は、そのカードはどのようになるのかということについて、お伺いをしておきたいと思います。","respondent":"冨田戸籍住民課長、長田地域活動課長、田中情報システム課長","answer":"あくまでも本人確認のためが主目的ですので、品川区役所に対する何らかの届出等にお使いいただけるものと思いますけれども、それ以外のものにつきましては。たばこの問題ですけれども、従来の条例を設置したときからも、商店街等々には大変なご協力をいただいてあります。そういう意味で、区民の情報について、どういうふうに取り扱われたか断言していただきたいという土井委員の質問ですが、そういう面では、今、出せますが。","voiceIndex":154,"id":"exchange-060"},{"speaker":"土井委員","kind":"質問・要望","question":"最後のほうから聞きます。ですから、そう言ってもらわないと、みんな安心しないわけだから、そういう意味で確認をします。こういうときこそ、「歩きたばこ等」とつけなきゃいけないわけですね。ここに書いてあるのが全部だし、先ほどのガムも入るわけですから、そうですよね。ですから、たばこを売っているところだけじゃなくて、チューインガムを売っているところにも、お話ししなきゃいかんわけですよ。","respondent":"田中情報システム課長、冨田戸籍住民課長","answer":"先ほど、答弁しましたアクセスログの、容易に取り出すシステム開発ですが、住基ネットについては都道府県のほうで協議しまして、そういう形で容易に取り出せるようなシステム開発をするということで。あくまでも品川区内のものと考えています。ただ、いろいろな機会をとらえて、品川区で発行しているという事実については伝えていきたいと考えています。","voiceIndex":158,"id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"１点目、先ほど、ＮＰＯの契約という話がありました。それから、契約というとさまざまな契約があると思いますが、区内業者をどんどん使っていただきたいという観点からいくと、今度、校舎改築をはじめ戸越幹線等もさまざまこれから工事が出てくると思いますが、その中で必ず、ＪＶという考えが出てくると思いますが、その考え方をもう一度、ご確認をしたいと思いますので、そこら辺をまずお聞かせください。","respondent":"久保田防災課長、西島経理課長","answer":"今般、地域防災計画の見直しを考えておりますが、その主眼点ということでお話します。今回の改定につきましては、東京都のほうが、今、地域防災計画の見直しをして、間もなく発表する予定です。こういう２点の目的でＪＶを実施しています。ちなみに、基準ですけれども、建築、土木工事は、予定価格が約４億円、造園、設備関係については１億3,０００万円以上のものを、現在、対象にしています。","voiceIndex":162,"id":"exchange-062"},{"speaker":"石田委員","kind":"意見","question":"例えば震災になったとき、じゃあ遺体をどうするのか。だけれども、どうしても嫌だという方もいらっしゃるかもしれない。そういうときに、じゃあ、こういうところとこういう協定がありますので、ご紹介できますというサービスというか、そういうメニューづくりも一つの協定の中に入れ込んでいくのもいいのではないかと考えていますが、そこら辺の考え方を、まずちょっとそっちだけを聞きます。","respondent":"久保田防災課長","answer":"今、お話にありました遺体の運搬ということにつきましては、災害時には、今のところは適切な車両の確保というのがなかなか難しいということで、例えば、トラックとか、あるいはそういうものを考えられるわけですけれども、もう一歩進みまして、確かに霊柩車の確保というのも。","voiceIndex":165,"id":"exchange-063"},{"speaker":"石田委員","kind":"質問・要望","question":"大体わかっているんですが、先ほど言いましたように、最低限のレベルで組むのはもちろんいいわけですが、せっかくここで協定というか、防災計画をつくり変えるのであれば、そのメニューづくりの一つとして、さまざまな方がいらっしゃるわけですから、そういうところもお考えになっていただきたいということですが、今、考えていただけるということなので、それでよしとしたいと思います。","respondent":"西島経理課長、古川総務課長","answer":"ＪＶのお尋ねですけれども、先ほど基準のお話をしましたけれども、一番最初に目的のお話をしましたように、ＪＶの目的は、区内の中小企業の受注機会の拡大を図るですので、基準は基準として、現在の経済情勢を勘案しながら。就学前施設の運営委託の関係ですけれども、結果として、ＮＰＯという一つの形態ということで、先ほどもご説明申し上げました。最初からＮＰＯというわけではございません。","voiceIndex":167,"id":"exchange-064"},{"speaker":"石田委員","kind":"提案","question":"それじゃ、例えばいろいろな組合が環境ＮＰＯを一生懸命勉強しているんだと、こういう提案をして、提案をするのが先なのか、ＮＰＯをつくるのが先なのか、その考え方が逆みたいな感じがするんだけれども、そこら辺の点をお聞かせください。","respondent":"古川総務課長","answer":"そういうときに、先ほども申し上げましたけれども、ＮＰＯ法人を立ち上げようという機運が期せずしてあった。そういう中で、こういう施設を私どもも考えているというところで、事態といたしましては、それを運営するに足りる一つの団体としてＮＰＯ法人を考えているです。","voiceIndex":170,"id":"exchange-065"},{"speaker":"石田委員","kind":"質問・要望","question":"時間もないので、またピアサポートとか、そういうところで考え方をやっていきたいと思いますが、先ほど、企画部長がおっしゃった、より質の高いサービスというところの補完的な意味ということもあれば、どちらが先かというところだけはお考えいただきたい。もし答弁があれば、お願いします。","respondent":"中尾根企画部長","answer":"今回については、非常に見えにくい部分がありますけれども、同時進行だと思います。今後については、管理運営等を決めて、きちんとしていきたいと考えています。","voiceIndex":172,"id":"exchange-066"},{"speaker":"船波委員","kind":"質問","question":"私からは、１５３ページの国際友好協会の事業、１６９ページの携帯電話、ポケベルなどによる通報システム、それから１７９ページの戸籍電算化、住民基本台帳ネットワークについてお伺いしたいと思います。利便性などが言われているのかもしれませんが、何が便利になるのか、効率化になるのか、そういうところをお伺いしたいと思います。","respondent":"冨田戸籍住民課長","answer":"あわせて、現在、住民票については住基ネットということで、全国統一した処理になっていますけれども、戸籍について、現在、国のほうでオンライン化を検討されております。近々、もう少し具体的なものが出てくるかと思いますけれども、当然、電算化が前提になると考えています。","voiceIndex":175,"id":"exchange-067"},{"speaker":"船波委員","kind":"質問","question":"その両方を比べてみても、戸籍のほうは手書きのものをコピーするから、住民票の写しを取るよりずっと格段に時間が待たされるということは、特にないのではないかと思うんです。それにもかかわらずこれだけの費用をかけてやるというところについて、ほんとうにこれだけの費用をかけてやるものなのかどうか、ちょっと疑問を持つんですが、その辺についてはどうお考えなんでしょうか。","respondent":"冨田戸籍住民課長","answer":"一つの大きなメリットですけれども、省力化というのがあります。やはり人手で処理をしているのが現実ですので、機械化できるものは機械化していきたいということで、相当数の職員の減を見込んでいるものです。","voiceIndex":177,"id":"exchange-068"},{"speaker":"船波委員","kind":"質問","question":"先ほどのお答えでちょっと気になったのは、国のほうでオンライン化を検討されていて、いずれはオンラインというお答えでしたけれども、品川区という自治体の中だけで電算化するのではなくて、いずれは住民基本台帳ネットワークのように、他の自治体ともつながれてしまうということも視野に入っているんでしょうか。","respondent":"冨田戸籍住民課長","answer":"将来的には、例えば婚姻届けを出すについても、現在、品川区に本籍のない方については、品川区に届出をされる場合は、その方の戸籍抄本なりをお出しいただくわけですけれども、そういったものも必要なくなるでしょうし、そういった意味合いから。","voiceIndex":179,"id":"exchange-069"},{"speaker":"船波委員","kind":"質問","question":"この間の手数料のところでちょっとお聞きしましたけれども、今度、８月から予定されているカードの交付が、予算の上では一応4,２７０人分で、実際は3,０００件ぐらいではないかというお話です。そうしますと、１年分としても6,０００人ぐらいの方がそのカードを申請すると見込んでいるということです。そういうことに関しては、どうお考えなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-070"},{"speaker":"船波委員","kind":"質問・要望","question":"そのわりには、こういうことをやっていっていいのかというのが疑問であります。品川区でも、国がやることになっているから、やりますというのではなくて、ソフトに関して、利便性だとか、個人情報の管理ということを、きちっと品川区として主体的に考えてやっていってほしいと思っています。そういうところもぜひ、やっていただきたいと思うんですが、どうお考えなんでしょうか。","respondent":"古川総務課長","answer":"しかしながら、今回、この事業の中には具体的な数字としては確かにあらわれておりませんけれども、１０周年の事業もそうですけれども、韓国の方に限らず、品川区にいらっしゃるさまざまな外国の方、あるいは日本の方々に、そういう機会を利用してご参加いただけるような広報。","voiceIndex":184,"id":"exchange-071"},{"speaker":"船波委員","kind":"質問・要望","question":"予算書と同じページに載っていますけれども、平和友好の事業で、中学生などを長崎、広島へ派遣するというのがありましたが、平和について、あるいは核兵器の恐ろしさについて学んだりするのは、広島、長崎ばかりではないと思います。核実験が行われた太平洋の国々などのことも学ぶ点であると思うので、その辺も、今後考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-072"},{"speaker":"三上委員","kind":"質問","question":"１６１ページ、生活安全推進事業、１７１ページ、防災区民組織育成費および品川区防災地図印刷、それから、１８３ページ４項の選挙費という部分で、関係してお伺いしたいと思います。最初に、生活安全推進事業、生活安全条例というものが平成１４年４月１日付で施行されております。この中で、どういったことを中心に取り組んでいこうというお話になったのか、ちょっとお伺いしたいと思います。","respondent":"長田地域活動課長","answer":"協議会につきましては、もう既に１回開かれまして、第２回目がこの３月１８日に予定されているものです。最初は、第１回の顔合わせですから、私どものほうから条例の趣旨等を説明させていただきまして、それぞれの役割分担等を確認をさせていただきました。","voiceIndex":189,"id":"exchange-073"},{"speaker":"三上委員","kind":"質問","question":"警察との連携がとりやすくなったということであります。先日来から地域にあっての安全ということについていろいろ議論されてまいりました。〔「今もやっている」と呼ぶ者あり〕今も確かにあるかわからないけれども、以前に比べると、よく日中回っているという姿があまりよく見えないという感じもしながら、そこらあたり、どんな状況かおわかりになりますでしょうか。","respondent":"長田地域活動課長","answer":"警察官の巡回の問題ですけれども、私ども、子どものころは、よく警察官が台帳を持って、個々の家庭を訪問していたような記憶があります。そういうことからすると、現在においては、昔みたいな形ではやられていないんだろうと思ってあります。","voiceIndex":191,"id":"exchange-074"},{"speaker":"三上委員","kind":"質問・要望","question":"こうなったら、８年間、二度とお会いしていませんよ。そういうような仕組みが、いまだもって残っているとすれば、やはり困る話になるものですから、そこらあたりがどういう状況になっているか、おわかりになれば教えていただきたいけれども、それは無理でしょうから、ぜひこういった生活安全協議会の場で、こういった具体的にそこの交番の守備範囲はどういう形で決められていくのか。","respondent":"長田地域活動課長","answer":"交番の受け持ち範囲まで、私どものほうでは、申しわけありませんけれども、把握をしてございません。","voiceIndex":193,"id":"exchange-075"},{"speaker":"三上委員","kind":"質問","question":"かなりの世帯があるわけですけれども、何世帯ぐらいの方が住んでいらっしゃるか、おわかりになるでしょうか。公務員が住んでいる関東財務局関係の施設の中で、ほかの地域では、いろいろな地域の行事なんかにも関係して、積極的に協力してくれているところもあると思うんですけれども、そこらあたりについての接触というのはどういうふうにされているのか、お伺いしたいと思います。","respondent":"長田地域活動課長","answer":"小山台二丁目、昔の林業試験所の中に公務員住宅２棟あるのは承知をしていますけれども、ちょっと何戸あるか、把握してございません。","voiceIndex":195,"id":"exchange-076"},{"speaker":"三上委員","kind":"質問","question":"これは、現実な悩みだと思います。ですから、公務員住宅の皆さんは自治会が形成されていないという雰囲気に、私は思っているんですけれども、連絡員という方がいる。これは学校当局だって同じことを言えると思うんです。そこのところをもう１回、お願いしておきます。以前に印刷された地図と、同程度の範囲での地図なのか、ちょっとお伺いしたいと思います。","respondent":"久保田防災課長","answer":"防災地図についてですけれども、今回の大きな改定の主は、都のほうの広域避難所の改定がございましたので、それにあわせて地図を改定する予定です。","voiceIndex":197,"id":"exchange-077"},{"speaker":"三上委員","kind":"質問・要望","question":"以前、町丁別に１枚ずつの地図を印刷しましたよね。４段ぐらいの階段であっても、お年寄りの方は手すりをつけてもらいたいという場所もあるんだという要望がありました。ですから、そういった要望の場所を、これから選挙管理委員会、もしくは教育委員会でお互いに協議して、手すりをつけてもらいたいというような場所があれば、ぜひお願いしたいと思うんですが、いかがでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所の件ですけれども、具体的にそういった箇所があれば、個別に障害者等のために対策をとりたいと思いますので、教えていただければと思います。","voiceIndex":199,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時間があったら１５５ページの職員研修費をお伺いいたします。庁舎等整備工事なんですけれども、昨年の予算特別委員会で、優しいまちづくりを進めてほしいという意味で、議会棟の中に車いす対応のトイレを、ぜひ１カ所設置していただきたいと、このように要望したんですが、そのときの答弁は、整備は進めていくが、なかなか困難なことであるというお答えをいただいて、１年が経ちました。","respondent":"西島経理課長","answer":"車いすのトイレをつくるためには、一般的には２ｍ四方、小さい場合でも２ｍ２０cm×１ｍ２０cmぐらいのスペースが必要ということで、たしか、こちらは男子用が大が１カ所、女性用は大が２カ所しかないということで。","voiceIndex":202,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問","question":"昨年とほとんど同じ中身だと思います。委員会とか本会議の傍聴にいらっしゃった方、５階、６階を利用された方が、どこのトイレを利用したらいいのか、率直に伺いますけれども。","respondent":"西島経理課長","answer":"５階であれば、並行移動していただけるんであれば第２庁舎ということになろうかと思います。議会等にそういう方もお見えになると思いますので、案内については工夫をさせていただきたいと思います。","voiceIndex":204,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民に開かれた議会にしていくという面では、やっぱり困難があってもハード面での工夫、計画を、ぜひ具体的にお示しいただきたいと思います。表示なんです。聞けば、案内してくれるかもしれないけれども、聞かなくてもわかるような、ぜひわかりやすい表示をしていただきたいと思うんです。","respondent":"西島経理課長","answer":"失礼いたしました。今の案内というのは、表示も含めて、わかりやすい表示をするということで工夫をしてまいりたいと考えています。","voiceIndex":206,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、計画を具体的にお示しいただきたいと思います。これはほんとうに強く強く要望をします。リフレッシュ工事なんですけれども、昨日のご質問の中でも、利用しやすい地域センターにしていくということで、ふれあいサポートの推進のためにも工事をしていくんだというご答弁をいただきました。具体的に工事の内容を、簡単にで結構なんで、お知らせをいただきたいと思います。","respondent":"長田地域活動課長","answer":"特にリフレッシュといいましても、構造自体を変えることができない部分がありますので、大規模なエレベーター等の設置については、建て替えのときですとか、大規模改修という部分でその都度やってまいりたいと思っているところです。","voiceIndex":208,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほとんど全体的に内装と外壁がきれいになるということで、大変嬉しいことだと思って、使われる方が集いやすい場所になると思って喜んでいます。地域の方が地域センターを利用するんだけれども、床が揺れるとか、ひびがたくさん入っていて心配だという声もあるので、その辺の安全性もぜひ示していただきたいんですが、この辺は計画的には、大規模改修のときだけなんでしょうか。","respondent":"長田地域活動課長","answer":"エレベーターの設置につきましては、現在もまだ１カ所検討しているところがあることはあるんですけれども、いろいろな条件の中で、果たしてこれができるかどうかというのは今後の検討になろうかと思います。","voiceIndex":210,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"エレベーターは１カ所検討中ということなんで、ぜひ、実現の方向にいっていただきたいと思います。今、鉄骨、鉄筋なんで、安全性のところは大丈夫だろうということなんですけれども、耐震診断、耐震対策がとられていないという面では、ほんとうに安全ですよと言いきれない部分があるので、ぜひその辺も、時間もお金もかかるとは思うんですけれども、計画を立てていただきたいと思います。","respondent":"長田地域活動課長","answer":"建物は、安全であることは一番のことかと思います。私ども、そういった意味におきましては、機会あるたびに安全の確認はしてまいりたいと思います。","voiceIndex":212,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ふれあいサポート推進事業についてお伺いします。プレス発表を見ているんですが、なかなか中身がよくわからないんで、具体的に中身の説明をしていただきたいと思います。簡単にで結構です。","respondent":"長田地域活動課長","answer":"特に去年からは、民生委員の１３地区化に伴いまして、より連携を深めていこうというようなこととか、あるいは災害弱者もこの対象の中に入れていこうということ、それから当然、そういうことをしていく中では、推進体制の強化も図っていかなければいけないだろうということで。","voiceIndex":214,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すごく単純な質問なんですが、事業の対象となる方は、どういう範囲の方なのか、教えていただきたい。今、経過を言っていただいたんですが、社会福祉協議会でやられていたのを地域に持ってきて、さらに強化ということですよね。今、ざっとはボランティア会議とか、推進会議とか行われるということですけれども、今までの事業と明確に違うところは、その辺なのでしょうか。","respondent":"長田地域活動課長","answer":"お年寄りでも、元気なお年寄りがいらっしゃいますけれども、こういった方は、サービスを提供する側に回っていただきたいということで、私どものほうでは、基本的には自立支援、それから要介護でも軽い部分が対象になるかと思います。","voiceIndex":216,"id":"exchange-086"},{"speaker":"飯沼委員","kind":"意見","question":"今までのとどの辺が違うのかというところを、再度また少しリニューアルというか、強化するということなんですけれども、その辺の違いを、もうちょっと明確に。どこが違うのかなという率直な疑問があるので。","respondent":"長田地域活動課長","answer":"今回、地区のふれあいサポート活動会議を組織しましたという説明を申し上げましたけれども、この中には、町会、自治会をはじめ民生委員とか、高齢者クラブ、あるいは地域のボランティア、ＰＴＡ、ところによっては企業等も含んだ中で、こういった会議を立ち上げまして。","voiceIndex":218,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど、対象者を伺ったんですけれども、なかなか範囲が難しいですね。だれがどう判断するのかというのがなかなか難しいなと思ったのと、組織化をされたということでは、この図なんかを見ると一大事業だなという印象をすごく受けるんです。この辺はどなたが担っていくのか。この辺のコーディネートをされる方のところと、資質アップについて、お伺いします。","respondent":"長田地域活動課長","answer":"体制の整備の中では、社会福祉協議会が地域の中での福祉を進める団体としての先駆的な部分を担ってありますので、それからボランティアを所管しているという部分もございまして、社会福祉協議会の協力を得て、職員の研修、それからまた。","voiceIndex":220,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"さっきお話がありましたけれども、特に福祉の意識が大事だという意味では、係長級の方というお話があったけれども、事務職の方というよりも、福祉の専門家がするような福祉の施策ではないかなと思うんですが、その点が１点。社会福祉協議会や在宅介護支援センターとの連携のところが、どのように行われるのか教えてください。","respondent":"長田地域活動課長","answer":"こういった部分につきましては、私ども、午前中も交通整理という言葉を使わせてもらいましたけれども、少なくとも専門分野にきちっと引き継ぐ、そこで責任を持った対応していただくと、こういう取り扱いをするように、今、地域センターでは心がけておりますので。","voiceIndex":222,"id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時間があと少しあるので、職員の研修についてお伺いをします。インターネットとか、パソコンの使用が大変増えていく中で、保育園の職員から、もう手書きの書類はだめで、全部パソコンで打ち出してほしいと言われて四苦八苦している人が結構いらっしゃるんです。持ち帰って仕事をしていることを把握されているのかどうか、その点にお伺いします。","respondent":"金子保育課長","answer":"保育園におけるパソコンのお尋ねですけれども、私ども、現在、３台置いておりますが、当初置いたときには、それほどの業務量はないかと思ったんですけれども、その後、順調に活用されていまして、台数を増やす方向で考えております。","voiceIndex":224,"id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１５１ページ、電子計算組織運営費に関連して１点と、１６９ページ、防災会議費等に関連して質問をします。電子計算機のほうですけれども、簡単に、ここに磁気テープ保管料等とありますけれども、現在時点で、品川区のこういう電子計算機等のデータを、どういうふうにして管理しているのか、それから安全対策をしているかということを、簡単にお聞かせください。お願いします。","respondent":"田中情報システム課長","answer":"一つのシステムがシステムダウンを起こしても、データが確保されるような形になっております。それ以外に大きな災害ですとか、地震等に遭った場合でも素早く復旧できるように、安全なデータ保管庫にバックアップして保管しているという形をとっております。","voiceIndex":227,"id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"それと比較にならないような情報が、今、この品川区に集まっているわけですから、ましてそれがこれからどんどん増えていく。でも、これからのことを考えていくと、やはりもう一歩踏み込んだ安全対策とか、アウトソーシングということを勉強させていただきましたけれども、最終的には、外に向かって品川区の最終的なデータの集積場所を、二重、三重、四重にもつくっていくべきと考えますが、いかがでしょうか。","respondent":"田中情報システム課長","answer":"それを考えますと、できるかというと、費用対効果を考えると、なかなか難しいところがあります。ただ、最後にありましたアウトソーシングにつきましては、今後の大きな課題ですので、計画化するよう平成１５年度の中で検討していくつもりです。","voiceIndex":229,"id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問","question":"2,７００万円のアウトソーシングという答弁が、今ありましたけれども、とりあえずはその方向で進んでいっていいと思うんですが、将来的な構想の中で、例えば、今ある品川区役所のシステムそのものを別なところに移して完全に二重化していくとか、オンラインバックアップシステムというのを勉強しましたけれども、そういうようなものをとっていくとか、要するに、区役所以外のもっと安全な場所に。","respondent":"田中情報システム課長","answer":"今ある大きな基本的な住民情報系のシステム等については、再構築して、民間のそういうデータセンターのサービス等を利用する方向で検討していきたいと思っています。","voiceIndex":231,"id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問","question":"私の質問の本意からすれば、セキュリティといいましょうか、安全対策を十分とるですので、理想は理想しても、費用対効果の中で検討をしてくださいますように、お願いしておきます。それと同じように、今、都会でできるんじゃないでしょうかということを思いながら質問しております。質問の観点としては、品川区の持っている情報と消防署の間との連携を十分にとるべきと考えますが、いかがでしょうか。","respondent":"久保田防災課長","answer":"いずれにしましても、これまでもやっておりますけれども、これからもふれあいサポート活動の中での連携ということもありますので、消防署、警察とも連携を密にして、必要な資料のデータ等については、情報交換を密にしていきたいと考えております。","voiceIndex":233,"id":"exchange-094"},{"speaker":"伊藤委員","kind":"質問","question":"今、お話があったように、データはいっているわけじゃないですか。防災対策会議とか、防災会議があるわけですから、そこの中で十分に議論をしていけば、例えば火事のときに、いちいちお願いして助けてもらう人はいないはずなんです。だから、そういうことを考えていけば、今、データがあるわけですから、もう一つ踏み込んでいけばできるんじゃないかと思うんですが、いかがでしょうか。","respondent":"久保田防災課長","answer":"情報の交換を密にしていくという点におきましては、そういうような検討も、今後必要かなと考えています。","voiceIndex":235,"id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問","question":"検討はいいんですけれども、こういうことを公務員同士で話し合って、一つのシステム化していく作業というのは、どうしてこう遅いんでしょうかね。もう一つ踏み込んで、例えば品川区のほうから各消防署へ連絡をして、データベースを構築していく考えがおありでしょうかとか、そういうふうに親切心でもいいから、なぜないんでしょうかと思うんですが、いかがでしょうか。","respondent":"太川区民生活事業部長","answer":"今後につきましては、こういう状況ですので、今後、ふれあいサポートのほうも積極的に進めていくという前提に立ってありますので、やはり個人情報の部分は一歩踏み込んで、私どもの各機関との連携を深めてまいります中で作成して、把握してまいりたいと思ってありますので。","voiceIndex":237,"id":"exchange-096"},{"speaker":"金高委員","kind":"質問・要望","question":"私は、１５７ページの自衛隊員募集事務費についてと、１８０ページの外国人登録費につきまして、２点ばかりお伺いをします。この費用で４万4,０００円が国の委託金として来ているわけですが、この支出の項目を見ますと、４万4,０００円が計上されているわけでありますけれども、実際には国庫委託金という形になっております。なぜ、全額計上していないのか、その点を示していただきたいと思います。","respondent":"宮地区民課長","answer":"７万4,０００円が４万4,０００円ということで、４万4,０００円が実際に募集事務をする際の事務費になってあります。残りの部分は、職員が携わっている分ということで、職員費として取っているものです。","voiceIndex":240,"id":"exchange-097"},{"speaker":"金高委員","kind":"質問・要望","question":"非常に簡単な答弁でございまして、ありがとうありますと言っていいのかどうかですけれども、この募集に関しまして、よく町会の掲示板であるとか、ふれあいの掲示板等に自衛隊募集のポスターであるとか、小さな申込みのはがきというのが張ってあるわけです。実際にこの部分でいきますと、募集費用ということですから、４万4,０００円で募集費用が１年間できるのかというのは非常に疑問な点があるんです。","respondent":"宮地区民課長","answer":"平成１４年度は、８月１日、９月１日、１２月１日という形で、広報を通じまして募集しまして、平成１４年度で実際に試験を受けられた方は１３５名、入隊は１１名ということで、広報の効果はかなり出ております。","voiceIndex":242,"id":"exchange-098"},{"speaker":"金高委員","kind":"質問","question":"続きまして、１８０ページの外国人登録費につきまして、お伺いします。結婚、留学、あるいはビジネス、それぞれあると思いますけれども、登録をするということは、やはり日本人であれば、戸籍とか住民基本台帳というふうになると思うんですが、登録することによって、それらの外国の方々がどのような権利を得る、またそれに反対する義務が生じるのか、それも含めて、お伺いいたします。","respondent":"冨田戸籍住民課長","answer":"登録による権利、義務の関係ですけれども、登録は義務ということになっております。日本にお出でになったときには、９０日以上滞在するということであれば、必ず届出ることになっております。これは、外国の方の義務になっております。","voiceIndex":244,"id":"exchange-099"},{"speaker":"金高委員","kind":"質問","question":"ただ単に来て、９０日以上滞在しますからどうですかというふうにはいかないと思うんですが、先ほどの基準として、結婚、留学、ビジネス、あるいはそれ以外に何か登録するに当たっての基準ということをお尋ねしたわけですので、その辺をもう一度お知らせ願いたい。","respondent":"冨田戸籍住民課長","answer":"外国人登録は、逆に、９０日以内の滞在ということであれば、登録の義務はなくなるということです。９０日以上に及ぶものであれば登録しなければならない。登録の基準ということではなくて、９０日以上いれば登録をする義務が発生するということです。","voiceIndex":246,"id":"exchange-100"},{"speaker":"金高委員","kind":"質問","question":"そうしますと、９０日以上ということで、国の関係でありますから、当然、日本に観光で９０日以上ということは考えられないわけでありますけれども、ややもすると、外国の方が来て、観光で入国してそのままドロンしてしまったというケースも多々発生すると思います。実際には、大変低い歳出が計上されております。これがまたどういうふうになっているか、その辺をお聞かせ願いたいと思います。","respondent":"冨田戸籍住民課長","answer":"最初に不法残留の件だと思いますけれども、昨年の１月１日現在なんですけれども、日本には１７７万人余の外国の方が登録されておりますけれども、そのうちの１２％、２２万人ほどが不法残留ということで、入管のほうではそういった報告をしています。","voiceIndex":248,"id":"exchange-101"},{"speaker":"金高委員","kind":"質問","question":"そうしますと、人件費等も含めての委託金ということで、国のほうから非常に手厚く来ているということで認識をさせていただきました。あまりにも、非常に高い費用の差があったものですから、その点を質問させていただいたわけです。ありがとうございました。警察の対応だと思いますけれども、どのように思っているのか、それも含めてお願いしたいと思います。","respondent":"長田地域活動課長","answer":"こういった部分は、大変警察のほうも対策をかなりの部分とってございまして、先ほど申し上げましたとおり、犯罪件数としては、かなり減ってきているという状況です。","voiceIndex":250,"id":"exchange-102"},{"speaker":"金高委員","kind":"質問・要望","question":"正式に登録してあるわけですから。しかし、実際に不法滞在をしながら、不良外人によるそういうような犯罪等が起これば、ほんとうに市民生活をしている善良な外国の方にも大いに迷惑をかけると思いますので、その辺も、今後やはり地域のほうと連絡を取り合って、しっかりと品川区のほうの対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-103"},{"speaker":"辻委員","kind":"質問・要望","question":"簡単にお伺いします。これは、場所にもよるんです。これは調べていただきたいと思いますので、この辺をぜひ、今回の改善の中でお願いしたいと思うんですけれども、その辺をお聞かせいただきたい。それから、歩きたばこについてちょっとお伺いしたいと思っています。ＣＡＴＶについて伺いますけれども、またそれは追ってやります。それから、区民カードについても、時間があればやりたいと思っています。","respondent":"西島経理課長、宮地区民課長、長田地域活動課長","answer":"私ども、ドコモのほうに連絡を取りまして、アンテナが設置できないのかというお話をしたところ、ドコモのほうでは、一般的には。奨学金につきまして、返済について訪問の督促を強化するということで、緊急地域雇用対策の補助金を使いまして、債権の回収のベテラン２人を雇いまして。歩きたばこに関する過料の問題ですけれども、従来、平成９年からは、どちからというとマナーに訴えるような活動をしてきたという中と。","voiceIndex":254,"id":"exchange-104"},{"speaker":"辻委員","kind":"質問","question":"携帯電話のほうは、ぜひお願いしたいと思います。その辺は技術的に研究していただければと思います。庁内に来るお客さんもちょっと不便しているような声を聞きます。放置自転車は過料という形をとれないんですか、理論的に、法的に考えてみたときに。別にまちづくり事業部に聞いているわけではなくて、純粋にどうですか。ほんとうは、その上にプラスして過料というものはどうなんですか。考え方です。","respondent":"古川総務課長","answer":"ただし、この過料を、どういう場合にどういうふうにその条例の中で定めるか、これはまたそれぞれの考え方があろうかと考えています。","voiceIndex":258,"id":"exchange-105"},{"speaker":"辻委員","kind":"質問","question":"この辺は、これから有料駐輪場というのをつくっていくわけですよ。今度、不動前にも保管場所とができるじゃないですか。その辺の中で、もう１回、根本的に問い直して事業自身をどうなんだという根っこの部分からやっていく必要があると思うんですよ。というのは、今回の過料という部分について、どこまで論議されたかというのをお聞きしたいと思うんですけれども、端的にお願いします。","respondent":"長田地域活動課長","answer":"それに対します対応ですけれども、放置自転車のほうは、保管をして、その必要経費分をいただくという方法で解決が図れるかと思うんですけれども、たばこのほうは、なかなか過料にかわる処分というか、部分が科せられないというようなことがありまして、今回。","voiceIndex":260,"id":"exchange-106"},{"speaker":"辻委員","kind":"確認","question":"わかりました。これは、それで結構です。時間ないんで、ちょっと。もう一つは、区民カードの事業が、今年度からスタートします。それで、これの位置づけというのはどういう形になっているんでしょうか。本人の確認に関する条例というものについてとの関係で、ちょっとお伺いします。","respondent":"冨田戸籍住民課長","answer":"区民カードにつきましては、今回、本人確認に関する条例について提案しておりますので、本人確認を徹底する場合に、手段として、写真つきの免許証等をお持ちでない方が相当数いらっしゃるので、そういった方々に必要な書類としてお持ちいただくようにということで載せたものです。","voiceIndex":262,"id":"exchange-107"},{"speaker":"辻委員","kind":"意見","question":"要するに、正規のきちっとしたものなのかどうかということですよね。オーソライズされているのかどうかということになっちゃうと、ここでいうと免許証とかそういうものは第３条第１項にぴしっと書いてあるんです。ところが、第３条第２項になってくると、健康保険証とか社員証とか、そういうのだったら「推定させる」という形になっているんです。","respondent":"冨田戸籍住民課長","answer":"条例案で言えば、第３条第１項ですか、官公署発行の身分証明証の部分です。推定書類ですけれども、この場合には、それのみではちょっと不十分ということで、聴聞といいますか、若干の質問をさせていただいてフォローするような形にしております。","voiceIndex":264,"id":"exchange-108"},{"speaker":"辻委員","kind":"質問","question":"今言った第３条第１項の中で、要するに官公庁の発行する資格証明書に当たるということでよろしいわけですね。今度、オプションとしては、住基カードでない区民カードを使えると言っていた。中身についてはいいですけれども、まず、写真つきで、第３条第１項に該当する形で住基カードを発行するという形で見ていいかどうか。","respondent":"冨田戸籍住民課長","answer":"はっきりは断定できないんですけれども、一応、選択制ということで聞いていますので、写真つきに限定するのは難しいかなと、現在のところ考えております。","voiceIndex":266,"id":"exchange-109"},{"speaker":"辻委員","kind":"確認","question":"じゃ、その場合に、写真がついてない住基カードというのは、ここで言うと、どういう意味になっちゃいますか。そのときに私が思ったのは、それだったら、形がおかしいじゃないですかということで、その辺を確認したかったんです。","respondent":"冨田戸籍住民課長","answer":"国のほうも、案内の中で、写真つきでないものは身分証明証としては使えないという意味の話をしてきております。","voiceIndex":268,"id":"exchange-110"},{"speaker":"辻委員","kind":"提案","question":"住基カードというのは、ネット上の話ですから、顔を見るわけにいかない部分があるからという別の次元の役割があるわけですけれども、同じ発行するんだったら、今、言ったように証明書としても使えるようにやっていけばいいんじゃないかと提案しているわけです。選べるというのは、確かに案の段階でもわかっているんです。でも、それは区としては、ぜひ訴えてもらいたいということを要望しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":270,"id":"exchange-111"},{"speaker":"北野委員","kind":"質問","question":"私は、３点、質問します。１５９ページのふれあいサポート推進事業、１６５ページのインターネット等経費、インターネット品川区ホームページ、１６９ページの防災行政無線管理費で、携帯電話一斉連絡・相互通話システムについてお伺いいたします。ふれあいサポート推進事業について伺いますが、こちらでは、地域センターでふれあいサポート活動会議が設置されていますが、活動内容をお伺いいたします。","respondent":"長田地域活動課長","answer":"各地区における内容ですけれども、大体１回目は新しい委員にお出でいただくわけですので、区として、どういったことをふれあいサポート活動の中で考えているのかというようなこととともに、参加いただいた委員のそれぞれ所属する団体、あるいは個人のボランティアも含めて。","voiceIndex":272,"id":"exchange-112"},{"speaker":"北野委員","kind":"質問","question":"これからというか、持たれているということでは、課題と役割ということが確かにあります。そしてまた、世論調査の中では、「ふれあいサポート活動について、どういうことをあなたはご存じですか」という中でも、項目として、ボランティアとか、高齢者の配食とかは掲載されていますけれども、子育て最中の方の支援についてという内容は掲載されていないんです。","respondent":"長田地域活動課長","answer":"そういった中では、子育てセンターもできたわけですので、そういったご相談をいただいたときには、子育て部門の、例えば保育課ですとか、児童課ですとか、そういったところの紹介をしてまいりたいと考えているところです。","voiceIndex":274,"id":"exchange-113"},{"speaker":"北野委員","kind":"質問・要望","question":"地域福祉の中では、高齢者はもちろんですけれども、障害者も、子育ても含まれていますので、ぜひ、そういう形でボランティアの方を募るということもそうですけれども、よい形で進めていっていただきたいと思います。時間がないので、次へ進みます。次はインターネット等経費についてです。どのようなことを刷新されるのか、そのことについてお伺いいたします。","respondent":"山田広報広聴課長","answer":"いわゆる４枠、右端のほうに区内の企業、または教育機関の広告を載せていく予定があります。その全体のバランスを合わせまして、なおいろいろなご意見が来ておりますので、総合的に見直しを図ってトップページを変えていきたいと考えています。","voiceIndex":276,"id":"exchange-114"},{"speaker":"北野委員","kind":"質問","question":"確かに、トップページは変わっていまして、左側に各事業部も書いてあります。しかし、アクセスしたときに、見たいものがほんとうに出てこないんですね。もう少し事業部でどういう内容をしているかというものをも細かく書くべきではないのかなと。私たちはわかりますけれども、所管がわからない方が多いのではないかなと思いますけれども、その点については、いかがでしょうか。","respondent":"山田広報広聴課長","answer":"細かい事業まではなかなか入っていないわけです。各事業部のところのクリックという部分でできるものなのか、どうなのか、１回目のクリックでうまく画面が出せるかどうかは、工夫をしながら検討してまいりたいと思います。","voiceIndex":278,"id":"exchange-115"},{"speaker":"北野委員","kind":"質問","question":"防災計画のほうですけれども、携帯電話で一斉ということで、実際にこちらのほうから、逆に地域の生情報を各町会長から直接もらうということですけれども、今までは、そういうことはされていたんでしょうか。そのことについて、お伺いしたいと思います。","respondent":"久保田防災課長","answer":"今回のは、本部と直接つながってありますので、そういう点では、より情報が伝わりやすいんではないかと考えています。","voiceIndex":280,"id":"exchange-116","title":"町会・自治会支援"},{"speaker":"北野委員","kind":"質問","question":"今回のは本部とつながっているということで、これも２０４カ所の町会に配付されるわけですよね。それの受け手のほうはどういう体制になるんでしょうか。せっかく生の情報をいただいても、それがうまく処理できなければ、生の情報を皆さんにお返しするということができないと思いますけれども、その点について、お伺いします。","respondent":"久保田防災課長","answer":"これまでも、水防関係につきましては、ごくごく限られた町会長からの問い合わせということでございましたので、そういう経験から言うと、十分に対応できるだろうと考えています。","voiceIndex":282,"id":"exchange-117"},{"speaker":"北野委員","kind":"質問・要望","question":"ほんとうは、実際に稼働してみなきゃわからない。しかし、あってはいけないようなシステムでもあるわけです。日常天災ということがどのような形で起こるかわかりませんので、そういう情報の共有というところでは、的確なもので判断していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-118"},{"speaker":"築舘委員","kind":"質問・要望","question":"１５７ページの水と緑の市町村との交流事業ということで、山北、早川とあります。平成１４年度の事務事業評価といたしましては、山北のほうはＣということで、効果を分析した上で事業の見直しを検討するということです。それからあともう１点は、１５９ページ、先ほどからお２人の方から出ておりますふれあいサポート推進事業です。それをお聞きしたいということです。","respondent":"宮地区民課長、長田地域活動課長","answer":"さまざまな事業を取り替えながらやっていく中で、より魅力をアップしていきたいと考えておりまして、見直した結果、こちらのほうも１３５万円の減で、これから実施できる予定です。ふれあいサポート活動の体制の整備ですけれども、実は、私ども、これを実施していく中で、少し地域センターの力量をアップしていこうと考えています。","voiceIndex":286,"id":"exchange-119"},{"speaker":"築舘委員","kind":"質問・要望","question":"要するに、何かあったときに、それでは責任はどこですかと言ったら、やはり地域センターのところに来るわけですから、子育てまで手が伸ばせないというような答弁じゃまずいわけです。だけど、高齢者も子どもも地域なんですから、同じ地域で一体化してお互いに助け合おうということをやっているんですから、そこの発想をしっかりと、ただ単なる福祉ということでも困るわけですよ。","respondent":"宮地区民課長、長田地域活動課長","answer":"そういうことをこれからもどんどん続けていく中で、ふるさととして民間の中での交流が進んでいくように力を出していきたいと思います。心の交流ということで進めていきたいと思います。ふれあいサポート活動についてですけれども、先ほど、私、地域の中の地域センターであるべきだと申し上げました。ですから、そういう意味では、まさに委員ご指摘のとおりだと認識をしています。","voiceIndex":289,"id":"exchange-120"},{"speaker":"築舘委員","kind":"質問・要望","question":"山北と早川町のほう、またさらに心の交流、内容の密度の濃いものをしていただきたいということを要望いたしておきます。ですから、そこを考えていただきたいということで、ちょっと要望しておきます。そういう方々になると、自分が困ったときには困っちゃうわけですけれども、ふだん困らないものですから、自分だけは楽しようと思っちゃうわけですね。その点、１点、お聞かせください。","respondent":"長田地域活動課長","answer":"私ども、この事業を進めていくについて、先ほどもちょっと申し上げましたけれども、町会、自治会はじめさまざまな地域の団体、あるいは、個人のボランティアといった多くの方々に参加をしていただくことが必要だと思っているところです。","voiceIndex":292,"id":"exchange-121"},{"speaker":"鶴委員","kind":"提案","question":"１５分しかない中で、ちょっぴり多くのことをお伺いいたしますので、できれば、答弁は簡潔にしていただけると幸いに思います。５区のそれぞれの死亡者は約2,０００人ぐらいずつでしょうか。それから、外国人の登録の問題ですけれども、外国人登録法を廃止して、地方自治法第１０条が定める地方自治体の住民であることを確認し、住民基本台帳法に基づく住民登録をするように法改正を求める動きがありますね。","respondent":"桑村人事課長、長田地域活動課長、宮地区民課長、野田口選挙管理委員会事務局長、冨田戸籍住民課長","answer":"ほかのものもいろいろ検討させていただいて、さらに検討してまいりたいと思います。歩きたばこの問題です。職員に関しましては、条例が通りましたときには、徹底した周知を図る予定です。お休みですが、極力休まないでやるということで、友引の日も営業、１月１日、２日のみ休みです。ただ、特にホームページですけれども、インターネットを利用しての選挙運動の広報といったことが、現在、検討されているという状況です。","voiceIndex":295,"id":"exchange-122"},{"speaker":"鶴委員","kind":"質問・要望","question":"在日の外国人の皆さんが、その第１条の目的に管理とうたっているその法律は１２本ですか、そのうち、人を管理すると第１条目的でうたっているのは、入管法と外国人登録法だけですよ、この二つだけです。そういうことになる。そういう立場から、人権啓発課はどういうふうに受けとめているか。何が恥ずかしいですか。何とか革新、何とか見解発表と、そこにそのチラシが入っているんですから、どうですか。","respondent":"野田口選挙管理委員会事務局長、阿部人権啓発課長","answer":"選挙管理委員会とすれば、文書図画につきましては、撤去命令の権限しかございませんけれども、もし、私どもに指導というお尋ねがあれば、先ほどの事務所の案内を不特定多数に配布するということであれば、売名行為。日本国憲法でも、明らかに日本国民にのみ認められているもの以外の基本的人権についても、等しく外国人にも認められているという状況ですので、外国人との共生についても、なお一層啓発に努めていきたいと考えています。","voiceIndex":301,"id":"exchange-123"},{"speaker":"鶴委員","kind":"意見","question":"外国人の問題については、また別の機会にしたいと思います。いずれにいたしましても、きれいな選挙をやりたいものだと、ルールを守っていくことが大事じゃないかと、それが信頼を勝ち取ることになるというふうに、私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":304,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"短く３点、お伺いをいたします。２３区横並びでやっているのだとは思いますけれども、〔「違う」と呼ぶ者あり〕違うんですか、どこでやっているのかお聞きしたいと思います。インターネットの中の書き込み、２チャンネルというんでしょうか、あれは区長、区議会議員選挙で、区議会議員の名前まで出ている。その点、選挙管理委員会として、どういう見解を持っているのかお聞きいたします。","respondent":"上山区民生活事業部副参事、野田口選挙管理委員会事務局長","answer":"きゅりあんですけれども、昨年、大ホールを中心といたしまして改修工事を実施いたしました。公職選挙法上、インターネットの選挙運動につきましては、先ほどの答弁でも申し上げましたけれども、現在、検討中ですけれども、ホームページにつきましては、選挙運動にわたらない限り。","voiceIndex":306,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"先ほどの２チャンネルの話は、ご答弁がなかったような気がするんですけれども、やはりこの辺も何か、全国的に選挙管理委員会、選挙を管理するということで、統一的な見解を求めるような運動なんかは、今、しているんでしょうか。その辺をお聞きしたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味では、確認団体以外の政治団体につきましては、政治活動ができないです。","voiceIndex":309,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり、これからのインターネット、ホームページはどんどん利用されていく中で、選挙管理委員会としても、これがいいのか、悪いのか、検討していって、新しいことに対応する選挙管理委員会ということで頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-127"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=806#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":110521,"voices":312}}]);
